QT_ISI(11,{"1328":["(Sesungguhnya jalan untuk menyalahkan itu hanyalah terhadap orang-orang yang meminta izin kepadamu) untuk tidak ikut berangkat berjihad (padahal mereka itu orang-orang kaya. Mereka rela berada bersama-sama orang-orang yang tidak ikut berperang dan Allah telah mengunci mati hati mereka, maka mereka tidak mengetahui) akibat perbuatan mereka.",[["۞ إِنَّمَا","Hanya"],["ٱلسَّبِيلُ","jalan (salahkan)"],["عَلَى","(berada) di atas"],["ٱلَّذِينَ","orang yang"],["يَسْتَـْٔذِنُونَكَ","minta izin kamu"],["وَهُمْ","sedangkan mereka"],["أَغْنِيَآءُ ۚ","(adalah) kaya"],["رَضُوا۟","Mereka (berpuas hati)."],["بِأَن","kepada"],["يَكُونُوا۟","jadilah"],["مَعَ","dengan"],["ٱلْخَوَالِفِ","mereka yang tinggal di belakang"],["وَطَبَعَ","dan Allah mengunci mati"],["ٱللَّهُ","dan Allah mengunci mati"],["عَلَىٰ","[pada]"],["قُلُوبِهِمْ","hati mereka"],["فَهُمْ","jadi mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"1329":["(Mereka mengemukakan uzurnya kepada kalian) untuk tidak pergi berperang (apabila kalian telah kembali kepada mereka) dari medan perang (Katakanlah) kepada mereka (\"Janganlah kalian mengemukakan uzur, kami tidak percaya lagi kepada kalian) kami sudah tidak mempercayai lagi kalian (karena sesungguhnya Allah telah memberitahukan kepada kami di antara berita-berita rahasia kalian) Allah telah memberitahukan kepada kami tentang hal-ihwal kalian. (Dan Allah serta Rasul-Nya akan melihat pekerjaan kalian kemudian kalian dikembalikan) melalui dibangkitkan dari dalam kubur (kepada Yang Mengetahui yang gaib dan yang nyata) yakni Allah (lalu Dia memberitahu kepada kalian apa yang telah kalian kerjakan.\") maka Dia membalasnya kepada kalian.",[["يَعْتَذِرُونَ","Mereka akan membuat alasan"],["إِلَيْكُمْ","kepada kamu"],["إِذَا","apabila"],["رَجَعْتُمْ","kamu (telah) kembali"],["إِلَيْهِمْ ۚ","kepada mereka"],["قُل","Katakanlah"],["لَّا","Jangan"],["تَعْتَذِرُوا۟","buat alasan"],["لَن","tidak pernah"],["نُّؤْمِنَ","kita akan beriman"],["لَكُمْ","kamu"],["قَدْ","Sesungguhnya"],["نَبَّأَنَا","Allah (telah) memberitahu kita"],["ٱللَّهُ","Allah (telah) memberitahu kita"],["مِنْ","daripada"],["أَخْبَارِكُمْ ۚ","berita kamu"],["وَسَيَرَى","dan Allah akan melihat"],["ٱللَّهُ","dan Allah akan melihat"],["عَمَلَكُمْ","perbuatan kamu"],["وَرَسُولُهُۥ","dan Rasul-Nya"],["ثُمَّ","Kemudian"],["تُرَدُّونَ","kamu akan dibawa balik"],["إِلَىٰ","kepada"],["عَـٰلِمِ","(yang) Maha Mengetahui"],["ٱلْغَيْبِ","(dari) yang ghaib"],["وَٱلشَّهَـٰدَةِ","dan yang dilihat"],["فَيُنَبِّئُكُم","kemudian Dia akan memberitahu kamu"],["بِمَا","tentang apa"],["كُنتُمْ","kamu pernah (untuk)"],["تَعْمَلُونَ","lakukan"]]],"1330":["(Kelak mereka akan bersumpah kepada kalian dengan nama Allah, apabila kalian kembali) yakni pulang (kepada mereka) dari medan perang Tabuk untuk menunjukkan bahwa mereka benar-benar mempunyai alasan yang tepat sewaktu mereka tidak ikut berangkat (supaya kalian berpaling dari mereka) artinya supaya tidak mencela perbuatan mereka itu. (Maka berpalinglah dari mereka karena sesungguhnya mereka itu adalah najis) najis karena batin mereka kotor (dan tempat mereka Jahanam sebagai balasan atas apa yang telah mereka kerjakan.)",[["سَيَحْلِفُونَ","Mereka akan bersumpah"],["بِٱللَّهِ","oleh Allah"],["لَكُمْ","kepada kamu"],["إِذَا","apabila"],["ٱنقَلَبْتُمْ","kamu balik"],["إِلَيْهِمْ","kepada mereka"],["لِتُعْرِضُوا۟","supaya kamu berpaling"],["عَنْهُمْ ۖ","daripada mereka"],["فَأَعْرِضُوا۟","Jadi berpalinglah"],["عَنْهُمْ ۖ","daripada mereka"],["إِنَّهُمْ","sesungguhnya, mereka"],["رِجْسٌۭ ۖ","(adalah) najis"],["وَمَأْوَىٰهُمْ","dan tempat tinggal mereka"],["جَهَنَّمُ","(ialah) Neraka"],["جَزَآءًۢ","suatu balasan"],["بِمَا","bagi apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَكْسِبُونَ","peroleh"]]],"1331":["(Mereka akan bersumpah kepada kalian agar kalian rida kepada mereka. Tetapi jika sekiranya kalian rida kepada mereka, maka sesungguhnya Allah tidak rida kepada orang-orang yang fasik itu) artinya Allah tidak rela kepada mereka dan kerelaan kalian kepada mereka sedikit pun tidak akan bermanfaat buat mereka, karena Allah telah murka kepada mereka.",[["يَحْلِفُونَ","Mereka bersumpah"],["لَكُمْ","kepada kamu"],["لِتَرْضَوْا۟","supaya kamu redha"],["عَنْهُمْ ۖ","bersama mereka"],["فَإِن","Tetapi jika"],["تَرْضَوْا۟","kamu redha"],["عَنْهُمْ","bersama mereka"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","(adalah) tidak berpuas hati"],["يَرْضَىٰ","(adalah) tidak berpuas hati"],["عَنِ","dengan"],["ٱلْقَوْمِ","manusia"],["ٱلْفَـٰسِقِينَ","(yang) durhaka"]]],"1332":["(Orang-orang Arab itu) yaitu penduduk daerah badui (lebih sangat kekafiran dan kemunafikannya) daripada penduduk daerah perkotaan; karena penduduk daerah badui berwatak keras dan kasar serta mereka jauh dari mendengarkan Alquran (dan lebih wajar) lebih patut (tidak mengetahui hukum-hukum yang diturunkan Allah kepada Rasul-Nya) berupa hukum-hukum dan syariat-syariat. Huruf allaa asalnya terdiri dari an dan laa kemudian keduanya digabungkan, sehingga jadilah allaa. (Dan Allah Maha Mengetahui) tentang makhluk-Nya (lagi Maha Bijaksana) di dalam mengatur penciptaan mereka.",[["ٱلْأَعْرَابُ","Orang Badwi"],["أَشَدُّ","(adalah) lebih kuat"],["كُفْرًۭا","(dalam) ketidakpercayaan"],["وَنِفَاقًۭا","dan kemunafikan"],["وَأَجْدَرُ","dan lebih berkemungkinan"],["أَلَّا","itu tidak"],["يَعْلَمُوا۟","mereka tahu"],["حُدُودَ","(the) had"],["مَآ","apa"],["أَنزَلَ","Allah (telah) mewahyukan"],["ٱللَّهُ","Allah (telah) mewahyukan"],["عَلَىٰ","kepada"],["رَسُولِهِۦ ۗ","RasulNya"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌ","Maha Mengetahui"],["حَكِيمٌۭ","Maha Bijaksana"]]],"1333":["(Di antara orang-orang Arab badui itu ada orang yang memandang apa yang dinafkahkannya) di jalan Allah (sebagai suatu kerugian) ketekoran dan kerugian sebab ia tidak mengharapkan akan pahalanya melainkan menginfakkannya karena rasa takut; mereka adalah Bani Asad dan Bani Ghathafan (dan menanti-nanti) malapetaka menimpa kalian sehingga ia bebas dari kalian (merekalah yang akan ditimpa marabahaya) dapat dibaca as-suu` dan dapat pula dibaca as-sau`, artinya azab dan kebinasaan itu justru akan menimpa mereka sendiri bukannya menimpa kalian. (Dan Allah Maha Mendengar) akan semua ucapan hamba-hamba-Nya (lagi Maha Mengetahui) perbuatan-perbuatan mereka.",[["وَمِنَ","Dan antara"],["ٱلْأَعْرَابِ","orang badwi"],["مَن","(adakah dia) siapa"],["يَتَّخِذُ","mengambil"],["مَا","apa"],["يُنفِقُ","dia berbelanja"],["مَغْرَمًۭا","(sebagai) kerugian"],["وَيَتَرَبَّصُ","dan dia menunggu"],["بِكُمُ","bagi kamu"],["ٱلدَّوَآئِرَ ۚ","giliran (nasib)"],["عَلَيْهِمْ","atas mereka"],["دَآئِرَةُ","(akan) giliran"],["ٱلسَّوْءِ ۗ","(dari) kejahatan"],["وَٱللَّهُ","Dan Allah"],["سَمِيعٌ","(adalah) Yang Maha Mendengar"],["عَلِيمٌۭ","Maha Mengetahui"]]],"1334":["(Dan di antara orang-orang Arab badui itu ada orang-orang yang beriman kepada Allah dan hari kemudian) seperti kabilah Juhainah dan kabilah Muzayyanah (dan menjadikan apa yang ia infakkan) di jalan Allah (sebagai amal taqarrub) maksudnya mendekatkan diri kepada-Nya (di sisi Allah dan) sebagai jalan untuk (memperoleh selawat) yakni doa-doa (Rasul) kepadanya. (Ketahuilah, sesungguhnya nafkah itu) artinya nafkah mereka itu (merupakan amal taqarrub) dapat dibaca qurubaatun dan dapat pula dibaca qurbatun (bagi mereka) di sisi-Nya. (Kelak Allah akan memasukkan mereka ke dalam rahmat-Nya) yaitu surga-Nya. (Sesungguhnya Allah Maha Pengampun) kepada orang-orang yang taat kepada-Nya (lagi Maha Penyayang) terhadap mereka yang taat.",[["وَمِنَ","Tetapi antara"],["ٱلْأَعْرَابِ","orang badwi"],["مَن","(adakah dia) siapa"],["يُؤْمِنُ","beriman"],["بِٱللَّهِ","kepada Allah"],["وَٱلْيَوْمِ","dan Hari"],["ٱلْـَٔاخِرِ","yang Terakhir"],["وَيَتَّخِذُ","dan mengambil"],["مَا","apa"],["يُنفِقُ","dia berbelanja"],["قُرُبَـٰتٍ","(sebagai) cara menghampiri"],["عِندَ","dengan"],["ٱللَّهِ","Allah"],["وَصَلَوَٰتِ","dan berkat"],["ٱلرَّسُولِ ۚ","(dari) Rasul"],["أَلَآ","Lihatlah"],["إِنَّهَا","Sesungguhnya, ia"],["قُرْبَةٌۭ","(adalah) cara mendekatkan diri"],["لَّهُمْ ۚ","bagi mereka"],["سَيُدْخِلُهُمُ","Allah akan mengakui mereka"],["ٱللَّهُ","Allah akan mengakui mereka"],["فِى","kepada"],["رَحْمَتِهِۦٓ ۗ","KerahimanNya"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"1335":["(Orang-orang yang terdahulu lagi yang pertama-tama masuk Islam di antara orang-orang Muhajirin dan Ansar) mereka adalah para sahabat yang ikut perang Badar atau yang dimaksud adalah semua para sahabat (dan orang-orang yang mengikuti mereka) sampai hari kiamat (dengan baik) dalam hal amal perbuatannya. (Allah rida kepada mereka) melalui ketaatan mereka kepada-Nya (dan mereka pun rida kepada Allah) rida akan pahala-Nya (dan Allah menyediakan bagi mereka surga-surga yang mengalir sungai-sungai di bawahnya) menurut suatu qiraat lafal tahtahaa dibaca dengan memakai huruf min sebelumnya sehingga bacaannya menjadi min tahtihaa (mereka kekal di dalamnya selama-lamanya. Itulah kemenangan yang besar).",[["وَٱلسَّـٰبِقُونَ","Dan para pendahulu"],["ٱلْأَوَّلُونَ","yang pertama"],["مِنَ","antara"],["ٱلْمُهَـٰجِرِينَ","golongan berhijrah"],["وَٱلْأَنصَارِ","dan para penolong"],["وَٱلَّذِينَ","dan orang yang"],["ٱتَّبَعُوهُم","mengikuti mereka"],["بِإِحْسَـٰنٍۢ","dalam kebenaran"],["رَّضِىَ","Allah redha"],["ٱللَّهُ","Allah redha"],["عَنْهُمْ","bersama mereka"],["وَرَضُوا۟","dan mereka redha"],["عَنْهُ","dengan Dia"],["وَأَعَدَّ","Dan Dia telah menyediakan"],["لَهُمْ","bagi mereka"],["جَنَّـٰتٍۢ","Taman-taman"],["تَجْرِى","mengalir"],["تَحْتَهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["خَـٰلِدِينَ","akan kekal"],["فِيهَآ","di dalamnya"],["أَبَدًۭا ۚ","selama-lamanya"],["ذَٰلِكَ","Itu"],["ٱلْفَوْزُ","(ialah) kejayaan"],["ٱلْعَظِيمُ","yang hebat"]]],"1336":["(Di antara orang-orang yang di sekeliling kalian) hai penduduk Madinah (dari kalangan orang-orang Arab badui ada orang-orang munafik) seperti orang-orang kabilah Aslam, kabilah Asyja` dan kabilah Ghiffar (dan juga di antara penduduk Madinah) ada orang-orang munafik pula. (Mereka keterlaluan dalam kemunafikannya) artinya kemunafikan mereka telah mendalam dan sudah mengakar di hati mereka. (Kamu tidak mengetahui mereka) hai Muhammad (tetapi Kamilah yang mengetahui mereka. Nanti mereka akan Kami siksa dua kali) dengan terungkapnya kemunafikan mereka, atau dibunuh di dunia dan disiksa di alam kubur (kemudian mereka akan dikembalikan) di akhirat nanti (kepada azab yang besar) yaitu siksa neraka.",[["وَمِمَّنْ","Dan antaranya"],["حَوْلَكُم","sekeliling kamu"],["مِّنَ","daripada"],["ٱلْأَعْرَابِ","orang badwi"],["مُنَـٰفِقُونَ ۖ","(adalah) orang-orang munafik"],["وَمِنْ","dan (juga) daripada"],["أَهْلِ","orang ramai"],["ٱلْمَدِينَةِ ۖ","(dari) Madinah"],["مَرَدُوا۟","Mereka berterusan"],["عَلَى","dalam"],["ٱلنِّفَاقِ","kemunafikan"],["لَا","tidak"],["تَعْلَمُهُمْ ۖ","kamu mengenali mereka"],["نَحْنُ","Kami"],["نَعْلَمُهُمْ ۚ","[Kami] mengenali mereka"],["سَنُعَذِّبُهُم","Kami akan menghukum mereka"],["مَّرَّتَيْنِ","dua kali"],["ثُمَّ","kemudian"],["يُرَدُّونَ","mereka akan dikembalikan"],["إِلَىٰ","kepada"],["عَذَابٍ","azab"],["عَظِيمٍۢ","yang besar"]]],"1337":["(Dan) ada pula suatu kaum (yang lain) lafal ayat ini menjadi mubtada (mereka mengakui dosa-dosa mereka) karena tidak ikut berangkat ke medan perang. Lafal ayat ini menjadi khabarnya (mereka mencampur-baurkan pekerjaan yang baik) yaitu jihad yang telah mereka lakukan sebelum peristiwa ini atau pengakuan mereka atas dosa-dosa yang telah mereka lakukan; atau dosa-dosa yang lainnya (dengan pekerjaan lain yang buruk) yaitu ketidakikutan mereka dalam berjihad kali ini. (Mudah-mudahan Allah menerima tobat mereka. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang). Ayat ini diturunkan berkenaan dengan apa yang dilakukan oleh Abu Lubabah dan segolongan orang-orang lainnya. Mereka mengikatkan diri mereka di tiang-tiang mesjid, hal ini mereka lakukan ketika mereka mendengar firman Allah swt. yang diturunkan berkenaan dengan orang-orang yang tidak berangkat berjihad, sedangkan mereka tidak ikut berangkat. Lalu mereka bersumpah bahwa ikatan mereka itu tidak akan dibuka melainkan oleh Nabi saw. sendiri. Kemudian setelah ayat ini diturunkan Nabi saw. melepaskan ikatan mereka.",[["وَءَاخَرُونَ","Dan lain-lain"],["ٱعْتَرَفُوا۟","(yang telah) mengakui"],["بِذُنُوبِهِمْ","dosa mereka"],["خَلَطُوا۟","Mereka telah bercampur"],["عَمَلًۭا","suatu perbuatan"],["صَـٰلِحًۭا","soleh"],["وَءَاخَرَ","(dengan) lain"],["سَيِّئًا","(itu) jahat"],["عَسَى","barangkali"],["ٱللَّهُ","Allah"],["أَن","[bahawa]"],["يَتُوبَ","akan berpaling (dalam belas kasihan)"],["عَلَيْهِمْ ۚ","kepada mereka"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌ","Maha Mengasihani"]]],"1338":["(Ambillah sedekah dari sebagian harta mereka, dengan sedekah itu kamu membersihkan dan menyucikan mereka) dari dosa-dosa mereka, maka Nabi saw. mengambil sepertiga harta mereka kemudian menyedekahkannya (dan berdoalah untuk mereka). (Sesungguhnya doa kamu itu menjadi ketenangan jiwa) rahmat (bagi mereka) menurut suatu pendapat yang dimaksud dengan sakanun ialah ketenangan batin lantaran tobat mereka diterima. (Dan Allah Maha Mendengar lagi Maha Mengetahui).",[["خُذْ","ambil"],["مِنْ","daripada"],["أَمْوَٰلِهِمْ","kekayaan mereka"],["صَدَقَةًۭ","sebuah amal"],["تُطَهِّرُهُمْ","menyucikan mereka"],["وَتُزَكِّيهِم","dan menyebabkan mereka bertambah"],["بِهَا","olehnya"],["وَصَلِّ","dan memberkati"],["عَلَيْهِمْ ۖ","[ke atas] mereka"],["إِنَّ","Sesungguhnya"],["صَلَوٰتَكَ","berkatmu"],["سَكَنٌۭ","(adalah a) jaminan"],["لَّهُمْ ۗ","bagi mereka"],["وَٱللَّهُ","Dan Allah"],["سَمِيعٌ","(adalah) Yang Maha Mendengar"],["عَلِيمٌ","Maha Mengetahui"]]],"1339":["(Tidakkah mereka mengetahui bahwasanya Allah menerima tobat dari hamba-hamba-Nya dan mengambil) maksudnya menerima (zakat dan bahwasanya Allah Maha Penerima tobat) hamba-hamba-Nya, yakni dengan menerima tobat mereka (lagi Maha Penyayang) kepada mereka. Kata tanya pada awal ayat ini bermakna taqrir; pengertian yang dimaksud ialah untuk menggugah mereka agar mau bertobat dan berzakat atau bersedekah.",[["أَلَمْ","Jangan"],["يَعْلَمُوٓا۟","mereka tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["هُوَ","(ialah) Dia"],["يَقْبَلُ","(Siapa) menerima"],["ٱلتَّوْبَةَ","taubat itu"],["عَنْ","daripada"],["عِبَادِهِۦ","hambanya"],["وَيَأْخُذُ","dan mengambil"],["ٱلصَّدَقَـٰتِ","badan amal"],["وَأَنَّ","dan bahawa"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["ٱلتَّوَّابُ","(ialah) Penerima taubat"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"1340":["(Dan katakanlah) kepada mereka atau kepada manusia secara umum (\"Bekerjalah kalian) sesuka hati kalian (maka Allah dan Rasul-Nya serta orang-orang mukmin akan melihat pekerjaan kalian itu dan kalian akan dikembalikan) melalui dibangkitkan dari kubur (kepada Yang Mengetahui alam gaib dan alam nyata) yakni Allah (lalu diberikan-Nya kepada kalian apa yang telah kalian kerjakan.\") lalu Dia akan membalasnya kepada kalian.",[["وَقُلِ","Dan katakan"],["ٱعْمَلُوا۟","buat"],["فَسَيَرَى","maka Allah akan melihat"],["ٱللَّهُ","maka Allah akan melihat"],["عَمَلَكُمْ","perbuatan kamu"],["وَرَسُولُهُۥ","dan Rasul-Nya"],["وَٱلْمُؤْمِنُونَ ۖ","dan orang-orang yang beriman"],["وَسَتُرَدُّونَ","Dan kamu akan dibawa balik"],["إِلَىٰ","kepada"],["عَـٰلِمِ","(yang) Maha Mengetahui"],["ٱلْغَيْبِ","(dari) yang ghaib"],["وَٱلشَّهَـٰدَةِ","dan yang dilihat"],["فَيُنَبِّئُكُم","kemudian Dia akan memberitahu kamu"],["بِمَا","tentang apa"],["كُنتُمْ","kamu pernah (untuk)"],["تَعْمَلُونَ","lakukan"]]],"1341":["(Dan ada pula orang-orang lain) di antara orang-orang yang tidak berangkat ke medan perang (yang ditangguhkan) dapat dibaca murjauna dan dapat pula dibaca murja'uuna; artinya tobat mereka ditangguhkan (sampai ada keputusan Allah) tentang perihal mereka sesuai dengan kehendak-Nya (adakalanya Allah akan mengazab mereka) seumpamanya mereka dimatikan oleh Allah tanpa sempat bertobat (dan adakalanya Allah akan menerima tobat mereka. Dan Allah Maha Mengetahui) tentang makhluk-Nya (lagi Maha Bijaksana) di dalam melakukan apa yang harus Ia lakukan terhadap mereka. Yang dimaksud dengan mereka ialah ketiga orang yang kedatangannya kepada Nabi saw. telah disebutkan tadi, mereka adalah Murarah bin Rabi', Kaab bin Malik dan Hilal bin Umayyah. Mereka tidak berangkat ke medan perang hanya karena malas dan cenderung kepada hidup yang serba santai dan enak, bukannya karena munafik. Dan mereka tidak mengemukakan uzurnya (alasannya) kepada Nabi saw. seperti halnya yang dilakukan oleh orang-orang lain. Akhirnya perihal mereka ditangguhkan selama lima puluh hari, selama itu mereka hidup diasingkan oleh semuanya sehingga turunlah ayat yang menjelaskan diterimanya tobat mereka.",[["وَءَاخَرُونَ","Dan lain-lain"],["مُرْجَوْنَ","tertunda"],["لِأَمْرِ","kerana perintah Allah"],["ٱللَّهِ","kerana perintah Allah"],["إِمَّا","sama ada"],["يُعَذِّبُهُمْ","Dia akan menghukum mereka"],["وَإِمَّا","atau"],["يَتُوبُ","Dia akan berpaling (dengan rahmat)"],["عَلَيْهِمْ ۗ","kepada mereka"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌ","Maha Mengetahui"],["حَكِيمٌۭ","Maha Bijaksana"]]],"1342":["(Dan) di antara mereka yang munafik itu (ada orang-orang yang mendirikan mesjid) jumlah mereka ada dua belas orang, semuanya orang-orang munafik (untuk menimbulkan kemudaratan) kepada orang-orang mukmin di mesjid Quba (dan karena kekafiran) karena mereka membangun mesjid itu berdasarkan perintah dari Abu Amir seorang rahib, dimaksud supaya menjadi basis pangkalan baginya dan bagi orang-orang yang berpihak kepadanya. Sedang ia (Amir) pergi untuk mendatangkan bala tentara Kaisar Romawi guna memerangi Nabi saw. (dan untuk memecah belah antara orang-orang mukmin) yang biasa salat di mesjid Quba, diharapkan sebagian dari orang-orang mukmin melakukan salat di mesjid mereka (serta menjadi tempat pemantauan) yakni tempat untuk memantau (bagi orang-orang yang memerangi Allah dan Rasul-Nya sejak dahulu) sebelum mesjid dhirar ini dibangun; yang dimaksud adalah Abu Amir tadi dan para pembantunya. (Mereka sesungguhnya bersumpah, \"Tiada lain) (kami menghendaki) dari pembangunan mesjid ini (hanyalah) untuk pekerjaan (yang baik semata.\") yaitu berlaku belas-kasihan terhadap orang-orang miskin dalam musim hujan dan musim panas, serta memberikan tempat persinggahan bagi kaum Muslimin. (Dan Allah menjadi saksi bahwa sesungguhnya mereka itu adalah pendusta) dalam sumpahnya. Mereka pernah meminta kepada Nabi saw. supaya melakukan salat di dalam mesjidnya itu, akan tetapi kemudian turunlah firman Allah berikut ini, yaitu:",[["وَٱلَّذِينَ","Dan orang yang"],["ٱتَّخَذُوا۟","ambil"],["مَسْجِدًۭا","sebuah masjid"],["ضِرَارًۭا","(kerana menyebabkan) kemudaratan"],["وَكُفْرًۭا","dan (untuk) kekufuran"],["وَتَفْرِيقًۢا","dan (untuk) pembahagian"],["بَيْنَ","antara"],["ٱلْمُؤْمِنِينَ","orang yang beriman"],["وَإِرْصَادًۭا","dan (sebagai) stesen"],["لِّمَنْ","untuk sesiapa sahaja"],["حَارَبَ","berperang"],["ٱللَّهَ","(terhadap) Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["مِن","sebelum"],["قَبْلُ ۚ","sebelum"],["وَلَيَحْلِفُنَّ","Dan pasti mereka akan bersumpah"],["إِنْ","Tidak"],["أَرَدْنَآ","kami mahu"],["إِلَّا","kecuali"],["ٱلْحُسْنَىٰ ۖ","yang baik"],["وَٱللَّهُ","Tetapi Allah"],["يَشْهَدُ","menjadi saksi"],["إِنَّهُمْ","sesungguhnya, mereka"],["لَكَـٰذِبُونَ","(adalah) sesungguhnya pendusta"]]],"1343":["(Janganlah kamu berdiri) melakukan salat (dalam mesjid itu selama-lamanya) kemudian Nabi saw. mengirimkan segolongan para sahabatnya guna merobohkan dan membakarnya. Kemudian mereka menjadikan bekas mesjid itu sebagai tempat pembuangan bangkai. (Sesungguhnya mesjid yang didirikan) dibangun dengan berlandaskan kepada pondasi (takwa, sejak hari pertama) yaitu mesjid yang didirikan oleh Nabi saw. sewaktu pertama kali beliau menginjakkan kakinya di tempat hijrahnya itu, yang dimaksud adalah mesjid Quba. Demikianlah menurut penjelasan yang telah dikemukakan oleh Imam Bukhari (adalah lebih berhak) daripada mesjid dhirar itu (kamu salat) untuk melakukan salat (di dalamnya. Di dalamnya ada orang-orang) kaum Ansar (yang ingin membersihkan diri. Dan Allah menyukai orang-orang yang bersih) artinya, Allah akan memberikan pahala kepada mereka. Lafal al-muththahhiriina asalnya ialah al-mutathahhiriina kemudian huruf ta diidgamkan kepada huruf tha yang asal, kemudian jadilah al-muththahhiriina. Ibnu Khuzaimah di dalam kitab sahihnya telah meriwayatkan sebuah hadis melalui Uwaimir bin Saidah, bahwasanya pada suatu hari Nabi saw. mendatangi mereka (para sahabat) di mesjid Quba. Kemudian beliau bersabda, \"Sesungguhnya Allah swt. telah memuji kalian dengan baik atas pembersihan diri kalian sehubungan dengan kisah mesjid kalian ini (Quba). Maka cara pembersihan apakah yang sedang kalian lakukan sekarang ini?\" Mereka menjawab, \"Demi Allah, wahai Rasulullah, kami tidak mengetahui apa-apa melainkan kami mempunyai tetangga-tetangga Yahudi; mereka lalu membasuh dubur mereka setelah buang air besar, maka kami pun melakukan pembasuhan seperti apa yang mereka lakukan.\" Menurut hadis yang lain, yang telah diriwayatkan oleh Imam Bazzar disebutkan bahwa para sahabat mengatakan, \"Akan tetapi kami memakai batu terlebih dahulu, kemudian baru kami memakai air.\" Maka Nabi saw. menjawab, \"Itulah yang benar, maka peganglah cara ini oleh kalian.\"",[["لَا","Jangan"],["تَقُمْ","berdiri"],["فِيهِ","di dalamnya"],["أَبَدًۭا ۚ","pernah"],["لَّمَسْجِدٌ","Sebuah masjid"],["أُسِّسَ","diasaskan"],["عَلَى","pada"],["ٱلتَّقْوَىٰ","kebenaran"],["مِنْ","daripada"],["أَوَّلِ","(yang) pertama"],["يَوْمٍ","hari"],["أَحَقُّ","(adalah) lebih layak"],["أَن","bahawa"],["تَقُومَ","kamu berdiri"],["فِيهِ ۚ","di dalamnya"],["فِيهِ","Di dalamnya"],["رِجَالٌۭ","(adalah) lelaki"],["يُحِبُّونَ","yang sayang"],["أَن","kepada"],["يَتَطَهَّرُوا۟ ۚ","menyucikan diri"],["وَٱللَّهُ","dan Allah"],["يُحِبُّ","suka"],["ٱلْمُطَّهِّرِينَ","orang yang menyucikan diri"]]],"1344":["(Maka apakah orang-orang yang mendirikan mesjidnya di atas dasar takwa) karena takut (kepada Allah dan) selalu mengharapkan (keridaan)-Nya itu (yang lebih baik, ataukah orang-orang yang mendirikan bangunannya di tepi) dapat dibaca jurufin dan dapat pula dibaca jurfin, artinya di pinggir (jurang) yakni hampir roboh (lalu bangunannya itu jatuh bersama-sama dengan dia) maksudnya bangunannya roboh berikut orang-orang yang membangunnya (ke dalam neraka Jahanam?) ungkapan ayat ini merupakan tamtsil/perumpamaan yang paling baik, yaitu menggambarkan pembangunan mesjid yang berdasarkan bukan kepada takwa, kemudian akibat-akibat yang akan dialaminya. Kata tanya pada permulaan ayat ini mengandung makna taqrir, artinya mesjid pertamalah yang baik seperti halnya mesjid Quba. Sedangkan gambaran yang kedua adalah perumpamaan mesjid dhirar. (Dan Allah tidak memberikan petunjuk kepada orang-orang yang lalim).",[["أَفَمَنْ","Kemudian adakah (seorang) yang"],["أَسَّسَ","diasaskan"],["بُنْيَـٰنَهُۥ","bangunannya"],["عَلَىٰ","pada"],["تَقْوَىٰ","kebenaran"],["مِنَ","daripada"],["ٱللَّهِ","Allah"],["وَرِضْوَٰنٍ","dan keredhaan-Nya"],["خَيْرٌ","lebih baik"],["أَم","atau"],["مَّنْ","(satu) siapa"],["أَسَّسَ","diasaskan"],["بُنْيَـٰنَهُۥ","bangunannya"],["عَلَىٰ","pada"],["شَفَا","tepi"],["جُرُفٍ","(dari) tebing"],["هَارٍۢ","(kira-kira) runtuh"],["فَٱنْهَارَ","jadi ia runtuh"],["بِهِۦ","dengan dia"],["فِى","dalam"],["نَارِ","(the) Api"],["جَهَنَّمَ ۗ","(dari) Neraka"],["وَٱللَّهُ","Dan Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["ٱلْقَوْمَ","orang yang zalim"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"1345":["(Bangunan-bangunan yang mereka dirikan itu senantiasa menjadi pangkal keraguan) yakni keragu-raguan (dalam hati mereka kecuali bila telah hancur) tercabik-cabik (hati mereka itu) lantaran mereka mati. (Dan Allah Maha Mengetahui) tentang makhluk-Nya (lagi Maha Bijaksana) dalam perlakuan-Nya terhadap makhluk-Nya.",[["لَا","Tidak"],["يَزَالُ","(akan) berhenti"],["بُنْيَـٰنُهُمُ","bangunan mereka"],["ٱلَّذِى","yang"],["بَنَوْا۟","mereka bina"],["رِيبَةًۭ","a (sebab) keraguan"],["فِى","dalam"],["قُلُوبِهِمْ","hati mereka"],["إِلَّآ","kecuali"],["أَن","bahawa"],["تَقَطَّعَ","(adalah) dipotong-potong"],["قُلُوبُهُمْ ۗ","hati mereka"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌ","Maha Mengetahui"],["حَكِيمٌ","Maha Bijaksana"]]],"1346":["(Sesungguhnya Allah telah membeli dari orang-orang mukmin diri dan harta mereka) lantaran mereka menginfakkannya di jalan ketaatan kepada-Nya, seperti untuk berjuang di jalan-Nya (dengan memberikan surga untuk mereka. Mereka berperang pada jalan Allah lalu mereka membunuh atau dibunuh) ayat ini merupakan kalimat baru yang menjadi penafsir bagi makna yang terkandung di dalam lafal fa yuqtaluuna wa yaqtuluuna, artinya sebagian dari mereka ada yang gugur dan sebagian yang lain meneruskan pertempurannya (sebagai janji yang benar) lafal wa`dan dan haqqan keduanya berbentuk mashdar yang dinashabkan fi`ilnya masing-masing yang tidak disebutkan (di dalam Taurat, Injil dan Alquran?) artinya tiada seorang pun yang lebih menepati janjinya selain dari Allah. (Maka bergembiralah) dalam ayat ini terkandung pengertian iltifat/perpindahan pembicaraan dari gaib kepada mukhathab/dari orang ketiga kepada orang kedua (dengan jual-beli yang telah kalian lakukan itu dan yang demikian itu) yaitu jual-beli itu (adalah kemenangan yang besar) yang dapat mengantarkan kepada tujuan yang paling didambakan.",[["۞ إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["ٱشْتَرَىٰ","(telah) membeli"],["مِنَ","daripada"],["ٱلْمُؤْمِنِينَ","orang yang beriman"],["أَنفُسَهُمْ","kehidupan mereka"],["وَأَمْوَٰلَهُم","dan kekayaan mereka"],["بِأَنَّ","kerana"],["لَهُمُ","bagi mereka"],["ٱلْجَنَّةَ ۚ","(ialah) Syurga"],["يُقَـٰتِلُونَ","Mereka bergaduh"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["فَيَقْتُلُونَ","mereka membunuh"],["وَيُقْتَلُونَ ۖ","dan mereka dibunuh"],["وَعْدًا","Sebuah janji"],["عَلَيْهِ","atas Dia"],["حَقًّۭا","benar"],["فِى","dalam"],["ٱلتَّوْرَىٰةِ","Taurat"],["وَٱلْإِنجِيلِ","dan Injeel"],["وَٱلْقُرْءَانِ ۚ","dan al-Quran"],["وَمَنْ","Dan siapa"],["أَوْفَىٰ","(adalah) lebih setia"],["بِعَهْدِهِۦ","kepada janjinya"],["مِنَ","daripada"],["ٱللَّهِ ۚ","Allah"],["فَٱسْتَبْشِرُوا۟","Jadi bergembiralah"],["بِبَيْعِكُمُ","dalam transaksi kamu"],["ٱلَّذِى","yang"],["بَايَعْتُم","kamu telah berkontrak"],["بِهِۦ ۚ","[dengannya]"],["وَذَٰلِكَ","Dan bahawa"],["هُوَ","ia"],["ٱلْفَوْزُ","(ialah) kejayaan"],["ٱلْعَظِيمُ","yang hebat"]]],"1347":["(Mereka itu adalah orang-orang yang bertobat) lafal at-taa'ibuuna dirafa'kan untuk tujuan memuji, yaitu dengan memperkirakan adanya mubtada sebelumnya; artinya mereka itu adalah orang-orang yang bertobat dari kemusyrikan dan kemunafikan (yang beribadah) orang-orang yang ikhlas karena Allah dalam beribadah (yang memuji) kepada Allah dalam semua kondisi (yang melawat) makna yang dimaksud adalah mereka selalu mengerjakan shaum/puasa (yang rukuk, yang sujud) artinya mereka adalah orang-orang yang salat (yang menyuruh berbuat makruf dan mencegah berbuat mungkar dan yang memelihara batasan-batasan Allah) yakni hukum-hukum-Nya dengan cara mengamalkannya. (Dan gembirakanlah orang-orang mukmin itu) dengan surga.",[["ٱلتَّـٰٓئِبُونَ","Mereka yang bertaubat"],["ٱلْعَـٰبِدُونَ","mereka yang beribadat"],["ٱلْحَـٰمِدُونَ","mereka yang memuji"],["ٱلسَّـٰٓئِحُونَ","mereka yang keluar"],["ٱلرَّٰكِعُونَ","mereka yang sujud"],["ٱلسَّـٰجِدُونَ","mereka yang sujud"],["ٱلْـَٔامِرُونَ","mereka yang menyuruh"],["بِٱلْمَعْرُوفِ","yang betul"],["وَٱلنَّاهُونَ","dan mereka yang melarang"],["عَنِ","[pada]"],["ٱلْمُنكَرِ","yang salah"],["وَٱلْحَـٰفِظُونَ","dan mereka yang memerhati"],["لِحُدُودِ","(the) had"],["ٱللَّهِ ۗ","(milik) Allah"],["وَبَشِّرِ","Dan sampaikanlah berita gembira"],["ٱلْمُؤْمِنِينَ","(kepada) orang-orang yang beriman"]]],"1348":["Ayat ini diturunkan berkenaan dengan permohonan ampunan Nabi saw. buat pamannya, yaitu Abu Thalib dan sekaligus berkenaan pula dengan permohonan ampunan sebagian para sahabat terhadap kedua orang-orang tua mereka masing-masing yang musyrik. (Tiadalah sepatutnya bagi Nabi dan orang-orang yang beriman memintakan ampun kepada Allah bagi orang-orang musyrik walaupun orang-orang musyrik itu kaum kerabat)nya, yakni familinya sendiri (sesudah jelas bagi mereka bahwasanya orang-orang yang musyrik itu adalah penghuni-penghuni Jahim) yakni neraka, lantaran mereka mati dalam keadaan kafir.",[["مَا","Tidak"],["كَانَ","(ia) ialah"],["لِلنَّبِىِّ","untuk Nabi"],["وَٱلَّذِينَ","dan orang yang"],["ءَامَنُوٓا۟","beriman"],["أَن","bahawa"],["يَسْتَغْفِرُوا۟","mereka meminta ampun"],["لِلْمُشْرِكِينَ","bagi orang musyrik"],["وَلَوْ","walaupun"],["كَانُوٓا۟","mereka jadi"],["أُو۟لِى","saudara terdekat"],["قُرْبَىٰ","saudara terdekat"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["مَا","[apa]"],["تَبَيَّنَ","telah menjadi jelas"],["لَهُمْ","kepada mereka"],["أَنَّهُمْ","bahawa mereka"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلْجَحِيمِ","(dari) api Neraka"]]],"1349":["(Dan permintaan ampun dari Ibrahim kepada Allah untuk bapaknya (pamannya) tidak lain hanya karena suatu janji yang telah diikrarkannya kepada bapaknya itu) melalui perkataan Nabi Ibrahim sendiri, seperti apa yang diungkapkan oleh firman-Nya, \"Aku akan mintakan ampun bagimu kepada Rabbku.\" (Q.S. Maryam 47) Nabi Ibrahim menjanjikan demikian dengan harapan semoga bapak (paman)nya itu mau masuk Islam. (Maka tatkala jelas bagi Ibrahim bahwa bapaknya/pamannya itu adalah musuh Allah) lantaran ia mati dalam keadaan kafir (maka Ibrahim berlepas diri daripadanya) kemudian Nabi Ibrahim berhenti dari memintakan ampunannya. (Sesungguhnya Ibrahim adalah seorang yang sangat lembut) banyak merendahkan diri dan berdoa kepada Allah (lagi penyantun) sangat sabar di dalam menahan derita.",[["وَمَا","Dan tidak"],["كَانَ","adalah"],["ٱسْتِغْفَارُ","(yang) meminta ampun"],["إِبْرَٰهِيمَ","(oleh) Ibrahim"],["لِأَبِيهِ","untuk bapanya"],["إِلَّا","kecuali"],["عَن","kerana"],["مَّوْعِدَةٍۢ","(dari) janji"],["وَعَدَهَآ","dia telah berjanji"],["إِيَّاهُ","(kepada) dia"],["فَلَمَّا","Tetapi apabila"],["تَبَيَّنَ","ia menjadi jelas"],["لَهُۥٓ","kepadanya"],["أَنَّهُۥ","bahawa dia"],["عَدُوٌّۭ","(adalah) musuh"],["لِّلَّهِ","kepada Allah"],["تَبَرَّأَ","dia berpisah"],["مِنْهُ ۚ","daripada dia"],["إِنَّ","Sesungguhnya"],["إِبْرَٰهِيمَ","Ibrahim"],["لَأَوَّٰهٌ","(adalah) penyayang"],["حَلِيمٌۭ","penyabar"]]],"1350":["(Dan Allah sekali-kali tidak akan menyesatkan suatu kaum, sesudah Allah memberi petunjuk kepada mereka) kepada Islam (hingga dijelaskan-Nya kepada mereka apa yang harus mereka jauhi) yakni amal-amal perbuatan mana saja yang harus mereka jauhi, akan tetapi ternyata mereka tidak menjauhinya, maka mereka layak menjadi orang-orang yang disesatkan. (Sesungguhnya Allah Maha Mengetahui segala sesuatu) antara lain ialah mengetahui siapa yang berhak untuk disesatkan dan siapa yang berhak untuk mendapat hidayah-Nya.",[["وَمَا","Dan tidak"],["كَانَ","ialah"],["ٱللَّهُ","(untuk) Allah"],["لِيُضِلَّ","yang Dia biarkan sesat"],["قَوْمًۢا","suatu kaum"],["بَعْدَ","selepas"],["إِذْ","[apabila]"],["هَدَىٰهُمْ","Dia telah membimbing mereka"],["حَتَّىٰ","sehingga"],["يُبَيِّنَ","Dia membuat jelas"],["لَهُم","kepada mereka"],["مَّا","apa"],["يَتَّقُونَ ۚ","mereka patut takut"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["بِكُلِّ","(daripada) setiap"],["شَىْءٍ","perkara"],["عَلِيمٌ","Maha Mengetahui"]]],"1351":["(Sesungguhnya kepunyaan Allahlah kerajaan langit dan bumi. Dia menghidupkan dan mematikan. Dan sekali-kali tiada bagi kalian) hai umat manusia (selain dari Allah) (yang melindungi) kalian daripada-Nya (dan yang memberikan pertolongan) yang dapat mencegah diri kalian dari kepastian Allah.",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَهُۥ","kepada-Nya (milik)"],["مُلْكُ","kekuasaan itu"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["يُحْىِۦ","Dia memberi kehidupan"],["وَيُمِيتُ ۚ","dan Dia menyebabkan kematian"],["وَمَا","Dan tidak"],["لَكُم","bagi kamu"],["مِّن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["مِن","sebarang"],["وَلِىٍّۢ","pelindung"],["وَلَا","dan bukan"],["نَصِيرٍۢ","mana-mana pembantu"]]],"1352":["(Sesungguhnya Allah telah menerima tobat) artinya Dia menerima tobat untuk selamanya (Nabi, orang-orang Muhajirin dan orang-orang Ansar yang mengikuti Nabi dalam masa kesulitan) yakni sewaktu keadaan sedang sulit-sulitnya. Hal ini terjadi sewaktu perang Tabuk; sebiji buah kurma dimakan oleh dua orang, dan sepuluh orang pasukan saling bergantian menaiki satu hewan kendaraan di antara sesama mereka, dan panas pada saat itu terik sekali sehingga mereka meminum air yang ada dalam perut unta karena persediaan air habis (setelah hampir berpaling) dapat dibaca yaziighu atau taziighu, artinya cenderung (hati segolongan dari mereka) dari mengikuti Nabi kemudian mereka bermaksud untuk kembali dan tidak ikut berperang lantaran kesulitan yang sedang mereka alami pada saat itu (kemudian Allah menerima tobat mereka itu) dengan memberikan keteguhan dan kesabaran kepada mereka. (Sesungguhnya Allah Maha Pengasih lagi Maha Penyayang).",[["لَّقَد","Sesungguhnya"],["تَّابَ","Allah berpaling (dengan rahmat)"],["ٱللَّهُ","Allah berpaling (dengan rahmat)"],["عَلَى","kepada"],["ٱلنَّبِىِّ","Nabi"],["وَٱلْمُهَـٰجِرِينَ","dan para pendatang"],["وَٱلْأَنصَارِ","dan para penolong"],["ٱلَّذِينَ","[mereka] yang"],["ٱتَّبَعُوهُ","mengikutinya"],["فِى","dalam"],["سَاعَةِ","(the) jam"],["ٱلْعُسْرَةِ","(dari) kesukaran"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["مَا","[apa]"],["كَادَ","mempunyai hampir"],["يَزِيغُ","menyimpang"],["قُلُوبُ","(the) hati"],["فَرِيقٍۢ","(dari) sebuah parti"],["مِّنْهُمْ","daripada mereka"],["ثُمَّ","kemudian"],["تَابَ","Dia berpaling (dengan belas kasihan)"],["عَلَيْهِمْ ۚ","kepada mereka"],["إِنَّهُۥ","Sesungguhnya Dia"],["بِهِمْ","kepada mereka"],["رَءُوفٌۭ","(adalah) Maha Baik"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"1353":["(Dan) Allah menerima tobat pula (terhadap tiga orang yang ditangguhkan) penerimaan tobat mereka melalui bukti yang menunjukkan hal itu (sehingga apabila bumi terasa sempit oleh mereka padahal bumi itu luas) sekalipun kenyataannya bumi itu luas lantaran mereka tidak dapat menemukan tempat yang dapat mengganti hati mereka (dan jika hati mereka pun terasa sempit pula) yakni hati mereka menjadi sempit lantaran susah dan asing disebabkan tobat mereka ditangguhkan penerimaannya sehingga hati mereka tidak gembira dan selalu tidak tenteram (serta mereka menduga) dan merasa yakin (bahwasanya) dibaca dengan takhfif, yaitu an (tidak ada tempat lari dari siksa Allah melainkan kepada-Nya saja. Kemudian Allah menerima tobat mereka) Allah memberikan taufik dan kekuatan kepada mereka untuk bertobat (agar mereka tetap dalam tobatnya. Sesungguhnya Allahlah Yang Maha Penerima tobat lagi Maha Penyayang).",[["وَعَلَى","Dan seterusnya"],["ٱلثَّلَـٰثَةِ","ketiga-tiganya"],["ٱلَّذِينَ","orang yang"],["خُلِّفُوا۟","telah ditinggalkan"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["ضَاقَتْ","(telah) tertekan"],["عَلَيْهِمُ","bagi mereka"],["ٱلْأَرْضُ","bumi"],["بِمَا","walaupun"],["رَحُبَتْ","ia adalah luas"],["وَضَاقَتْ","Dan (telah) kesempitan"],["عَلَيْهِمْ","bagi mereka"],["أَنفُسُهُمْ","jiwa mereka sendiri"],["وَظَنُّوٓا۟","dan mereka pasti"],["أَن","bahawa"],["لَّا","(ada) tidak"],["مَلْجَأَ","tempat perlindungan"],["مِنَ","daripada"],["ٱللَّهِ","Allah"],["إِلَّآ","kecuali"],["إِلَيْهِ","kepada-Nya"],["ثُمَّ","Kemudian"],["تَابَ","Dia berpaling (dengan belas kasihan)"],["عَلَيْهِمْ","kepada mereka"],["لِيَتُوبُوٓا۟ ۚ","supaya mereka bertaubat"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["ٱلتَّوَّابُ","(ialah) Penerima taubat"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"1354":["(Hai orang-orang yang beriman, bertakwalah kalian kepada Allah) dengan meninggalkan perbuatan-perbuatan maksiat (dan hendaklah kalian bersama orang-orang yang benar) dalam hal iman dan menepati janji untuk itu kalian harus menetapi kebenaran.",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["ٱتَّقُوا۟","Takut"],["ٱللَّهَ","Allah"],["وَكُونُوا۟","dan jadilah"],["مَعَ","dengan"],["ٱلصَّـٰدِقِينَ","mereka yang benar"]]],"1355":["(Tidaklah patut bagi penduduk Madinah dan orang-orang Arab badui yang berdiam di sekitarnya tidak turut menyertai Rasulullah) bilamana beliau pergi berperang (dan tidak patut pula bagi mereka lebih mencintai diri mereka daripada mencintai diri Rasul) yaitu dengan cara mendahulukan kepentingan apa yang menjadi keridaannya daripada kemaslahatan diri sendiri di dalam menghadapi saat-saat yang sulit. Ungkapan ayat ini merupakan nahi atau larangan, akan tetapi diungkapkan dalam bentuk kalimat khabar atau kalimat berita. (Yang demikian itu) yaitu larangan untuk tidak pergi bersama Rasulullah ke medan perang (ialah karena mereka) disebabkan (tidak ditimpa kehausan) rasa dahaga (kepayahan) keletihan (dan kelaparan) yakni rasa lapar (pada jalan Allah dan tidak pula menginjak suatu tempat) lafal mauthi'an adalah mashdar akan tetapi maknanya sama dengan lafal wath'an (yang membangkitkan amarah) artinya yang membuat marah (orang-orang kafir dan tidak menimpakan kepada musuh) Allah (sesuatu bencana) membunuh, menawan atau membegal musuh (melainkan dituliskan bagi mereka dengan yang demikian itu suatu amal saleh) dimaksud supaya mereka mau melaksanakan hal tersebut. (Sesungguhnya Allah tidak menyia-nyiakan pahala orang-orang yang berbuat baik) pahala mereka tidak akan disia-siakan-Nya, bahkan Dia akan memberi mereka pahala.",[["مَا","Tidak"],["كَانَ","ia adalah"],["لِأَهْلِ","(untuk) rakyat"],["ٱلْمَدِينَةِ","daripada Madinah"],["وَمَنْ","dan siapa"],["حَوْلَهُم","berada di sekeliling mereka"],["مِّنَ","daripada"],["ٱلْأَعْرَابِ","orang badwi"],["أَن","bahawa"],["يَتَخَلَّفُوا۟","mereka kekal di belakang"],["عَن","selepas"],["رَّسُولِ","Rasul"],["ٱللَّهِ","daripada Allah"],["وَلَا","dan bukan"],["يَرْغَبُوا۟","mereka lebih suka"],["بِأَنفُسِهِمْ","kehidupan mereka"],["عَن","kepada"],["نَّفْسِهِۦ ۚ","hidupnya"],["ذَٰلِكَ","iaitu"],["بِأَنَّهُمْ","kerana [mereka]"],["لَا","tidak"],["يُصِيبُهُمْ","menyeksa mereka"],["ظَمَأٌۭ","dahaga"],["وَلَا","dan bukan"],["نَصَبٌۭ","keletihan"],["وَلَا","dan bukan"],["مَخْمَصَةٌۭ","kelaparan"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["وَلَا","dan bukan"],["يَطَـُٔونَ","mereka melangkah"],["مَوْطِئًۭا","sebarang langkah"],["يَغِيظُ","yang marah"],["ٱلْكُفَّارَ","orang kafir"],["وَلَا","dan bukan"],["يَنَالُونَ","mereka timpakan"],["مِنْ","pada"],["عَدُوٍّۢ","seorang musuh"],["نَّيْلًا","suatu infliction"],["إِلَّا","kecuali"],["كُتِبَ","direkodkan"],["لَهُم","bagi mereka"],["بِهِۦ","di dalamnya"],["عَمَلٌۭ","(sebagai) surat ikatan"],["صَـٰلِحٌ ۚ","soleh"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يُضِيعُ","biarkan hilang"],["أَجْرَ","ganjarannya"],["ٱلْمُحْسِنِينَ","(dari) orang-orang yang berbuat baik"]]],"1356":["(Dan mereka tiada menafkahkan) dalam rangka melaksanakan hal tersebut (suatu nafkah yang kecil) sekali pun berupa sebiji buah kurma (dan tidak pula yang besar dan tidak melintasi suatu lembah) dengan berjalan kaki (melainkan dituliskan bagi mereka) amal saleh pula (karena Allah memberi balasan kepada mereka yang lebih baik dari apa yang telah mereka kerjakan) sebagai pahalanya.",[["وَلَا","Dan tidak"],["يُنفِقُونَ","mereka belanjakan"],["نَفَقَةًۭ","sebarang perbelanjaan"],["صَغِيرَةًۭ","kecil"],["وَلَا","dan bukan"],["كَبِيرَةًۭ","besar"],["وَلَا","dan bukan"],["يَقْطَعُونَ","mereka menyeberang"],["وَادِيًا","sebuah lembah"],["إِلَّا","tetapi"],["كُتِبَ","direkodkan"],["لَهُمْ","bagi mereka"],["لِيَجْزِيَهُمُ","agar Allah membalasnya"],["ٱللَّهُ","agar Allah membalasnya"],["أَحْسَنَ","yang terbaik"],["مَا","apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَعْمَلُونَ","lakukan"]]],"1357":["Tatkala kaum Mukminin dicela oleh Allah bila tidak ikut ke medan perang kemudian Nabi saw. mengirimkan sariyahnya, akhirnya mereka berangkat ke medan perang semua tanpa ada seorang pun yang tinggal, maka turunlah firman-Nya berikut ini: (Tidak sepatutnya bagi orang-orang yang mukmin itu pergi) ke medan perang (semuanya. Mengapa tidak) (pergi dari tiap-tiap golongan) suatu kabilah (di antara mereka beberapa orang) beberapa golongan saja kemudian sisanya tetap tinggal di tempat (untuk memperdalam pengetahuan mereka) yakni tetap tinggal di tempat (mengenai agama dan untuk memberi peringatan kepada kaumnya apabila mereka telah kembali kepadanya) dari medan perang, yaitu dengan mengajarkan kepada mereka hukum-hukum agama yang telah dipelajarinya (supaya mereka itu dapat menjaga dirinya) dari siksaan Allah, yaitu dengan melaksanakan perintah-Nya dan menjauhi larangan-Nya. Sehubungan dengan ayat ini Ibnu Abbas r.a. memberikan penakwilannya bahwa ayat ini penerapannya hanya khusus untuk sariyah-sariyah, yakni bilamana pasukan itu dalam bentuk sariyah lantaran Nabi saw. tidak ikut. Sedangkan ayat sebelumnya yang juga melarang seseorang tetap tinggal di tempatnya dan tidak ikut berangkat ke medan perang, maka hal ini pengertiannya tertuju kepada bila Nabi saw. berangkat ke suatu ghazwah.",[["۞ وَمَا","Dan tidak"],["كَانَ","ialah"],["ٱلْمُؤْمِنُونَ","(untuk) orang-orang yang beriman"],["لِيَنفِرُوا۟","bahawa mereka pergi"],["كَآفَّةًۭ ۚ","semua bersama"],["فَلَوْلَا","Jadi jika tidak"],["نَفَرَ","pergi ke hadapan"],["مِن","daripada"],["كُلِّ","setiap"],["فِرْقَةٍۢ","kumpulan"],["مِّنْهُمْ","antara mereka"],["طَآئِفَةٌۭ","sebuah parti"],["لِّيَتَفَقَّهُوا۟","agar mereka memperoleh pemahaman"],["فِى","dalam"],["ٱلدِّينِ","agama itu"],["وَلِيُنذِرُوا۟","dan supaya mereka memberi amaran"],["قَوْمَهُمْ","rakyat mereka"],["إِذَا","apabila"],["رَجَعُوٓا۟","mereka balik"],["إِلَيْهِمْ","kepada mereka"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَحْذَرُونَ","awas"]]],"1358":["(Hai orang-orang yang beriman perangilah orang-orang kafir yang ada di sekitar kalian itu) yakni mereka yang tinggal berdekatan dengan kalian, kemudian mereka yang dibilang tinggal berdekatan dengan kalian (dan hendaklah mereka menemui kekerasan daripada kalian) artinya berlaku keraslah kalian terhadap mereka (dan ketahuilah bahwasanya Allah beserta orang-orang yang bertakwa) bantuan dan pertolongan-Nya akan selalu menyertainya.",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["قَـٰتِلُوا۟","Bergaduh"],["ٱلَّذِينَ","orang yang"],["يَلُونَكُم","(ada) dekat dengan kamu"],["مِّنَ","daripada"],["ٱلْكُفَّارِ","orang kafir"],["وَلْيَجِدُوا۟","dan biarkan mereka mencari"],["فِيكُمْ","dalam kamu"],["غِلْظَةًۭ ۚ","kekasaran"],["وَٱعْلَمُوٓا۟","Dan tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["مَعَ","(adalah) dengan"],["ٱلْمُتَّقِينَ","orang-orang yang takut (kepada-Nya)"]]],"1359":["(Dan apabila diturunkan suatu surah) dari Alquran (maka di antara mereka) orang-orang munafik (ada yang berkata) kepada teman-temannya dengan nada mengejek (\"Siapakah di antara kalian yang bertambah imannya dengan turunnya surah ini?\") yakni kepercayaannya. Maka Allah swt. langsung berfirman menjawab perkataan mereka. (Adapun orang-orang yang beriman, maka surah ini menambah imannya) karena mereka benar-benar percaya kepadanya (sedangkan mereka merasa gembira) dengan turunnya surah ini.",[["وَإِذَا","Dan apabila-apabila"],["مَآ","Dan apabila-apabila"],["أُنزِلَتْ","didedahkan"],["سُورَةٌۭ","a Surah"],["فَمِنْهُم","antara mereka"],["مَّن","(adalah beberapa) siapa"],["يَقُولُ","berkata"],["أَيُّكُمْ","yang mana antara kamu"],["زَادَتْهُ","(telah) meningkat [ia]"],["هَـٰذِهِۦٓ","(oleh) ini"],["إِيمَـٰنًۭا ۚ","(dalam) iman"],["فَأَمَّا","Adapun"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["فَزَادَتْهُمْ","maka ia telah menambahkan mereka"],["إِيمَـٰنًۭا","(dalam) iman"],["وَهُمْ","dan mereka"],["يَسْتَبْشِرُونَ","bergembiralah"]]],"1360":["(Dan adapun orang-orang yang di dalam hati mereka ada penyakit) lemah keyakinan (maka dengan surah ini bertambah kekafiran mereka di samping kekafirannya) kekafiran mereka makin bertambah karena pada mulanya mereka sudah kafir kepada surah itu (dan mereka mati dalam keadaan kafir).",[["وَأَمَّا","Tetapi untuk"],["ٱلَّذِينَ","mereka"],["فِى","dalam"],["قُلُوبِهِم","hati mereka"],["مَّرَضٌۭ","(adalah) penyakit"],["فَزَادَتْهُمْ","(ia) meningkatkan mereka"],["رِجْسًا","(dalam) kejahatan"],["إِلَىٰ","kepada"],["رِجْسِهِمْ","kejahatan mereka"],["وَمَاتُوا۟","Dan mereka mati"],["وَهُمْ","sedangkan mereka"],["كَـٰفِرُونَ","(adalah) orang-orang kafir"]]],"1361":["(Dan tidakkah mereka memperhatikan) bila dibaca yarauna, fa'ilnya adalah orang-orang munafik, dan bila dibaca tarauna, fa`ilnya adalah orang-orang mukmin (bahwa mereka diuji) dicoba (sekali atau dua kali setiap tahun) dengan musim paceklik dan wabah penyakit (kemudian mereka tidak juga bertobat) dari kemunafikannya (dan tidak pula mengambil pelajaran) artinya pelajaran buat dirinya.",[["أَوَلَا","Jangan"],["يَرَوْنَ","mereka lihat"],["أَنَّهُمْ","bahawa mereka"],["يُفْتَنُونَ","dicuba"],["فِى","[dalam]"],["كُلِّ","setiap"],["عَامٍۢ","tahun"],["مَّرَّةً","sekali"],["أَوْ","atau"],["مَرَّتَيْنِ","dua kali"],["ثُمَّ","Namun"],["لَا","tidak"],["يَتُوبُونَ","mereka bertaubat"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يَذَّكَّرُونَ","ambil iktibar"]]],"1362":["(Dan apabila diturunkan satu surah) yang di dalamnya menyebutkan tentang perihal mereka, kemudian surah tersebut dibacakan oleh Nabi saw. (sebagian mereka memandang kepada sebagian yang lain) dengan maksud untuk lari dari tempat itu seraya berkata (\"Adakah seorang dari orang-orang Muslimin yang melihat kalian?\") bilamana kalian pergi dari tempat ini; jika ternyata tidak ada seorang pun dari kalangan kaum Muslimin yang melihat mereka, maka mereka segera beranjak pergi dari tempat itu. Apabila ternyata ada seseorang dari kaum Muslimin yang melihat mereka, maka mereka tetap di tempatnya (sesudah itu mereka pun pergi) dengan membawa kekafirannya. (Allah telah memalingkan hati mereka) dari hidayah (disebabkan mereka adalah kaum yang tidak mengerti) akan kebenaran, lantaran mereka tidak mau menggunakan pikirannya guna merenungkan kebenaran itu.",[["وَإِذَا","Dan apabila-apabila"],["مَآ","Dan apabila-apabila"],["أُنزِلَتْ","didedahkan"],["سُورَةٌۭ","a Surah"],["نَّظَرَ","tengok"],["بَعْضُهُمْ","sebahagian mereka"],["إِلَىٰ","kepada"],["بَعْضٍ","yang lain"],["هَلْ","Adakah"],["يَرَىٰكُم","jumpa kamu"],["مِّنْ","sebarang"],["أَحَدٍۢ","satu"],["ثُمَّ","Kemudian"],["ٱنصَرَفُوا۟ ۚ","mereka berpaling"],["صَرَفَ","Allah telah berpaling"],["ٱللَّهُ","Allah telah berpaling"],["قُلُوبَهُم","hati mereka"],["بِأَنَّهُمْ","kerana mereka"],["قَوْمٌۭ","(adalah) suatu kaum"],["لَّا","tidak"],["يَفْقَهُونَ","mereka faham"]]],"1363":["(Sesungguhnya telah datang kepada kalian seorang rasul dari kaum kalian sendiri) dari kalangan kalian sendiri, yaitu Nabi Muhammad saw. (berat terasa) dirasa berat (olehnya apa yang kalian derita) yaitu penderitaan kalian, yang dimaksud ialah penderitaan dan musibah yang menimpa diri kalian (sangat menginginkan bagi kalian) hidayah dan keselamatan (lagi terhadap orang-orang mukmin amat belas kasihan) sangat belas kasihan (lagi penyayang) ia selalu mengharapkan kebaikan bagi mereka.",[["لَقَدْ","Sungguh"],["جَآءَكُمْ","(telah) datang kepadamu"],["رَسُولٌۭ","seorang Rasul"],["مِّنْ","daripada"],["أَنفُسِكُمْ","kamu sendiri"],["عَزِيزٌ","Sedih"],["عَلَيْهِ","kepadanya"],["مَا","(ialah) apa"],["عَنِتُّمْ","kamu menderita"],["حَرِيصٌ","(dia) prihatin"],["عَلَيْكُم","atas kamu"],["بِٱلْمُؤْمِنِينَ","kepada orang yang beriman"],["رَءُوفٌۭ","(dia) baik hati"],["رَّحِيمٌۭ","(dan) penyayang"]]],"1364":["(Jika mereka berpaling) dari iman kepadamu (maka katakanlah, \"Cukuplah bagiku) maksudnya cukup untukku (Allah; tidak ada Tuhan selain Dia. Hanya kepada-Nya aku bertawakal) percaya dan bukan kepada selain-Nya (dan Dia adalah Rabb yang memiliki Arasy) yakni Al-Kursiy (yang agung.\") Arasy disebutkan secara khusus karena ia makhluk yang paling besar. Imam Hakim di dalam kitab Al-Mustadrak meriwayatkan sebuah atsar yang bersumber dari Ubay bin Kaab, bahwasanya Ubay bin Kaab telah mengatakan, \"Ayat yang diturunkan paling akhir ialah firman-Nya, 'Sesungguhnya telah datang kepada kalian seorang rasul.'\" (Q.S. At-Taubah 128-129). Kedua ayat akhir surah At-Taubah itulah ayat yang paling terakhir diturunkan.",[["فَإِن","Tetapi jika"],["تَوَلَّوْا۟","mereka berpaling"],["فَقُلْ","kemudian berkata"],["حَسْبِىَ","Cukup untuk aku"],["ٱللَّهُ","(ialah) Allah"],["لَآ","(Ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ ۖ","Dia"],["عَلَيْهِ","Pada Dia"],["تَوَكَّلْتُ ۖ","Aku meletakkan kepercayaan aku"],["وَهُوَ","Dan Dia"],["رَبُّ","(ialah) Tuhan"],["ٱلْعَرْشِ","(dari) Arasy"],["ٱلْعَظِيمِ","yang Agung"]]],"1365":["(Alif, laam, raa) hanya Allahlah yang mengetahui maksudnya. (Inilah) artinya ayat-ayat ini (ayat-ayat Alkitab) yakni Alquran. Diidhafatkan lafal ayaatul pada lafal Alkitab mengandung makna min, yakni bagian daripada Alquran (yang mengandung hikmah) yang padat akan hikmah-hikmah.",[["الٓر ۚ","Alif Lam Ra"],["تِلْكَ","Ini"],["ءَايَـٰتُ","(adalah) ayat-ayat"],["ٱلْكِتَـٰبِ","Kitab"],["ٱلْحَكِيمِ","yang bijak"]]],"1366":["(Patutkah manusia) artinya penduduk Mekah. Istifham atau kata tanya di sini mengandung makna ingkar sedangkan jar dan majrurnya menjadi hal atau kata keterangan daripada firman selanjutnya (menjadi keheranan) lafal ini dibaca `ajaban menjadi khabar dari kaana, bila dibaca rafa` menjadi isim kaana. Menurut pendapat yang masyhur adalah sebagai khabar daripada kaana. (bahwa Kami mewahyukan) artinya pemberian wahyu Kami (kepada seorang lelaki di antara mereka) yaitu Nabi Muhammad saw. (yaitu) huruf an di sini menjadi penafsir dari lafal an auhainaa (\"Berilah peringatan) peringatkanlah (kepada manusia) yakni orang-orang kafir akan adanya siksaan buat mereka (dan gembirakanlah orang-orang beriman bahwa) bahwasanya (mereka mempunyai kedudukan) pahala (yang tinggi di sisi Rabb mereka\") dimaksud adalah pahala yang baik sebagai pembalasan dari amal-amal yang telah mereka lakukan. (Orang-orang kafir berkata, \"Sesungguhnya orang ini) yaitu Nabi Muhammad saw. (benar-benar adalah tukang sihir yang nyata.\") jelas tukang sihir. Menurut suatu qiraat lafal lasaahirun dibaca lasihrun, sedangkan musyar ilaihnya adalah Alquran yang dianggap mereka merupakan sihir.",[["أَكَانَ","Adakah ia"],["لِلنَّاسِ","untuk umat manusia"],["عَجَبًا","keajaiban"],["أَنْ","bahawa"],["أَوْحَيْنَآ","Kami mendedahkan"],["إِلَىٰ","kepada"],["رَجُلٍۢ","seorang lelaki"],["مِّنْهُمْ","daripada (antara) mereka"],["أَنْ","bahawa"],["أَنذِرِ","Beri amaran"],["ٱلنَّاسَ","umat manusia"],["وَبَشِّرِ","dan sampaikanlah berita gembira"],["ٱلَّذِينَ","(kepada) mereka yang"],["ءَامَنُوٓا۟","beriman"],["أَنَّ","bahawa"],["لَهُمْ","bagi mereka"],["قَدَمَ","(akan) kedudukan yang dihormati"],["صِدْقٍ","(akan) kedudukan yang dihormati"],["عِندَ","dekat"],["رَبِّهِمْ ۗ","Tuhan mereka"],["قَالَ","Berkata"],["ٱلْكَـٰفِرُونَ","orang kafir"],["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["لَسَـٰحِرٌۭ","(adalah) sesungguhnya seorang ahli sihir"],["مُّبِينٌ","jelas"]]],"1367":["(Sesungguhnya Rabb kalian ialah Allah yang menciptakan langit dan bumi dalam enam hari) dari hari-hari dunia, artinya dalam masa yang perkiraannya sama dengan enam hari karena sesungguhnya pada masa itu belum ada matahari dan bulan. Akan tetapi seandainya Allah berkehendak, maka Dia dapat menciptakannya dalam sekejap mata. Allah swt, tidak memakai cara tersebut dimaksud untuk memberikan pelajaran kepada makhluk-Nya tentang ketekunan dan kesabaran di dalam bertindak (kemudian Dia bersemayam di atas Arsy) bersemayamnya Allah disesuaikan dengan keagungan sifat-Nya (untuk mengatur segala urusan) di antara makhluk-makhluk-Nya (Tiada seorang pun) huruf min merupakan shilah atau penghubung (yang dapat memberikan syafaat) kepada seseorang (kecuali sesudah ada keizinan-Nya) ayat ini merupakan sanggahan terhadap perkataan orang-orang kafir yang menyatakan bahwa berhala-berhala mereka dapat memberikan syafaat kepada diri mereka. (Zat yang demikian itulah) yaitu yang menciptakan dan yang mengatur (Allah, Rabb kalian, maka sembahlah Dia) artinya tauhidkanlah Dia. (Maka apakah kalian tidak mengambil pelajaran?) lafal tadzakkaruuna asalnya tatadzakkaruuna, kemudian huruf ta yang kedua diidgamkan ke dalam huruf dzal asal kalimat, maka jadilah tadzakkaruuna.",[["إِنَّ","Sesungguhnya"],["رَبَّكُمُ","Tuhanmu"],["ٱللَّهُ","(ialah) Allah"],["ٱلَّذِى","yang Esa"],["خَلَقَ","dicipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["فِى","dalam"],["سِتَّةِ","enam"],["أَيَّامٍۢ","tempoh"],["ثُمَّ","kemudian"],["ٱسْتَوَىٰ","Dia menubuhkan"],["عَلَى","pada"],["ٱلْعَرْشِ ۖ","takhta"],["يُدَبِّرُ","melupuskan"],["ٱلْأَمْرَ ۖ","urusan"],["مَا","Tidak"],["مِن","(adalah) mana-mana pemberi syafaat"],["شَفِيعٍ","(adalah) mana-mana pemberi syafaat"],["إِلَّا","kecuali"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["إِذْنِهِۦ ۚ","izinNya"],["ذَٰلِكُمُ","Itu"],["ٱللَّهُ","(ialah) Allah"],["رَبُّكُمْ","Tuhanmu"],["فَٱعْبُدُوهُ ۚ","maka sembahlah Dia"],["أَفَلَا","Kemudian tidak akan"],["تَذَكَّرُونَ","kamu ingat"]]],"1368":["(Hanya kepada-Nyalah) yaitu Allah swt. (kalian semuanya akan kembali; sebagai janji yang benar dari Allah) lafal wa'dan dan lafal haqqan keduanya merupakan mashdar yang dinashabkan oleh fi'ilnya masing-masing yang keberadaannya diperkirakan. (Sesungguhnya Allah) huruf hamzah inna dibaca kasrah karena menjadi isti'naf, sedangkan jika dibaca fatah maka memakai huruf lam yang keberadaannya diperkirakan sebelumnya (menciptakan makhluk pada permulaan) artinya Dia mulai menciptakan makhluk dengan mengadakan mereka (kemudian menghidupkannya kembali) pada hari berbangkit (agar Dia memberi pembalasan) pahala (kepada orang-orang yang beriman dan yang mengerjakan amal saleh dengan adil. Dan untuk orang-orang kafir disediakan minuman air yang panas) artinya air yang panasnya luar biasa (dan azab yang pedih) sangat menyakitkan (disebabkan kekafiran mereka) sebagai pembalasan atas kekafirannya.",[["إِلَيْهِ","KepadaNya"],["مَرْجِعُكُمْ","(akan menjadi) kepulanganmu"],["جَمِيعًۭا ۖ","[semua]"],["وَعْدَ","Janji"],["ٱللَّهِ","(milik) Allah"],["حَقًّا ۚ","(adalah) benar"],["إِنَّهُۥ","Sesungguhnya Dia"],["يَبْدَؤُا۟","berasal"],["ٱلْخَلْقَ","penciptaan"],["ثُمَّ","kemudian"],["يُعِيدُهُۥ","Dia mengulanginya"],["لِيَجْزِىَ","agar Dia memberi ganjaran"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan lakukan"],["ٱلصَّـٰلِحَـٰتِ","perbuatan baik itu"],["بِٱلْقِسْطِ ۚ","dalam keadilan"],["وَٱلَّذِينَ","Tetapi mereka yang"],["كَفَرُوا۟","kufur"],["لَهُمْ","bagi mereka"],["شَرَابٌۭ","(akan menjadi) minuman"],["مِّنْ","daripada"],["حَمِيمٍۢ","cecair mendidih"],["وَعَذَابٌ","dan hukuman"],["أَلِيمٌۢ","yang pedih"],["بِمَا","kerana"],["كَانُوا۟","mereka pernah (untuk)"],["يَكْفُرُونَ","kufur"]]],"1369":["(Dialah yang menjadikan matahari bersinar) mempunyai sinar (dan bulan bercahaya dan ditetapkan-Nya bagi bulan) dalam perjalanannya (manzilah-manzilah) selama dua puluh delapan malam untuk setiap bulan, setiap malam daripada dua puluh delapan malam itu memperoleh suatu manzilah, kemudian tidak tampak selama dua malam, jika jumlah hari bulan yang bersangkutan ada tiga puluh hari. Atau tidak tampak selama satu malam jika ternyata jumlah hari bulan yang bersangkutan ada dua puluh sembilan hari (supaya kalian mengetahui) melalui hal tersebut (bilangan tahun dan perhitungan waktu, Allah tidak menciptakan yang demikian itu) hal-hal yang telah disebutkan itu (melainkan dengan hak) bukannya main-main, Maha Suci Allah dari perbuatan tersebut (Dia menjelaskan) dapat dibaca yufashshilu dan nufashshilu, artinya Dia menerangkan atau Kami menerangkan (tanda-tanda kepada orang-orang yang mengetahui) yakni orang-orang yang mau berpikir.",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["جَعَلَ","dibuat"],["ٱلشَّمْسَ","matahari"],["ضِيَآءًۭ","cahaya yang bersinar"],["وَٱلْقَمَرَ","dan bulan"],["نُورًۭا","cahaya yang dipantulkan"],["وَقَدَّرَهُۥ","dan bertekad untuk itu"],["مَنَازِلَ","fasa"],["لِتَعْلَمُوا۟","supaya kamu tahu"],["عَدَدَ","(nombor)."],["ٱلسِّنِينَ","(dari) tahun"],["وَٱلْحِسَابَ ۚ","dan kiraan (masa)"],["مَا","Tidak"],["خَلَقَ","dicipta"],["ٱللَّهُ","Allah"],["ذَٰلِكَ","bahawa"],["إِلَّا","kecuali"],["بِٱلْحَقِّ ۚ","dalam kebenaran"],["يُفَصِّلُ","Dia menerangkan"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["لِقَوْمٍۢ","bagi kaum"],["يَعْلَمُونَ","(siapa) tahu"]]],"1370":["(Sesungguhnya pada pertukaran malam dan siang itu) silih bergantinya malam dan siang hari kemudian panjang dan pendeknya malam dan siang hari (dan pada yang diciptakan Allah di langit) yakni para malaikat, matahari, bulan dan bintang-bintang serta lain sebagainya (Dan) di (bumi) berupa margasatwa, gunung-gunung, lautan, sungai-sungai, pohon-pohon dan lain sebagainya (benar-benar terdapat tanda-tanda) yang menunjukkan kepada kekuasaan-Nya (bagi orang-orang yang bertakwa) kepada-Nya kemudian mereka beriman. Allah secara khusus menyebutkan orang-orang yang bertakwa karena sesungguhnya merekalah yang dapat memanfaatkan keberadaan tanda-tanda tersebut.",[["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ٱخْتِلَـٰفِ","(yang) silih berganti"],["ٱلَّيْلِ","(dari) malam"],["وَٱلنَّهَارِ","dan hari"],["وَمَا","dan apa"],["خَلَقَ","(telah) dicipta"],["ٱللَّهُ","(oleh) Allah"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["لَـَٔايَـٰتٍۢ","(adalah) Tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يَتَّقُونَ","yang bertakwa kepada Tuhan"]]],"1371":["(Sesungguhnya orang-orang yang tidak mengharapkan/tidak percaya akan pertemuan dengan Kami) pada hari berbangkit nanti (dan mereka merasa puas dengan kehidupan dunia) sebagai ganti daripada kehidupan akhirat karena mereka tidak mempercayai adanya hari akhirat itu (serta merasa tenteram dengan kehidupan itu) merasa tenang dengan kehidupan dunia (dan orang-orang yang terhadap ayat-ayat Kami) bukti-bukti yang menunjukkan kepada keesaan Kami (mereka melalaikan) mereka sama sekali tidak mau memikirkannya.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يَرْجُونَ","jangkakan"],["لِقَآءَنَا","pertemuan dengan Kami"],["وَرَضُوا۟","dan berpuas hati"],["بِٱلْحَيَوٰةِ","dengan kehidupan"],["ٱلدُّنْيَا","dunia"],["وَٱطْمَأَنُّوا۟","dan rasa puas"],["بِهَا","dengannya"],["وَٱلَّذِينَ","dan mereka"],["هُمْ","mereka"],["عَنْ","(adalah) daripada"],["ءَايَـٰتِنَا","Tanda-Tanda Kami"],["غَـٰفِلُونَ","lalai"]]],"1372":["(Mereka itu tempatnya ialah neraka disebabkan apa yang selalu mereka kerjakan) berupa kemusyrikan dan perbuatan-perbuatan maksiat.",[["أُو۟لَـٰٓئِكَ","Itu"],["مَأْوَىٰهُمُ","tempat tinggal mereka"],["ٱلنَّارُ","(akan menjadi) Neraka"],["بِمَا","bagi apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَكْسِبُونَ","peroleh"]]],"1373":["(Sesungguhnya orang-orang yang beriman dan mengerjakan amal-amal saleh, mereka diberi petunjuk) diberi bimbingan (oleh Rabb mereka karena keimanannya) kepada-Nya; kelak pada hari kiamat Allah swt. akan menjadikan bagi mereka cahaya dengan cahaya itu mereka mendapat petunjuk (di bawah mereka mengalir sungai-sungai di dalam surga yang penuh kenikmatan).",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan lakukan"],["ٱلصَّـٰلِحَـٰتِ","perbuatan baik"],["يَهْدِيهِمْ","(akan) membimbing mereka"],["رَبُّهُم","Tuhan mereka"],["بِإِيمَـٰنِهِمْ ۖ","dengan iman mereka"],["تَجْرِى","Akan mengalir"],["مِن","daripada"],["تَحْتِهِمُ","di bawah mereka"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["فِى","dalam"],["جَنَّـٰتِ","Taman-taman"],["ٱلنَّعِيمِ","(dari) Kegembiraan"]]],"1374":["(Doa mereka di dalamnya) sewaktu mereka meminta apa yang mereka inginkan di dalam surga hanya tinggal mengatakan (Subhaanakallaahumma) artinya Maha Suci Engkau ya Allah. Bilamana mereka telah memintanya maka mereka menemukan apa yang mereka inginkan telah berada di hadapan mereka (dan salam penghormatan mereka) di antara sesama mereka (di dalam surga ialah salam. Dan penutup doa mereka ialah) huruf an di sini adalah kata penafsir (alhamdulillaahi rabbil aalamiin) segala puji bagi Allah Rabb alam semesta. Ayat ini diturunkan sewaktu orang-orang musyrik meminta disegerakan turunnya azab.",[["دَعْوَىٰهُمْ","doa mereka"],["فِيهَا","di dalamnya"],["سُبْحَـٰنَكَ","(akan), \"Maha Suci Engkau"],["ٱللَّهُمَّ","Ya Allah"],["وَتَحِيَّتُهُمْ","Dan salam mereka"],["فِيهَا","di dalamnya (akan)"],["سَلَـٰمٌۭ ۚ","Damai"],["وَءَاخِرُ","Dan yang terakhir"],["دَعْوَىٰهُمْ","(dari) panggilan mereka"],["أَنِ","(akan) [itu]"],["ٱلْحَمْدُ","Segala Pujian"],["لِلَّهِ","kepada Allah"],["رَبِّ","Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"1375":["(Dan kalau sekiranya Allah menyegerakan kejahatan bagi manusia seperti permintaan mereka untuk menyegerakan) artinya sama seperti mereka meminta mendapatkan dengan segera (kebaikan, pastilah diakhiri) boleh dibaca laqudhiya atau laqadha (umur mereka) lafal ajaluhum dapat dibaca rafa` yakni menjadi ajaluhum dan dapat pula dibaca nashab hingga menjadi ajalahum; seumpamanya Allah membinasakan mereka dengan segera akan tetapi ternyata Allah menangguhkan (Maka Kami biarkan) Kami tinggalkan (orang-orang yang tidak mengharapkan pertemuan dengan Kami bergelimang di dalam kesesatan mereka) mereka hidup diselimuti oleh keraguan yang membingungkan.",[["۞ وَلَوْ","Dan jika"],["يُعَجِّلُ","mempercepatkan"],["ٱللَّهُ","(oleh) Allah"],["لِلنَّاسِ","untuk umat manusia"],["ٱلشَّرَّ","yang jahat"],["ٱسْتِعْجَالَهُم","(as) Dia bersegera untuk mereka"],["بِٱلْخَيْرِ","yang baik"],["لَقُضِىَ","pasti, telah ditetapkan"],["إِلَيْهِمْ","bagi mereka"],["أَجَلُهُمْ ۖ","istilah mereka"],["فَنَذَرُ","Tetapi Kami pergi"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يَرْجُونَ","jangkakan"],["لِقَآءَنَا","pertemuan dengan Kami"],["فِى","dalam"],["طُغْيَـٰنِهِمْ","pelanggaran mereka"],["يَعْمَهُونَ","merayau buta"]]],"1376":["(Dan apabila manusia ditimpa) yang dimaksud adalah orang kafir (bahaya) berupa penyakit dan kefakiran (dia berdoa kepada Kami dalam keadaan berbaring) membaringkan diri (atau duduk, atau berdiri) artinya dalam semua keadaan (tetapi setelah Kami hilangkan bahaya itu daripadanya dia kembali) kepada kekafirannya (seolah-olah) lafal ka-an berasal dari ka-anna yang ditakhfifkan sedangkan isimnya tidak disebutkan. Lengkapnya ka-annahu, artinya seolah-olah dia (tidak pernah berdoa kepada Kami untuk menghilangkan bahaya yang telah menimpanya. Begitulah) sifat orang kafir, yaitu berdoa di kala tertimpa bahaya dan berpaling di kala hidup sejahtera (orang-orang yang melampaui batas itu memandang baik) yang dimaksud adalah orang-orang musyrik (apa yang selalu mereka kerjakan).",[["وَإِذَا","Dan apabila"],["مَسَّ","sentuhan"],["ٱلْإِنسَـٰنَ","lelaki itu"],["ٱلضُّرُّ","penderitaan itu"],["دَعَانَا","dia memanggil Kami"],["لِجَنۢبِهِۦٓ","(berbaring) di sisinya"],["أَوْ","atau"],["قَاعِدًا","duduk"],["أَوْ","atau"],["قَآئِمًۭا","berdiri"],["فَلَمَّا","Tetapi apabila"],["كَشَفْنَا","Kami keluarkan"],["عَنْهُ","daripada dia"],["ضُرَّهُۥ","penderitaannya"],["مَرَّ","dia meneruskan"],["كَأَن","seolah-olah dia"],["لَّمْ","(ada) tidak"],["يَدْعُنَآ","dipanggil Kami"],["إِلَىٰ","bagi"],["ضُرٍّۢ","(the) penderitaan"],["مَّسَّهُۥ ۚ","(yang) menyentuhnya"],["كَذَٰلِكَ","Demikianlah"],["زُيِّنَ","(ia) dibuat seolah-olah adil"],["لِلْمُسْرِفِينَ","kepada yang boros"],["مَا","apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَعْمَلُونَ","lakukan"]]],"1377":["(Dan sesungguhnya Kami telah membinasakan umat-umat) generasi-generasi (yang sebelum kalian) hai penduduk Mekah (ketika mereka berbuat kelaliman) yaitu dengan melakukan kemusyrikan (padahal) sungguh (telah datang kepada mereka rasul-rasul mereka dengan membawa keterangan-keterangan yang nyata) bukti-bukti yang menunjukkan kebenaran risalah mereka (tetapi mereka sekali-kali tidak hendak beriman) kalimat ayat ini di'athafkan pada lafal lammaa zhalamuu. (Demikianlah) seperti yang telah Kami binasakan mereka (Kami memberi pembalasan kepada orang-orang yang berbuat dosa) yaitu orang-orang kafir.",[["وَلَقَدْ","Dan sesungguhnya"],["أَهْلَكْنَا","Kami musnahkan"],["ٱلْقُرُونَ","generasi"],["مِن","sebelum kamu"],["قَبْلِكُمْ","sebelum kamu"],["لَمَّا","apabila"],["ظَلَمُوا۟ ۙ","mereka melakukan kesalahan"],["وَجَآءَتْهُمْ","dan datang kepada mereka"],["رُسُلُهُم","Rasul-rasul mereka"],["بِٱلْبَيِّنَـٰتِ","dengan bukti yang jelas"],["وَمَا","tetapi tidak"],["كَانُوا۟","mereka adalah"],["لِيُؤْمِنُوا۟ ۚ","untuk beriman"],["كَذَٰلِكَ","Demikianlah"],["نَجْزِى","Kami membalas"],["ٱلْقَوْمَ","manusia"],["ٱلْمُجْرِمِينَ","(yang) penjenayah"]]],"1378":["(Kemudian Kami jadikan kalian) hai penduduk Mekah (pengganti-pengganti) lafal khalaaif adalah bentuk jamak dari lafal khaliifah (di muka bumi sesudah mereka supaya Kami memperhatikan bagaimana kalian berbuat) di muka bumi; apakah kalian mau mengambil pelajaran dari umat-umat terdahulu itu sehingga kalian mau percaya kepada rasul-rasul Kami.",[["ثُمَّ","Kemudian"],["جَعَلْنَـٰكُمْ","Kami membuat kamu"],["خَلَـٰٓئِفَ","pengganti"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["مِنۢ","selepas mereka"],["بَعْدِهِمْ","selepas mereka"],["لِنَنظُرَ","supaya Kami melihat"],["كَيْفَ","bagaimana"],["تَعْمَلُونَ","kamu lakukan"]]],"1379":["(Dan apabila dibacakan kepada mereka ayat-ayat Kami) yakni Alquran (yang nyata) yang jelas; lafal bayyinaatin kedudukannya menjadi hal atau kata keterangan keadaan (orang-orang yang tidak mengharapkan pertemuan dengan Kami berkata) mereka adalah orang-orang yang tidak takut akan adanya hari pembalasan (\"Datangkanlah Alquran yang lain dari ini) yang isinya tidak mengandung celaan kepada tuhan-tuhan kami (atau gantilah dia.\") dengan buatanmu sendiri (Katakanlah,) kepada mereka (\"Tidaklah pantas) tidak layak (bagiku menggantinya dari pihak) berdasarkan kemauan (diriku sendiri. Aku tidak) tiada lain (hanya mengikuti apa yang diwahyukan kepadaku. Sesungguhnya aku takut jika mendurhakai Rabbku) oleh sebab menggantikan Alquran (kepada siksa hari yang besar.\") yaitu hari kiamat.",[["وَإِذَا","Dan apabila"],["تُتْلَىٰ","dibacakan"],["عَلَيْهِمْ","kepada mereka"],["ءَايَاتُنَا","Ayat Kami"],["بَيِّنَـٰتٍۢ ۙ","(sebagai) bukti yang jelas"],["قَالَ","berkata"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يَرْجُونَ","harapan"],["لِقَآءَنَا","(untuk) pertemuan (dengan) Kami"],["ٱئْتِ","Bawa kami"],["بِقُرْءَانٍ","sebuah Al-Quran"],["غَيْرِ","selain daripada"],["هَـٰذَآ","ini"],["أَوْ","atau"],["بَدِّلْهُ ۚ","mengubahnya"],["قُلْ","Katakanlah"],["مَا","Tidak"],["يَكُونُ","(ia) ialah"],["لِىٓ","untuk aku"],["أَنْ","bahawa"],["أُبَدِّلَهُۥ","Aku mengubahnya"],["مِن","daripada"],["تِلْقَآئِ","kemahuan aku sendiri"],["نَفْسِىٓ ۖ","kemahuan aku sendiri"],["إِنْ","Tidak"],["أَتَّبِعُ","aku ikut"],["إِلَّا","kecuali"],["مَا","apa"],["يُوحَىٰٓ","didedahkan"],["إِلَىَّ ۖ","kepada aku"],["إِنِّىٓ","Sesungguhnya aku"],["أَخَافُ","[Aku] takut"],["إِنْ","jika"],["عَصَيْتُ","Aku terpaksa ingkar"],["رَبِّى","Tuhanku"],["عَذَابَ","azab"],["يَوْمٍ","(dari) sehari"],["عَظِيمٍۢ","Hebat"]]],"1380":["(Katakanlah, \"Jika Allah menghendaki, niscaya aku tidak membacakannya kepada kalian dan aku tidak pula memberitahukan kepada kalian) mengajarkan kepada kalian (mengenainya) huruf laa di sini bermakna nafi atau meniadakan, kemudian diathafkan kepada nafi yang sebelumnya. Menurut qiraat yang lain dianggap sebagai lam yang menjadi jawab daripada huruf lau, dengan demikian berarti niscaya aku akan mengajarkannya kepada kalian dengan bahasa yang bukan bahasaku (Sesungguhnya aku telah tinggal) diam (bersama dengan kalian beberapa lama) yaitu empat puluh tahun (sebelumnya.\") selama itu aku belum pernah menceritakan sesuatu kepada kalian (Maka apakah kalian tidak memikirkannya?) bahwasanya Alquran itu bukanlah buatanku sendiri.",[["قُل","Katakanlah"],["لَّوْ","Jika"],["شَآءَ","(telah) berkehendak"],["ٱللَّهُ","Allah"],["مَا","tidak"],["تَلَوْتُهُۥ","Aku (akan) membacanya"],["عَلَيْكُمْ","kepada kamu"],["وَلَآ","dan bukan"],["أَدْرَىٰكُم","Dia (akan) memberitahu kamu"],["بِهِۦ ۖ","Dia (akan) memberitahu kamu"],["فَقَدْ","Sesungguhnya"],["لَبِثْتُ","Aku telah tinggal"],["فِيكُمْ","antara kamu"],["عُمُرًۭا","seumur hidup"],["مِّن","sebelum itu"],["قَبْلِهِۦٓ ۚ","sebelum itu"],["أَفَلَا","Kemudian tidak akan"],["تَعْقِلُونَ","kamu menggunakan alasan"]]],"1381":["(Maka siapakah) artinya, tiada seorang pun (yang lebih lalim daripada orang yang mengada-adakan kedustaan terhadap Allah) yaitu dengan melakukan kemusyrikan terhadap Allah (atau mendustakan ayat-ayat-Nya?) yakni Alquran. (Sesungguhnya) pada kenyataannya (tiadalah beruntung) tiadalah berbahagia (orang-orang yang berbuat dosa) yaitu orang-orang musyrik.",[["فَمَنْ","Jadi siapa"],["أَظْلَمُ","(adalah) lebih salah"],["مِمَّنِ","daripada dia yang"],["ٱفْتَرَىٰ","mencipta"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["كَذِبًا","satu pembohongan"],["أَوْ","atau"],["كَذَّبَ","menafikan"],["بِـَٔايَـٰتِهِۦٓ ۚ","Tanda-tandaNya"],["إِنَّهُۥ","Sesungguhnya"],["لَا","tidak"],["يُفْلِحُ","akan berjaya"],["ٱلْمُجْرِمُونَ","penjenayah"]]],"1382":["(Dan mereka menyembah selain daripada Allah) (apa yang tidak dapat mendatangkan kemudaratan) jika mereka tidak menyembahnya (dan tidak pula kemanfaatan) jika mereka menyembahnya, yang dimaksud adalah berhala-berhala yang mereka sembah itu (dan mereka berkata,) tentang berhala-berhala itu (\"Mereka itu adalah pemberi syafaat kepada kami di sisi Allah.\" Katakanlah) kepada mereka (\"Apakah kalian mengabarkan kepada Allah) menceritakan kepada-Nya (apa yang tidak diketahui-Nya di langit dan tidak pula di bumi?\") Istifham atau kata tanya di sini mengandung makna ingkar, karena seandainya Dia mempunyai sekutu niscaya Dia akan mengetahui sekutunya itu karena sesungguhnya tiada sesuatu pun yang samar bagi-Nya. (Maha Suci Allah) dari hal-hal yang tidak layak bagi-Nya (dan Maha Tinggi daripada apa yang mereka persekutukan itu) bersama Allah.",[["وَيَعْبُدُونَ","Dan mereka menyembah"],["مِن","daripada"],["دُونِ","selain daripada"],["ٱللَّهِ","Allah"],["مَا","itu (yang)"],["لَا","tidak"],["يَضُرُّهُمْ","membahayakan mereka"],["وَلَا","dan bukan"],["يَنفَعُهُمْ","memberi manfaat kepada mereka"],["وَيَقُولُونَ","dan mereka berkata"],["هَـٰٓؤُلَآءِ","Ini"],["شُفَعَـٰٓؤُنَا","(adalah) pemberi syafaat kami"],["عِندَ","dengan"],["ٱللَّهِ ۚ","Allah"],["قُلْ","Katakanlah"],["أَتُنَبِّـُٔونَ","Adakah kamu memaklumkan"],["ٱللَّهَ","Allah"],["بِمَا","tentang apa"],["لَا","tidak"],["يَعْلَمُ","dia tahu"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَلَا","dan bukan"],["فِى","dalam"],["ٱلْأَرْضِ ۚ","bumi"],["سُبْحَـٰنَهُۥ","Maha Suci Dia"],["وَتَعَـٰلَىٰ","dan Maha Tinggi"],["عَمَّا","atas apa"],["يُشْرِكُونَ","mereka mempersekutukan (dengan Dia)"]]],"1383":["(Manusia dahulunya hanyalah satu umat) satu agama yaitu agama Islam, sejak dari zaman Nabi Adam sampai dengan zaman Nabi Nuh. Menurut pendapat yang lain dikatakan mulai dari zaman Nabi Ibrahim sampai dengan zamannya Amr bin Luhay (kemudian mereka berselisih) disebabkan sebagian daripada mereka tetap iman sedangkan sebagian yang lainnya kafir. (Kalau tidaklah karena suatu ketetapan yang telah ada dari Rabbmu dahulu) dengan menangguhkan pembalasan hingga hari kiamat (pastilah diberi keputusan di antara mereka) yaitu di antara manusia di dunia (tentang apa yang mereka perselisihkan itu) dalam masalah agama, yaitu dengan mengazab orang-orang kafir.",[["وَمَا","Dan tidak"],["كَانَ","adalah"],["ٱلنَّاسُ","umat manusia"],["إِلَّآ","tetapi"],["أُمَّةًۭ","sesebuah komuniti"],["وَٰحِدَةًۭ","satu"],["فَٱخْتَلَفُوا۟ ۚ","kemudian mereka berselisih pendapat"],["وَلَوْلَا","Dan sekiranya (ia) tidak berlaku"],["كَلِمَةٌۭ","satu perkataan"],["سَبَقَتْ","(yang) mendahului"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["لَقُضِىَ","nescaya ia (akan) mendapat keputusan"],["بَيْنَهُمْ","antara mereka"],["فِيمَا","berkenaan apa"],["فِيهِ","[di dalamnya]"],["يَخْتَلِفُونَ","mereka berbeza"]]],"1384":["(Dan mereka berkata,) yakni penduduk Mekah (\"Mengapa tidak) kenapa tidak (diturunkan kepadanya) dimaksud kepada Nabi Muhammad saw. (suatu keterangan dari Rabbnya?\") sebagaimana yang telah diberikan kepada para nabi lainnya, seperti mukjizat unta, mukjizat tongkat dan mukjizat tangan (Maka katakanlah,) kepada mereka (\"Sesungguhnya yang gaib itu) hal-hal yang gaib dari mata hamba-hamba Allah (kepunyaan Allah) antara lain ialah mukjizat-mukjizat, maka mukjizat-mukjizat itu tidak ada yang dapat mendatangkannya melainkan hanya seizin Allah. Sesungguhnya tugasku hanyalah menyampaikan (sebab itu tunggu sajalah oleh kalian) datangnya azab jika kalian tidak mau beriman (sesungguhnya aku bersama kalian termasuk orang-orang yang menunggu.\")",[["وَيَقُولُونَ","Dan mereka berkata"],["لَوْلَآ","kenapa tidak"],["أُنزِلَ","diturunkan"],["عَلَيْهِ","kepadanya"],["ءَايَةٌۭ","sebuah Tanda"],["مِّن","daripada"],["رَّبِّهِۦ ۖ","Tuhannya"],["فَقُلْ","Jadi katakan"],["إِنَّمَا","Hanya"],["ٱلْغَيْبُ","yang ghaib"],["لِلَّهِ","(adalah) untuk Allah"],["فَٱنتَظِرُوٓا۟","jadi tunggu"],["إِنِّى","sesungguhnya, aku"],["مَعَكُم","bersama kamu"],["مِّنَ","antara"],["ٱلْمُنتَظِرِينَ","mereka yang menunggu"]]],"1385":["(Dan apabila Kami merasakan kepada manusia) kepada orang-orang kafir Mekah (suatu rahmat) berupa hujan dan kesuburan (sesudah datangnya bahaya) kesengsaraan dan kekeringan (menimpa mereka, tiba-tiba mereka mempunyai tipu daya dalam menentang tanda-tanda kekuasaan Kami) dengan memperolok-olokkannya dan mendustakannya. (Katakanlah,) kepada mereka (\"Allah lebih cepat dalam membuat tipu daya\") sebagai pembalasan dari-Nya. (Sesungguhnya utusan-utusan Kami) yaitu para malaikat (menuliskan tipu daya kalian) lafal tamkuruuna dapat dibaca dengan memakai huruf ta sehingga menjadi tamkuruuna, dapat pula dibaca dengan huruf ya sehingga bacaannya menjadi yamkuruuna.",[["وَإِذَآ","Dan apabila"],["أَذَقْنَا","Kami membiarkan [manusia] merasai"],["ٱلنَّاسَ","Kami membiarkan [manusia] merasai"],["رَحْمَةًۭ","belas kasihan"],["مِّنۢ","selepas"],["بَعْدِ","selepas"],["ضَرَّآءَ","kesusahan"],["مَسَّتْهُمْ","telah menyentuh mereka"],["إِذَا","lihatlah"],["لَهُم","Mereka ada"],["مَّكْرٌۭ","plot"],["فِىٓ","terhadap"],["ءَايَاتِنَا ۚ","Ayat Kami"],["قُلِ","Katakanlah"],["ٱللَّهُ","Allah"],["أَسْرَعُ","(adalah) lebih pantas"],["مَكْرًا ۚ","(dalam) perancangan"],["إِنَّ","Sesungguhnya"],["رُسُلَنَا","Rasul-rasul Kami"],["يَكْتُبُونَ","tuliskan"],["مَا","apa"],["تَمْكُرُونَ","kamu merancang"]]],"1386":["(Dialah Tuhan yang menjadikan kalian dapat berjalan) menurut suatu qiraat yansyurukum bukannya yusayyirukum (di daratan, berlayar di laut. Sehingga apabila kalian berada di dalam bahtera) di dalam perahu-perahu (dan meluncurlah bahtera itu membawa orang-orang yang di dalamnya) di dalam lafal ini terkandung pengertian iltifat dari mukhathab menjadi ghaib (dengan tiupan angin yang baik) angin yang lembut (dan mereka bergembira karenanya, datanglah angin badai) angin yang kencang tiupannya dan dapat menghancurkan segala sesuatu yang dilandanya (dan gelombang dari segenap penjuru menimpanya, dan mereka yakin bahwa mereka telah dikepung bahaya) mereka pasti binasa (maka mereka berdoa kepada Allah dengan mengikhlaskan ketaatan kepada-Nya semata-mata) yakni berseru (\"Sesungguhnya jika) huruf lam di sini bermakna qasam atau sumpah (Engkau menyelamatkan kami dari bahaya ini) dari malapetaka ini (pastilah kami termasuk orang-orang yang bersyukur.\") yaitu akan menjadi orang-orang yang mentauhidkan Allah.",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["يُسَيِّرُكُمْ","membolehkan kamu melakukan perjalanan"],["فِى","dalam"],["ٱلْبَرِّ","bumi"],["وَٱلْبَحْرِ ۖ","dan laut"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["كُنتُمْ","kamu"],["فِى","dalam"],["ٱلْفُلْكِ","kapal-kapal itu"],["وَجَرَيْنَ","dan mereka belayar"],["بِهِم","bersama mereka"],["بِرِيحٍۢ","dengan angin"],["طَيِّبَةٍۢ","kebaikan"],["وَفَرِحُوا۟","dan mereka bergembira"],["بِهَا","di dalamnya"],["جَآءَتْهَا","datang kepadanya"],["رِيحٌ","angin"],["عَاصِفٌۭ","ribut"],["وَجَآءَهُمُ","dan datang kepada mereka"],["ٱلْمَوْجُ","ombak"],["مِن","daripada"],["كُلِّ","setiap"],["مَكَانٍۢ","tempat"],["وَظَنُّوٓا۟","dan mereka beranggapan"],["أَنَّهُمْ","bahawa mereka"],["أُحِيطَ","dikelilingi"],["بِهِمْ ۙ","bersama mereka"],["دَعَوُا۟","Mereka memanggil"],["ٱللَّهَ","Allah"],["مُخْلِصِينَ","ikhlas"],["لَهُ","kepada-Nya"],["ٱلدِّينَ","(dalam) agama"],["لَئِنْ","(sambil berkata), \"Jika"],["أَنجَيْتَنَا","Kamu selamatkan kami"],["مِنْ","daripada"],["هَـٰذِهِۦ","ini"],["لَنَكُونَنَّ","pasti kita akan jadi"],["مِنَ","antara"],["ٱلشَّـٰكِرِينَ","yang bersyukur"]]],"1387":["(Maha setelah Allah menyelamatkan mereka, tiba-tiba mereka membuat kelaliman di muka bumi tanpa alasan yang benar) mereka melakukan kemusyrikan. (Hai manusia, sesungguhnya perbuatan kelewat batas kalian) perbuatan kelaliman kalian (akan menimpa diri kalian sendiri) karena sesungguhnya yang menanggung dosanya adalah diri kalian sendiri (hal itu hanyalah kenikmatan duniawi) kalian bersenang-senang dengannya dalam waktu yang sedikit. (Kemudian kepada Kamilah kembali kalian) sesudah mati (lalu Kami kabarkan kepada kalian apa yang telah kalian kerjakan) maka Kami membalas kalian berdasarkannya. Menurut suatu qiraat lafal mataa'un dibaca nashab sehingga menjadi mataa'an, artinya kalian bersenang-senang.",[["فَلَمَّآ","Tetapi apabila"],["أَنجَىٰهُمْ","Dia menyelamatkan mereka"],["إِذَا","lihatlah"],["هُمْ","mereka"],["يَبْغُونَ","memberontak"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["بِغَيْرِ","tanpa"],["ٱلْحَقِّ ۗ","[yang] betul"],["يَـٰٓأَيُّهَا","Wahai umat manusia"],["ٱلنَّاسُ","Wahai umat manusia"],["إِنَّمَا","Hanya"],["بَغْيُكُمْ","pemberontakan kamu"],["عَلَىٰٓ","(adalah) menentang"],["أَنفُسِكُم ۖ","kamu sendiri"],["مَّتَـٰعَ","(the) kenikmatan"],["ٱلْحَيَوٰةِ","(dari) kehidupan"],["ٱلدُّنْيَا ۖ","dunia"],["ثُمَّ","Kemudian"],["إِلَيْنَا","kepada Kami"],["مَرْجِعُكُمْ","(adalah) kamu kembali"],["فَنُنَبِّئُكُم","dan Kami akan memaklumkan kepada kamu"],["بِمَا","tentang apa"],["كُنتُمْ","kamu pernah (untuk)"],["تَعْمَلُونَ","lakukan"]]],"1388":["(Sesungguhnya perumpamaan) gambaran (kehidupan duniawi itu adalah seperti air) hujan (yang Kami turunkan dari langit lalu tumbuhlah berkat air itu dengan suburnya) oleh sebab air itu (tanaman-tanaman bumi) sehingga sebagian di antaranya tampak bersatu dengan sebagian yang lain karena rimbunnya (di antaranya ada yang dimakan manusia) berupa biji jawawut, biji gandum dan lain sebagainya (dan binatang ternak) yaitu berupa rerumputan dan dedaunan. (Hingga apabila bumi itu telah sempurna keindahannya) menampakkan keindahannya berkat tumbuh-tumbuhannya (dan memakai pula perhiasannya) karena bunga-bungaannya. Asal kata wazzayyanat adalah tazayyanat, kemudian huruf ta diganti dengan huruf za, yang selanjutnya huruf za yang pengganti ini diidghamkan atau dimasukkan ke dalam huruf za asal, sehingga jadilah izzayyanat (dan pemilik-pemiliknya mengira bahwa mereka pasti menguasainya) mereka merasa pasti akan dapat memetik hasilnya (tiba-tiba datanglah kepadanya perkara Kami) kepastian atau azab Kami (di waktu malam hari atau siang, lalu Kami jadikan ia) yakni tanam-tanamannya (laksana tanam-tanaman yang sudah disabit) sudah dipanen dengan memakai sabit (seakan-akan) lafal ka-an adalah mukhaffafah dari lafal ka-anna, artinya seakan-akan ia (belum pernah tumbuh) belum pernah berujud (kemarin. Demikianlah Kami menjelaskan) Kami terangkan (tanda-tanda kekuasaan Kami kepada orang-orang yang berpikir).",[["إِنَّمَا","Hanya"],["مَثَلُ","(the) contoh"],["ٱلْحَيَوٰةِ","(dari) kehidupan"],["ٱلدُّنْيَا","dunia"],["كَمَآءٍ","(ialah) seperti air"],["أَنزَلْنَـٰهُ","yang Kami turunkan"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["فَٱخْتَلَطَ","jadi menyerap"],["بِهِۦ","[dengan] itu"],["نَبَاتُ","(the) tumbuhan"],["ٱلْأَرْضِ","(dari) bumi"],["مِمَّا","dari mana"],["يَأْكُلُ","makan"],["ٱلنَّاسُ","kaum lelaki"],["وَٱلْأَنْعَـٰمُ","dan lembu"],["حَتَّىٰٓ","sehingga"],["إِذَآ","apabila"],["أَخَذَتِ","mengambil"],["ٱلْأَرْضُ","bumi"],["زُخْرُفَهَا","perhiasannya"],["وَٱزَّيَّنَتْ","dan dicantikkan"],["وَظَنَّ","dan berfikir"],["أَهْلُهَآ","rakyatnya"],["أَنَّهُمْ","bahawa mereka"],["قَـٰدِرُونَ","mempunyai kuasa"],["عَلَيْهَآ","atasnya"],["أَتَىٰهَآ","datang (kepada)nya"],["أَمْرُنَا","Perintah kami"],["لَيْلًا","(menjelang) malam"],["أَوْ","atau"],["نَهَارًۭا","(mengikut) hari"],["فَجَعَلْنَـٰهَا","dan Kami membuatnya"],["حَصِيدًۭا","tuaian yang dipotong bersih"],["كَأَن","seolah-olah"],["لَّمْ","tidak"],["تَغْنَ","ia telah berkembang"],["بِٱلْأَمْسِ ۚ","semalam"],["كَذَٰلِكَ","Demikianlah"],["نُفَصِّلُ","Kami terangkan"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["لِقَوْمٍۢ","bagi kaum"],["يَتَفَكَّرُونَ","yang merenung"]]],"1389":["(Allah menyeru ke darussalam) kepada jalan keselamatan, yaitu surga; Dia menyeru manusia pada keimanan (dan menunjuki orang yang dikehendaki-Nya) untuk mendapat petunjuk (kepada jalan yang lurus) yakni agama Islam.",[["وَٱللَّهُ","Dan Allah"],["يَدْعُوٓا۟","panggilan"],["إِلَىٰ","kepada"],["دَارِ","(the) Rumah"],["ٱلسَّلَـٰمِ","(dari) Damai"],["وَيَهْدِى","dan panduan"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["إِلَىٰ","kepada"],["صِرَٰطٍۢ","(jalan) yang lurus"],["مُّسْتَقِيمٍۢ","(jalan) yang lurus"]]],"1390":["(Bagi orang-orang yang berbuat baik) dengan keimanannya (ada pahala yang terbaik) yaitu surga (dan tambahannya) yaitu dapat melihat Allah swt. sebagaimana yang telah diterangkan di dalam hadis sahih Muslim. (Dan tidak pernah layu) tidak pernah tertutup (wajah mereka oleh kekelaman) kesusahan yang kelam (dan tidak pula oleh kehinaan) kesedihan. (Mereka itulah penghuni surga, mereka kekal di dalamnya.)",[["۞ لِّلَّذِينَ","Bagi mereka yang"],["أَحْسَنُوا۟","berbuat baik"],["ٱلْحُسْنَىٰ","(adalah) yang terbaik"],["وَزِيَادَةٌۭ ۖ","dan banyak lagi"],["وَلَا","Dan tidak"],["يَرْهَقُ","(akan) meliputi"],["وُجُوهَهُمْ","muka mereka"],["قَتَرٌۭ","habuk"],["وَلَا","dan bukan"],["ذِلَّةٌ ۚ","penghinaan"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلْجَنَّةِ ۖ","(dari) Syurga"],["هُمْ","mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","(akan) kekal selama-lamanya"]]],"1391":["(Dan orang-orang) lafal ayat ini diathafkan kepada lafal alladziina ahsanuu yang ada pada ayat sebelumnya; artinya dan bagi orang-orang (yang mengerjakan keburukan) orang-orang yang mengerjakan kemusyrikan (mendapat balasan yang setimpal dan mereka ditutupi oleh kehinaan. Tidak ada bagi mereka, dari azab Allah) huruf min pada ayat ini adalah huruf zaidah atau tambahan (seorang pelindung pun) yang dapat mencegahnya (seakan-akan tertutupi) diselimuti (muka mereka oleh kepingan-kepingan) dapat dibaca qitha`an dan dapat pula dibaca qith`an (malam yang gelap-gulita. Mereka itulah penghuni neraka; mereka kekal di dalamnya).",[["وَٱلَّذِينَ","Dan orang yang"],["كَسَبُوا۟","diperolehi"],["ٱلسَّيِّـَٔاتِ","perbuatan jahat itu"],["جَزَآءُ","(the) balasan"],["سَيِّئَةٍۭ","(dari) perbuatan jahat"],["بِمِثْلِهَا","(adalah) seperti itu"],["وَتَرْهَقُهُمْ","dan (akan) menutupi mereka"],["ذِلَّةٌۭ ۖ","penghinaan"],["مَّا","Mereka tidak akan mempunyai"],["لَهُم","Mereka tidak akan mempunyai"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["مِنْ","sebarang"],["عَاصِمٍۢ ۖ","pertahanan"],["كَأَنَّمَآ","Seolah-olah"],["أُغْشِيَتْ","telah dilindungi"],["وُجُوهُهُمْ","muka mereka"],["قِطَعًۭا","(dengan) kepingan"],["مِّنَ","daripada"],["ٱلَّيْلِ","kegelapan malam"],["مُظْلِمًا ۚ","kegelapan malam"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلنَّارِ ۖ","(dari) api"],["هُمْ","mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","(akan) kekal selama-lamanya"]]],"1392":["(Dan) ingatlah (suatu hari, ketika itu Kami mengumpulkan mereka) yakni semua makhluk (semuanya, kemudian Kami berkata kepada orang-orang yang mempersekutukan Tuhan, \"Tetaplah pada tempat kalian) lafal makaanakum dinashabkan oleh ilzamuu yang keberadaannya diperkirakan pada sebelumnya (kalian semuanya) lafal ini bersifat mengukuhkan dhamir mustatar yang terkandung di dalam fi'il yang keberadaannya diperkirakan tadi, kemudian diathafkan kepadanya (bersama dengan sekutu-sekutu kalian) yakni berhala-berhala sesembahan kalian. (Lalu Kami pisahkan) Kami bedakan (antara mereka\") dan orang-orang yang beriman, sebagaimana yang telah disebutkan dalam ayat: (Dan dikatakan kepada orang-orang kafir), 'Berpisahlah kalian (dari orang-orang mukmin) pada hari ini, hai orang-orang yang berbuat jahat. (Yasin 59). (Dan berkatalah) kepada mereka (sekutu-sekutu mereka, \"Kalian sekali-kali tidak pernah menyembah kami) huruf maa bermakna nafi, kemudian maf'ul didahulukan demi untuk fashilah.",[["وَيَوْمَ","Dan (hari) itu"],["نَحْشُرُهُمْ","Kami akan mengumpulkan mereka"],["جَمِيعًۭا","semua bersama"],["ثُمَّ","kemudian"],["نَقُولُ","Kami akan berkata"],["لِلَّذِينَ","kepada mereka yang"],["أَشْرَكُوا۟","mempersekutukan (dengan Allah)"],["مَكَانَكُمْ","(Kekal di) tempat kamu"],["أَنتُمْ","kamu"],["وَشُرَكَآؤُكُمْ ۚ","dan rakan kongsi kamu"],["فَزَيَّلْنَا","Kemudian Kami akan berpisah"],["بَيْنَهُمْ ۖ","[antara] mereka"],["وَقَالَ","dan (akan) berkata"],["شُرَكَآؤُهُم","rakan kongsi mereka"],["مَّا","Tidak"],["كُنتُمْ","kamu pernah (untuk)"],["إِيَّانَا","menyembah kami"],["تَعْبُدُونَ","menyembah kami"]]],"1393":["(Dan cukuplah Allah menjadi saksi antara kami dengan kalian, sesungguhnya) huruf in adalah mukhaffafah dari inna (kami tidak tahu-menahu tentang penyembahan kalian kepada kami.\")",[["فَكَفَىٰ","Begitu memadai"],["بِٱللَّهِ","(ialah) Allah"],["شَهِيدًۢا","(sebagai) saksi"],["بَيْنَنَا","antara kita"],["وَبَيْنَكُمْ","dan antara kamu"],["إِن","bahawa"],["كُنَّا","kami"],["عَنْ","daripada"],["عِبَادَتِكُمْ","ibadahmu"],["لَغَـٰفِلِينَ","tentu tidak sedar"]]],"1394":["(Di tempat itu) yakni pada hari itu (akan merasakan pembalasan) lafal tabluu berasal dari mashdar al-balwaa. Akan tetapi menurut qiraat lainnya dibaca tatluu berasal dari mashdar tilaawah; artinya dibacakan (tiap-tiap diri dari apa yang telah dikerjakannya dahulu) amal-amal perbuatan yang telah mereka kerjakan di dunia (dan mereka dikembalikan kepada Allah Pelindung mereka yang sebenarnya) pelindung yang hak dan yang selama-lamanya (dan lenyaplah) hilanglah (dari mereka apa yang mereka ada-adakan) terhadap Allah swt. yaitu berupa sekutu-sekutu yang mereka sembah itu.",[["هُنَالِكَ","di sana"],["تَبْلُوا۟","akan dibicarakan"],["كُلُّ","setiap"],["نَفْسٍۢ","jiwa"],["مَّآ","(untuk) apa"],["أَسْلَفَتْ ۚ","ia berlaku sebelum ini"],["وَرُدُّوٓا۟","dan mereka akan dikembalikan"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["مَوْلَىٰهُمُ","Tuhan mereka"],["ٱلْحَقِّ ۖ","yang benar"],["وَضَلَّ","dan akan hilang"],["عَنْهُم","daripada mereka"],["مَّا","apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَفْتَرُونَ","mencipta"]]],"1395":["(Katakanlah,) kepada mereka (\"Siapakah yang memberi rezeki kepada kalian dari langit) yaitu melalui hujan (dan bumi) yaitu melalui tumbuh-tumbuhan (atau siapakah yang kuasa menciptakan pendengaran) lafal as-sam`u di sini bermakna al-asma`; artinya yang menciptakan pendengaran (dan penglihatan dan siapakah yang mengeluarkan yang hidup dari yang mati dan mengeluarkan yang mati dari yang hidup dan siapakah yang mengatur segala urusan?\") di antara makhluk semuanya. (Maka mereka katakan,) bahwa Dia (\"Allah.\" Maka katakanlah,) kepada mereka (\"Mengapa kalian tidak bertakwa.\") kepada-Nya, oleh sebab itu berimanlah kalian.",[["قُلْ","Katakanlah"],["مَن","Siapa"],["يَرْزُقُكُم","menyediakan untuk kamu"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["أَمَّن","Atau siapa"],["يَمْلِكُ","kawalan"],["ٱلسَّمْعَ","pendengaran"],["وَٱلْأَبْصَـٰرَ","dan penglihatan"],["وَمَن","Dan siapa"],["يُخْرِجُ","membawa keluar"],["ٱلْحَىَّ","yang hidup"],["مِنَ","daripada"],["ٱلْمَيِّتِ","yang mati"],["وَيُخْرِجُ","dan melahirkan"],["ٱلْمَيِّتَ","yang mati"],["مِنَ","daripada"],["ٱلْحَىِّ","yang hidup"],["وَمَن","Dan siapa"],["يُدَبِّرُ","membuang"],["ٱلْأَمْرَ ۚ","urusan"],["فَسَيَقُولُونَ","Kemudian mereka akan berkata"],["ٱللَّهُ ۚ","Allah"],["فَقُلْ","Kemudian katakan"],["أَفَلَا","Kemudian tidak akan"],["تَتَّقُونَ","kamu takut (dia)"]]],"1396":["(Maka yang demikian itu) Zat Yang menciptakan segala sesuatu itu (adalah Allah, Rabb kalian yang sebenarnya) yang tetap dan wajib kalian sembah (maka tidak ada sesudah kebenaran itu melainkan kesesatan) Istifham atau kata tanya di sini bermakna menetapkan; artinya tidak ada sesudah kebenaran itu melainkan hanya kesesatan belaka. Barang siapa yang menyimpang dari kebenaran yaitu menyembah selain kepada Allah berarti ia terjerumus ke dalam kesesatan (Maka bagaimanakah) mengapa (kalian dipalingkan?) dari keimanan padahal bukti-bukti kebenaran telah cukup ada.",[["فَذَٰلِكُمُ","Untuk itu"],["ٱللَّهُ","(ialah) Allah"],["رَبُّكُمُ","Tuhanmu"],["ٱلْحَقُّ ۖ","yang benar"],["فَمَاذَا","Jadi apa (boleh)"],["بَعْدَ","selepas"],["ٱلْحَقِّ","kebenaran"],["إِلَّا","kecuali"],["ٱلضَّلَـٰلُ ۖ","kesilapan itu"],["فَأَنَّىٰ","Jadi bagaimana"],["تُصْرَفُونَ","(adakah) kamu berpaling"]]],"1397":["(Demikianlah) sebagaimana mereka berpaling daripada iman (telah tetap hukuman Rabbmu terhadap orang-orang yang fasik) yakni orang-orang kafir, seperti yang diungkapkan oleh firman Allah yang lain, yaitu: \"Benar-benar Aku akan mengisi neraka Jahanam...\" (Q.S. Al-A`raf 18, Hud 119, As-Sajdah 32, Shad 85), atau hukuman Allah itu disebabkan (karena mereka tidak beriman.)",[["كَذَٰلِكَ","Demikianlah"],["حَقَّتْ","(adalah) terbukti benar"],["كَلِمَتُ","(the) Firman"],["رَبِّكَ","Tuhanmu"],["عَلَى","ke atas"],["ٱلَّذِينَ","orang yang"],["فَسَقُوٓا۟","membangkang menderhaka"],["أَنَّهُمْ","bahawa mereka"],["لَا","(akan) tidak"],["يُؤْمِنُونَ","beriman"]]],"1398":["(Katakanlah, \"Apakah di antara sekutu-sekutu kalian ada yang dapat memulai penciptaan makhluk, kemudian mengulanginya atau menghidupkannya kembali?\" Katakanlah, \"Allahlah yang memulai penciptaan makhluk kemudian mengulanginya atau menghidupkannya kembali; maka bagaimanakah kalian dipalingkan?\") dari menyembah Allah swt. padahal bukti-bukti yang menunjukkan Allah disembah sudah ada.",[["قُلْ","Katakanlah"],["هَلْ","Adakah (ada)"],["مِن","daripada"],["شُرَكَآئِكُم","rakan kongsi kamu"],["مَّن","(mana-mana) siapa"],["يَبْدَؤُا۟","berasal"],["ٱلْخَلْقَ","penciptaan"],["ثُمَّ","kemudian"],["يُعِيدُهُۥ ۚ","mengulanginya"],["قُلِ","Katakanlah"],["ٱللَّهُ","Allah"],["يَبْدَؤُا۟","berasal"],["ٱلْخَلْقَ","penciptaan"],["ثُمَّ","kemudian"],["يُعِيدُهُۥ ۖ","mengulanginya"],["فَأَنَّىٰ","Jadi bagaimana"],["تُؤْفَكُونَ","kamu tertipu"]]],"1399":["(Katakanlah, \"Apakah di antara sekutu-sekutu kalian ada yang dapat menunjuki kepada kebenaran?\") dengan menegakkan hujah-hujah dan memberikan petunjuk (Katakanlah, \"Allahlah yang menunjuki kepada kebenaran.\" Maka apakah Zat yang menunjuki kepada kebenaran itu) yang dimaksud adalah Allah (lebih berhak diikuti ataukah orang yang tidak dapat memberi petunjuk) lafal yahiddiy asalnya yahtadii; artinya mendapat petunjuk (kecuali bila diberi petunjuk?) lebih berhak untuk diikuti? Kata tanya di sini mengandung makna mengukuhkan dan sekaligus sebagai celaan, makna yang dimaksud ialah bahwa yang pertamalah yang lebih berhak untuk diikuti (Mengapa kalian berbuat demikian? Bagaimanakah kalian mengambil keputusan) dengan keputusan yang rusak ini, yaitu mengikuti orang-orang yang tidak berhak untuk diikuti.",[["قُلْ","Katakanlah"],["هَلْ","Adakah (ada)"],["مِن","daripada"],["شُرَكَآئِكُم","rakan kongsi kamu"],["مَّن","(mana-mana) siapa"],["يَهْدِىٓ","panduan"],["إِلَى","kepada"],["ٱلْحَقِّ ۚ","kebenaran"],["قُلِ","Katakanlah"],["ٱللَّهُ","Allah"],["يَهْدِى","panduan"],["لِلْحَقِّ ۗ","kepada kebenaran"],["أَفَمَن","Adakah maka (dia) yang"],["يَهْدِىٓ","panduan"],["إِلَى","kepada"],["ٱلْحَقِّ","kebenaran"],["أَحَقُّ","lebih layak"],["أَن","bahawa"],["يُتَّبَعَ","dia patut diikuti"],["أَمَّن","atau (dia) yang"],["لَّا","tidak"],["يَهِدِّىٓ","panduan"],["إِلَّآ","melainkan"],["أَن","[bahawa]"],["يُهْدَىٰ ۖ","dia diberi petunjuk"],["فَمَا","Kemudian apa"],["لَكُمْ","(adalah) untuk kamu"],["كَيْفَ","bagaimana"],["تَحْكُمُونَ","kamu menilai"]]],"1400":["(Dan kebanyakan mereka tidak mengikuti) di dalam penyembahan mereka terhadap berhala-berhala (kecuali persangkaan saja) dalam hal ini mereka hanya menirukan apa yang telah diperbuat oleh nenek-moyang mereka (Sesungguhnya prasangka itu tidak sedikit pun berguna untuk mencapai kebenaran) yang membutuhkan ilmu pengetahuan tentangnya (Sesungguhnya Allah Maha Mengetahui apa yang mereka kerjakan) oleh sebab itu maka Dia membalas semua amal perbuatan yang telah mereka kerjakan itu.",[["وَمَا","Dan tidak"],["يَتَّبِعُ","ikut"],["أَكْثَرُهُمْ","kebanyakan mereka"],["إِلَّا","kecuali"],["ظَنًّا ۚ","andaian"],["إِنَّ","Sesungguhnya"],["ٱلظَّنَّ","andaian itu"],["لَا","tidak"],["يُغْنِى","manfaat"],["مِنَ","terhadap"],["ٱلْحَقِّ","kebenaran"],["شَيْـًٔا ۚ","sesuatu"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلِيمٌۢ","Maha Mengetahui"],["بِمَا","tentang apa"],["يَفْعَلُونَ","mereka lakukan"]]],"1401":["(Tidaklah mungkin Alquran ini dibuat) artinya dibuat-buat (oleh selain Allah) hanya Dialah yang membuatnya bukan selainnya (akan tetapi) Alquran itu diturunkan (membenarkan apa-apa yang sebelumnya) yaitu berupa kitab-kitab sebelumnya (dan menjelaskan hukum-hukum yang telah ditetapkan-Nya) artinya Alquran itu menjelaskan hukum-hukum yang telah ditentukan oleh Allah dan masalah-masalah lainnya (tidak ada keraguan) tidak ada syakwasangka lagi (di dalamnya, diturunkan dari Rabb semesta alam) lafal min rabbil `aalamiina berkaitan dengan lafal tashdiiqan, atau berkaitan dengan lafal unzila yang tidak disebutkan. Lafal tashdiiqan dan lafal tafshiilan dapat pula dibaca rafa' sehingga menjadi tashdiiqun dan tafshiilun akan tetapi berdasarkan perkiraan adanya lafal huwa sebelumnya.",[["وَمَا","Dan tidak"],["كَانَ","ialah"],["هَـٰذَا","ini"],["ٱلْقُرْءَانُ","al-Quran"],["أَن","bahawa"],["يُفْتَرَىٰ","(ia boleh) dihasilkan"],["مِن","oleh"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["وَلَـٰكِن","tetapi"],["تَصْدِيقَ","(ia adalah) pengesahan"],["ٱلَّذِى","(daripada itu) yang"],["بَيْنَ","(ada) sebelum itu"],["يَدَيْهِ","(ada) sebelum itu"],["وَتَفْصِيلَ","dan penerangan terperinci"],["ٱلْكِتَـٰبِ","Kitab"],["لَا","(ada) tidak"],["رَيْبَ","keraguan"],["فِيهِ","di dalamnya"],["مِن","daripada"],["رَّبِّ","(yang) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"1402":["(Atau) patutkah (mereka mengatakan, \"Muhammad membuat-buatnya.\") yakni Nabi Muhammad saw. telah membuatnya sendiri. (Katakanlah, \"Kalau benar yang kalian katakan itu, maka cobalah datangkan sebuah surah seumpamanya) dalam hal kefasihan dan keparamasastraannya yang kalian buat sendiri, bukankah kalian itu adalah orang-orang Arab yang fasih dalam berbahasa sama denganku (dan panggillah) untuk membantu dalam hal ini (siapa-siapa yang dapat kalian panggil selain Allah) selain daripada Allah (jika kalian orang-orang yang benar\") bahwasanya Alquran itu adalah buatan belaka, niscaya kalian tidak akan mampu melakukannya. Selanjutnya Allah berfirman:",[["أَمْ","Atau"],["يَقُولُونَ","(lakukan) mereka berkata"],["ٱفْتَرَىٰهُ ۖ","Dia telah menciptanya"],["قُلْ","Katakanlah"],["فَأْتُوا۟","Kemudian bawa"],["بِسُورَةٍۢ","a Surah"],["مِّثْلِهِۦ","suka"],["وَٱدْعُوا۟","dan panggil"],["مَنِ","sesiapa sahaja"],["ٱسْتَطَعْتُم","kamu boleh"],["مِّن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"1403":["(Yang sebenarnya, mereka mendustakan apa yang mereka belum mengetahuinya dengan sempurna) subjek yang dimaksud adalah Alquran; mereka sama sekali tidak mau memikirkan tentangnya (dan belum pernah) tidak pernah (datang kepada mereka penjelasannya) akibat dari apa yang terkandung di dalamnya, yaitu berupa ancaman. (Demikianlah) yakni kedustaan itu (orang-orang yang sebelum mereka telah mendustakan) rasul-rasul mereka (Maka perhatikanlah bagaimana akibat orang-orang yang lalim itu) yaitu mereka yang mendustakan para rasul, makna yang dimaksud ialah kebinasaan yang telah menimpa mereka, demikian pula Kami akan membinasakan mereka yang mendustakannya.",[["بَلْ","Bahkan"],["كَذَّبُوا۟","mereka menafikan"],["بِمَا","apa"],["لَمْ","tidak"],["يُحِيطُوا۟","mereka boleh merangkumi"],["بِعِلْمِهِۦ","(dari) pengetahuannya"],["وَلَمَّا","dan bukan"],["يَأْتِهِمْ","telah datang (kepada) mereka"],["تَأْوِيلُهُۥ ۚ","tafsirannya"],["كَذَٰلِكَ","Demikianlah"],["كَذَّبَ","dinafikan"],["ٱلَّذِينَ","mereka"],["مِن","sebelum mereka"],["قَبْلِهِمْ ۖ","sebelum mereka"],["فَٱنظُرْ","kemudian lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلظَّـٰلِمِينَ","(dari) orang-orang yang zalim"]]],"1404":["(Di antara mereka) penduduk Mekah (ada arang-orang yang beriman kepada Alquran) hal ini diketahui oleh Allah (dan di antara mereka ada pula orang-orang yang tidak beriman kepadanya) untuk selama-lamanya. (Rabbmu lebih mengetahui tentang orang-orang yang berbuat kerusakan) hal ini merupakan ancaman yang ditujukan kepada mereka yang tidak beriman kepadanya,",[["وَمِنْهُم","Dan daripada mereka"],["مَّن","(adalah seorang) siapa"],["يُؤْمِنُ","beriman"],["بِهِۦ","di dalamnya"],["وَمِنْهُم","dan daripada mereka"],["مَّن","(adalah seorang) siapa"],["لَّا","tidak"],["يُؤْمِنُ","beriman"],["بِهِۦ ۚ","di dalamnya"],["وَرَبُّكَ","Dan Tuhanmu"],["أَعْلَمُ","Maha Mengetahui"],["بِٱلْمُفْسِدِينَ","daripada para perasuah"]]],"1405":["(Jika mereka mendustakan kamu, maka katakanlah,) kepada mereka (\"Bagiku pekerjaanku dan bagi kalian pekerjaan kalian) artinya bagi masing-masing pihak menanggung akibat perbuatannya sendiri. Kalian berlepas diri terhadap apa yang aku kerjakan dan aku berlepas diri terhadap apa yang kalian kerjakan.\") akan tetapi ayat itu dinasakh oleh ayatus-saif atau ayat yang menganjurkan memerangi mereka.",[["وَإِن","Dan jika"],["كَذَّبُوكَ","mereka menafikan kamu"],["فَقُل","kemudian berkata"],["لِّى","Bagi aku"],["عَمَلِى","(adalah) perbuatanku"],["وَلَكُمْ","dan untuk kamu"],["عَمَلُكُمْ ۖ","(adalah) perbuatan kamu"],["أَنتُم","kamu"],["بَرِيٓـُٔونَ","(adalah) dipisahkan"],["مِمَّآ","daripada apa"],["أَعْمَلُ","aku buat"],["وَأَنَا۠","dan aku"],["بَرِىٓءٌۭ","dipisahkan"],["مِّمَّا","daripada apa"],["تَعْمَلُونَ","kamu lakukan"]]],"1406":["(Dan di antara mereka ada orang yang mendengarkanmu) jika kamu membacakan Alquran (apakah kamu dapat menjadikan orang-orang tuli itu mendengar) keadaan mereka yang tidak mau mengambil manfaat daripada Alquran yang dibacakan kepada mereka diserupakan dengan keadaan orang-orang yang tuli (walaupun keadaan mereka) di samping tuli itu (tidak mengerti) tidak mau berpikir.",[["وَمِنْهُم","Dan di antara mereka"],["مَّن","(adalah beberapa) siapa"],["يَسْتَمِعُونَ","dengar"],["إِلَيْكَ ۚ","kepada kamu"],["أَفَأَنتَ","Tetapi (boleh) kamu"],["تُسْمِعُ","menyebabkan orang pekak mendengar"],["ٱلصُّمَّ","menyebabkan orang pekak mendengar"],["وَلَوْ","walaupun"],["كَانُوا۟","mereka [adalah]"],["لَا","jangan"],["يَعْقِلُونَ","guna akal"]]],"1407":["(Dan di antara mereka ada orang yang melihat kepadamu, apakah dapat kamu memberi petunjuk kepada orang-orang yang buta, walaupun mereka tidak dapat memperhatikan) Allah swt. menyerupakan keadaan mereka dengan keadaan orang-orang yang tidak dapat melihat, karena mereka tidak mau mengambil petunjuk dari apa yang mereka lihat. Bahkan keadaan mereka lebih parah lagi; gambaran ini diungkapkan pula di dalam firman-Nya yang lain, yaitu, \"Karena sesungguhnya bukanlah mata itu yang buta, tetapi yang buta ialah hati yang di dalam dada.\" (Al-Hajj 46).",[["وَمِنْهُم","Dan di antara mereka"],["مَّن","(adalah beberapa) siapa"],["يَنظُرُ","tengok"],["إِلَيْكَ ۚ","pada kamu"],["أَفَأَنتَ","Tetapi (boleh) kamu"],["تَهْدِى","panduan"],["ٱلْعُمْىَ","yang buta"],["وَلَوْ","walaupun"],["كَانُوا۟","mereka [adalah]"],["لَا","jangan"],["يُبْصِرُونَ","lihat"]]],"1408":["(Sesungguhnya Allah tidak berbuat lalim kepada manusia sedikit pun, akan tetapi manusia itulah yang berbuat lalim kepada diri mereka sendiri).",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يَظْلِمُ","salah"],["ٱلنَّاسَ","manusia"],["شَيْـًۭٔا","(dalam) apa-apa"],["وَلَـٰكِنَّ","tetapi"],["ٱلنَّاسَ","manusia"],["أَنفُسَهُمْ","salah diri sendiri"],["يَظْلِمُونَ","salah diri sendiri"]]],"1409":["(Dan di hari ketika Allah mengumpulkan mereka, seakan-akan) artinya keadaan mereka seolah-olah (tidak pernah tinggal) di dunia atau di alam kubur (melainkan hanya sesaat saja di siang hari) mengingat kengerian yang mereka lihat pada saat itu. Jumlah tasybih atau kalimat ka-allam yalbatsuu illaa saa'atan minan nahaar menjadi hal atau kata keterangan daripada dhamir maf'ul yang terdapat di dalam lafal yahsyuruhum (mereka saling berkenalan di antara sesama mereka) sebagian di antara mereka berkenalan dengan sebagian yang lain bila mereka dibangkitkan dari alam kubur, kemudian terputuslah perkenalan mereka mengingat ngerinya keadaan yang sedang mereka hadapi. Kalimat ayat ini menjadi jumlah hal yang muqaddarah atau berta'alluq pada zharaf. (Sesungguhnya rugilah orang-orang yang mendustakan pertemuan mereka dengan Allah) yaitu mereka yang tidak mempercayai adanya hari berbangkit (dan mereka tidak mendapat petunjuk).",[["وَيَوْمَ","Dan Hari"],["يَحْشُرُهُمْ","Dia akan mengumpulkan mereka"],["كَأَن","seolah-olah"],["لَّمْ","mereka tidak kekal"],["يَلْبَثُوٓا۟","mereka tidak kekal"],["إِلَّا","kecuali"],["سَاعَةًۭ","sejam"],["مِّنَ","daripada"],["ٱلنَّهَارِ","hari itu"],["يَتَعَارَفُونَ","mereka akan mengenali antara satu sama lain"],["بَيْنَهُمْ ۚ","antara mereka"],["قَدْ","Sungguh"],["خَسِرَ","(akan) kalah"],["ٱلَّذِينَ","orang yang"],["كَذَّبُوا۟","dinafikan"],["بِلِقَآءِ","mesyuarat itu"],["ٱللَّهِ","(dengan) Allah"],["وَمَا","dan bukan"],["كَانُوا۟","mereka adalah"],["مُهْتَدِينَ","mereka yang mendapat petunjuk"]]],"1410":["(Dan jika) lafal immaa ini asalnya adalah terdiri dari in syarthiyah dan maa zaidah yang digabungkan menjadi satu (Kami perlihatkan kepadamu sebagian dari apa yang Kami ancamkan kepada mereka) berupa azab, di dalam hidupmu. Jawab syarath dibuang, lengkapnya adalah fadzaaka, artinya tentulah kamu dapat menyaksikannya (atau jika Kami wafatkan kamu) sebelum mereka tertimpa azab (maka kepada Kamilah mereka kembali, dan Allah menjadi saksi) selalu melihat (atas apa yang mereka kerjakan) berupa kedustaan mereka dan kekafiran yang mereka lakukan itu, kelak Allah akan mengazab mereka dengan siksaan yang amat keras.",[["وَإِمَّا","Dan sama ada"],["نُرِيَنَّكَ","Kami tunjukkan kepada kamu"],["بَعْضَ","beberapa"],["ٱلَّذِى","(daripada) yang"],["نَعِدُهُمْ","Kami berjanji kepada mereka"],["أَوْ","atau"],["نَتَوَفَّيَنَّكَ","Kami menyebabkan kamu mati"],["فَإِلَيْنَا","kemudian kepada Kami"],["مَرْجِعُهُمْ","(adalah) kepulangan mereka"],["ثُمَّ","kemudian"],["ٱللَّهُ","Allah"],["شَهِيدٌ","(adalah) seorang Saksi"],["عَلَىٰ","atas"],["مَا","apa"],["يَفْعَلُونَ","mereka lakukan"]]],"1411":["(Tiap-tiap umat) dari umat-umat semuanya (mempunyai rasul, maka apabila telah datang rasul mereka) kepadanya mereka mendustakannya (diberikanlah keputusan antara mereka dengan adil) secara adil; untuk itu Allah mengazab mereka dan menyelamatkan rasul-Nya bersama orang-orang yang beriman kepadanya (dan mereka sedikit pun tidak dianiaya) seumpamanya mereka diazab tanpa dosa. Demikianlah Kami melakukan hal yang serupa terhadap mereka.",[["وَلِكُلِّ","Dan untuk setiap"],["أُمَّةٍۢ","bangsa"],["رَّسُولٌۭ ۖ","(adalah) seorang Rasul"],["فَإِذَا","Maka apabila"],["جَآءَ","datang"],["رَسُولُهُمْ","Rasul mereka"],["قُضِىَ","ia akan dihakimi"],["بَيْنَهُم","antara mereka"],["بِٱلْقِسْطِ","dalam keadilan"],["وَهُمْ","dan mereka"],["لَا","(akan) tidak"],["يُظْلَمُونَ","dizalimi"]]],"1412":["(Mereka mengatakan, \"Bilakah datangnya ancaman itu) siksaan itu (jika memang kalian orang-orang yang benar?\") dalam hal ini.",[["وَيَقُولُونَ","Dan mereka berkata"],["مَتَىٰ","Apabila"],["هَـٰذَا","(akan) ini"],["ٱلْوَعْدُ","janji (ditepati)"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"1413":["(Katakanlah, \"Aku tidak berkuasa untuk mendatangkan kemudaratan kepada diriku) yang aku dapat menolaknya (dan tidak pula kemanfaatan) yang aku dapat menariknya (melainkan apa yang dikehendaki Allah?\") bila memang Allah telah memastikannya terhadap diriku. Bagaimana aku dapat berkuasa untuk menurunkan azab kepada kalian. (Tiap-tiap umat mempunyai ajal) masa yang telah dimaklumi bagi kebinasaan mereka. (Maka apabila telah datang ajal mereka, maka mereka tidak dapat menangguhkannya) tidak dapat menangguhkan kedatangan azab itu (barang sedikit pun dan tidak pula mendahulukannya) menyegerakan datangnya azab itu.",[["قُل","Katakanlah"],["لَّآ","Tidak"],["أَمْلِكُ","Aku ada kuasa"],["لِنَفْسِى","untuk diri aku sendiri"],["ضَرًّۭا","(untuk) sebarang bahaya"],["وَلَا","dan bukan"],["نَفْعًا","(untuk) sebarang keuntungan"],["إِلَّا","kecuali"],["مَا","apa"],["شَآءَ","Allah berkehendak"],["ٱللَّهُ ۗ","Allah berkehendak"],["لِكُلِّ","Untuk setiap"],["أُمَّةٍ","bangsa"],["أَجَلٌ ۚ","(adalah) istilah"],["إِذَا","Apabila"],["جَآءَ","datang"],["أَجَلُهُمْ","istilah mereka"],["فَلَا","maka tidak"],["يَسْتَـْٔخِرُونَ","mereka kekal di belakang"],["سَاعَةًۭ ۖ","sejam"],["وَلَا","dan bukan"],["يَسْتَقْدِمُونَ","mereka boleh mendahuluinya"]]],"1414":["(Katakanlah, \"Terangkanlah) ceritakanlah kepadaku (jika datang kepada kalian siksaan-Nya) yakni azab Allah (di waktu malam hari) (atau di siang hari, apakah) benar (minta disegerakan juga datangnya azab itu) siksaan itu (oleh orang-orang yang berdosa?\") yakni orang-orang musyrik. Di dalam ayat ini terkandung ungkapan meletakkan isim zhahir pada tempat isim dhamir. Jumlah istifham dalam ayat ini merupakan jawab syarat; perihalnya sama dengan ucapan anda, \"idzaa ataituka madzaa tu'thiiniy?\" (Jika aku datang berkunjung kepadamu, apakah yang akan engkau berikan kepadaku). Adapun pengertian yang dimaksud daripada makna ayat ini ialah menggambarkan kengerian; atau dengan kata lain, alangkah ngerinya apa yang mereka minta supaya disegerakan.",[["قُلْ","Katakanlah"],["أَرَءَيْتُمْ","Adakah kamu melihat"],["إِنْ","jika"],["أَتَىٰكُمْ","datang kepada kamu"],["عَذَابُهُۥ","hukumannya"],["بَيَـٰتًا","(menjelang) malam"],["أَوْ","atau"],["نَهَارًۭا","(mengikut) hari"],["مَّاذَا","apa (bahagian)"],["يَسْتَعْجِلُ","daripadanya akan (ingin) disegerakan"],["مِنْهُ","daripadanya akan (ingin) disegerakan"],["ٱلْمُجْرِمُونَ","penjenayah"]]],"1415":["(Kemudian apakah setelah terjadinya azab itu) setelah siksaan menimpa kalian (kemudian itu kalian baru mempercayainya?) percaya kepada Allah atau percaya kepada azab-Nya sewaktu azab itu diturunkan. Hamzah di sini mengandung makna mengingkari adanya penangguhan azab. Kala itu iman kalian tidak dapat diterima, kemudian akan dikatakan kepada kalian (Apakah baru sekarang) kalian mempercayainya? (padahal sebelumnya kalian selalu meminta supaya disegerakan) kalimat ayat ini mengandung arti cemoohan.",[["أَثُمَّ","Adakah (ia) kemudian"],["إِذَا","apabila"],["مَا","apabila"],["وَقَعَ","(ia telah) berlaku"],["ءَامَنتُم","kamu (akan) beriman"],["بِهِۦٓ ۚ","di dalamnya"],["ءَآلْـَٔـٰنَ","Sekarang"],["وَقَدْ","Dan sungguh"],["كُنتُم","kamu dahulu"],["بِهِۦ","berusaha untuk menyegerakannya"],["تَسْتَعْجِلُونَ","berusaha untuk menyegerakannya"]]],"1416":["(Kemudian dikatakan kepada orang-orang yang lalim atau musyrik itu, \"Rasakanlah oleh kalian siksaan yang kekal) artinya siksaan yang kalian kekal di dalamnya (tidaklah) (kalian diberi balasan melainkan) pembalasan (dengan apa yang telah kalian kerjakan\").",[["ثُمَّ","Kemudian"],["قِيلَ","ia akan dikatakan"],["لِلَّذِينَ","kepada mereka yang"],["ظَلَمُوا۟","dizalimi"],["ذُوقُوا۟","rasa"],["عَذَابَ","hukuman"],["ٱلْخُلْدِ","yang kekal"],["هَلْ","Adakah kamu (diberi) balasan"],["تُجْزَوْنَ","Adakah kamu (diberi) balasan"],["إِلَّا","kecuali"],["بِمَا","bagi apa"],["كُنتُمْ","kamu pernah (untuk)"],["تَكْسِبُونَ","peroleh"]]],"1417":["(Dan mereka menanyakan kepadamu) meminta penjelasan darimu (\"Benarkah hal itu?\") artinya apa yang telah engkau ancamkan kepada kami berupa siksaan dan dibangkitkan dari kubur itu? (Katakanlah, \"Ya,) benar (demi Rabbku, sesungguhnya azab itu adalah benar dan kalian sekali-kali tidak dapat luput.\") tidak dapat selamat daripadanya.",[["۞ وَيَسْتَنۢبِـُٔونَكَ","Dan mereka meminta kamu untuk memaklumkan"],["أَحَقٌّ","Adakah ia benar"],["هُوَ ۖ","Adakah ia benar"],["قُلْ","Katakanlah"],["إِى","ya"],["وَرَبِّىٓ","oleh Tuhanku"],["إِنَّهُۥ","Sesungguhnya, ia"],["لَحَقٌّۭ ۖ","(adalah) sesungguhnya kebenaran"],["وَمَآ","dan bukan"],["أَنتُم","kamu"],["بِمُعْجِزِينَ","(boleh) melarikan diri (ia)"]]],"1418":["(Dan kalau setiap diri yang lalim itu) yang kafir itu (mempunyai segala apa yang ada di bumi ini) kekayaan yang terdapat di bumi ini (tentu dia menebus dirinya dengan itu) demi menyelamatkan diri dari azab di hari kiamat (dan mereka menyembunyikan penyesalannya) karena tidak mau beriman (ketika mereka telah menyaksikan azab itu) para pemimpin orang-orang musyrik itu dengan sengaja menyembunyikan rasa penyesalannya dari mata orang-orang lemah mereka yang telah mereka sesatkan, karena mereka takut mendapatkan celaan. (Dan telah diberikan keputusan di antara mereka) yakni di antara makhluk (dengan adil) secara adil (sedangkan mereka tidak dianiaya) sedikit pun.",[["وَلَوْ","Dan jika"],["أَنَّ","bahawa"],["لِكُلِّ","untuk setiap"],["نَفْسٍۢ","jiwa"],["ظَلَمَتْ","(yang) dizalimi"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["لَٱفْتَدَتْ","ia (akan) berusaha untuk menebus"],["بِهِۦ ۗ","dengannya"],["وَأَسَرُّوا۟","dan mereka (akan) mengaku"],["ٱلنَّدَامَةَ","penyesalan itu"],["لَمَّا","apabila"],["رَأَوُا۟","mereka lihat"],["ٱلْعَذَابَ ۖ","azab"],["وَقُضِىَ","Tetapi akan dihakimi"],["بَيْنَهُم","antara mereka"],["بِٱلْقِسْطِ ۚ","dalam keadilan"],["وَهُمْ","dan mereka"],["لَا","(akan) tidak"],["يُظْلَمُونَ","(menjadi) dizalimi"]]],"1419":["(Ingatlah, sesungguhnya kepunyaan Allah apa yang ada di langit dan di bumi. Ingatlah sesungguhnya janji Allah itu) mengenai hari berbangkit dan hari pembalasan (benar) pasti (tetapi kebanyakan mereka) manusia (tidak mengetahui) hal itu.",[["أَلَآ","Tidak syak lagi"],["إِنَّ","sesungguhnya"],["لِلَّهِ","kerana Allah"],["مَا","(adalah) apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۗ","dan bumi"],["أَلَآ","Tidak syak lagi"],["إِنَّ","sesungguhnya"],["وَعْدَ","(janji) Allah"],["ٱللَّهِ","(janji) Allah"],["حَقٌّۭ","(adalah) benar"],["وَلَـٰكِنَّ","Tetapi"],["أَكْثَرَهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"1420":["(Dialah yang menghidupkan dan mematikan dan hanya kepada-Nyalah kalian dikembalikan) di hari kemudian, kemudian Dia membalas kalian atas amal perbuatan kalian.",[["هُوَ","Dia"],["يُحْىِۦ","memberi kehidupan"],["وَيُمِيتُ","dan menyebabkan kematian"],["وَإِلَيْهِ","dan kepada-Nya"],["تُرْجَعُونَ","kamu akan dikembalikan"]]],"1421":["(Hai manusia) yakni penduduk Mekah (sesungguhnya telah datang kepada kalian pelajaran dari Rabb kalian) berupa Alkitab yang di dalamnya dijelaskan hal-hal yang bermanfaat dan hal-hal yang mudarat bagi diri kalian, yaitu berupa kitab Alquran (dan penyembuh) penawar (bagi penyakit-penyakit yang ada di dalam dada) yakni penyakit akidah yang rusak dan keragu-raguan (dan petunjuk) dari kesesatan (serta rahmat bagi orang-orang yang beriman) kepadanya.",[["يَـٰٓأَيُّهَا","Wahai umat manusia"],["ٱلنَّاسُ","Wahai umat manusia"],["قَدْ","Sesungguhnya"],["جَآءَتْكُم","telah datang kepada kamu"],["مَّوْعِظَةٌۭ","suatu arahan"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["وَشِفَآءٌۭ","dan kesembuhan"],["لِّمَا","bagi apa"],["فِى","(berada) dalam"],["ٱلصُّدُورِ","buah dada kamu"],["وَهُدًۭى","dan bimbingan"],["وَرَحْمَةٌۭ","dan belas kasihan"],["لِّلْمُؤْمِنِينَ","untuk orang yang beriman"]]],"1422":["(Katakanlah, \"Dengan karunia Allah) yaitu agama Islam (dan rahmat-Nya) yaitu Alquran (maka dengan hal itu) dengan karunia dan rahmat tersebut (hendaklah mereka bergembira. Karunia Allah dan rahmat-Nya itu adalah lebih baik daripada apa yang mereka kumpulkan.\") yaitu berupa duniawi. Lafal yajma'uuna dapat dibaca tajma'uuna.",[["قُلْ","Katakanlah"],["بِفَضْلِ","Dalam Bounty"],["ٱللَّهِ","(milik) Allah"],["وَبِرَحْمَتِهِۦ","dan dalam RahmatNya"],["فَبِذَٰلِكَ","jadi dalam itu"],["فَلْيَفْرَحُوا۟","biarlah mereka bergembira"],["هُوَ","Ia"],["خَيْرٌۭ","(lebih) baik"],["مِّمَّا","daripada apa"],["يَجْمَعُونَ","mereka terkumpul"]]],"1423":["(Katakanlah, \"Terangkanlah kepadaku) ceritakanlah kepadaku (tentang apa yang telah diturunkan oleh Allah) tentang apa yang telah diciptakan oleh-Nya (bagi kalian berupa rezeki, lalu kalian jadikan sebagiannya haram dan sebagian yang lainnya halal.\") seperti ternak bahirah, ternak saibah dan bangkai. (Katakanlah, \"Apakah Allah telah memberikan izin kepada kalian) tentang ini, yaitu tentang penghalalan dan pengharaman ini; tentu saja tidak (atau) bahkan (kalian mengada-adakan saja terhadap Allah?\") kalian telah berdusta dengan mengaitkan hal tersebut dari Allah.",[["قُلْ","Katakanlah"],["أَرَءَيْتُم","Pernahkah kamu melihat"],["مَّآ","apa"],["أَنزَلَ","(telah) diturunkan"],["ٱللَّهُ","(oleh) Allah"],["لَكُم","bagi kamu"],["مِّن","daripada"],["رِّزْقٍۢ","(peruntukan)."],["فَجَعَلْتُم","dan kamu telah membuat"],["مِّنْهُ","daripadanya"],["حَرَامًۭا","menyalahi undang-undang"],["وَحَلَـٰلًۭا","dan halal"],["قُلْ","Katakanlah"],["ءَآللَّهُ","Mempunyai Allah"],["أَذِنَ","dibenarkan"],["لَكُمْ ۖ","[kepada] kamu"],["أَمْ","atau"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["تَفْتَرُونَ","kamu mengada-adakan (bohong)"]]],"1424":["(Apakah dugaan orang-orang yang mengada-adakan kebohongan terhadap Allah) maksudnya apakah dugaan mereka terhadap-Nya (pada hari kiamat) apakah mereka menduga bahwasanya Allah tidak akan menghukum mereka? Tentu saja tidak demikian. (Sesungguhnya Allah benar-benar mempunyai karunia yang dilimpahkan kepada manusia) yaitu dengan menangguhkan mereka dan selalu memberikan nikmat kepada mereka (tetapi kebanyakan mereka tidak bersyukur).",[["وَمَا","Dan apa"],["ظَنُّ","(akan menjadi) andaian"],["ٱلَّذِينَ","orang yang"],["يَفْتَرُونَ","mencipta"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["ٱلْكَذِبَ","pembohongan itu"],["يَوْمَ","(pada) hari itu"],["ٱلْقِيَـٰمَةِ ۗ","(dari) Penghakiman"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَذُو","Sesungguhnya penuh dengan karunia"],["فَضْلٍ","Sesungguhnya penuh dengan karunia"],["عَلَى","kepada"],["ٱلنَّاسِ","umat manusia"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَهُمْ","kebanyakan mereka"],["لَا","(adalah) tidak"],["يَشْكُرُونَ","bersyukur"]]],"1425":["(Kamu tidak berada) hai Muhammad! (dalam suatu keadaan) dalam suatu perkara (dan tidak membaca suatu ayat) artinya mengenai perkara tersebut atau membaca dari Allah (dari Alquran) yang diturunkan oleh-Nya kepadamu (dan kamu tidak mengerjakan) khithab ayat ini ditujukan kepada Nabi Muhammad saw. dan umatnya (suatu pekerjaan, melainkan Kami menjadi saksi atas kalian) meneliti (di waktu kalian melakukan) mengerjakan (perbuatan itu) amal perbuatan itu. (Tidak luput) tidak samar (dari pengetahuan Rabbmu hal yang sebesar) seberat (zarrah) semut yang paling kecil (di bumi atau pun di langit. Tidak ada yang lebih kecil dan tidak pula yang lebih besar dari itu melainkan semua tercatat dalam kitab yang nyata) yang jelas, yaitu Lohmahfuz.",[["وَمَا","Dan tidak"],["تَكُونُ","kamu"],["فِى","[dalam]"],["شَأْنٍۢ","apa jua keadaan"],["وَمَا","dan bukan"],["تَتْلُوا۟","kamu mengaji"],["مِنْهُ","daripadanya"],["مِن","daripada"],["قُرْءَانٍۢ","(al-Quran)."],["وَلَا","dan bukan"],["تَعْمَلُونَ","kamu lakukan"],["مِنْ","sebarang"],["عَمَلٍ","perbuatan"],["إِلَّا","kecuali"],["كُنَّا","Kami"],["عَلَيْكُمْ","atas kamu"],["شُهُودًا","saksi"],["إِذْ","apabila"],["تُفِيضُونَ","kamu dah bertunang"],["فِيهِ ۚ","di dalamnya"],["وَمَا","Dan tidak"],["يَعْزُبُ","melarikan diri"],["عَن","daripada"],["رَّبِّكَ","Tuhanmu"],["مِن","daripada"],["مِّثْقَالِ","(yang) berat"],["ذَرَّةٍۢ","(dari) atom"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَلَا","dan bukan"],["فِى","dalam"],["ٱلسَّمَآءِ","langit"],["وَلَآ","dan bukan"],["أَصْغَرَ","lebih kecil"],["مِن","daripada"],["ذَٰلِكَ","bahawa"],["وَلَآ","dan bukan"],["أَكْبَرَ","lebih besar"],["إِلَّا","tetapi"],["فِى","(berada) dalam"],["كِتَـٰبٍۢ","sebuah Rekod"],["مُّبِينٍ","yang nyata"]]],"1426":["(Ingatlah, sesungguhnya wali-wali Allah itu tidak ada kekhawatiran terhadap mereka dan tidak pula mereka bersedih hati) di akhirat nanti.",[["أَلَآ","Tidak syak lagi"],["إِنَّ","Sesungguhnya"],["أَوْلِيَآءَ","(the) kawan-kawan"],["ٱللَّهِ","(milik) Allah"],["لَا","(akan ada) tidak"],["خَوْفٌ","bertakwa"],["عَلَيْهِمْ","selepas itu"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يَحْزَنُونَ","akan bersedih"]]],"1427":["(Yaitu orang-orang yang beriman dan mereka selalu bertakwa) kepada Allah dengan menjalankan perintah-Nya dan menjauhi larangan-Nya.",[["ٱلَّذِينَ","Orang yang"],["ءَامَنُوا۟","beriman"],["وَكَانُوا۟","dan adalah"],["يَتَّقُونَ","sedar (kepada Allah)"]]],"1428":["(Bagi mereka berita gembira di dalam kehidupan dunia) makna ayat ini ditafsirkan oleh hadis sahih yang diketengahkan oleh Imam Hakim, bahwa berita gembira ini berupa mimpi yang baik yang dilihat oleh seorang wali Allah, atau mimpi yang baik itu diperlihatkan kepadanya (dan dalam kehidupan di akhirat) mereka mendapatkan surga dan pahala. (Tidak ada perubahan bagi kalimat-kalimat Allah) janji-janji Allah tidak akan diingkari. (Yang demikian itu) hal yang telah disebutkan itu (adalah kemenangan yang besar).",[["لَهُمُ","Untuk mereka"],["ٱلْبُشْرَىٰ","(ialah) berita gembira"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا","dunia"],["وَفِى","dan dalam"],["ٱلْـَٔاخِرَةِ ۚ","akhirat"],["لَا","Tidak"],["تَبْدِيلَ","berubah"],["لِكَلِمَـٰتِ","(ada) dalam Firman"],["ٱللَّهِ ۚ","(milik) Allah"],["ذَٰلِكَ","Itu"],["هُوَ","ialah"],["ٱلْفَوْزُ","kejayaan itu"],["ٱلْعَظِيمُ","yang hebat"]]],"1429":["(Janganlah kamu sedih oleh perkataan mereka) terhadap dirimu, seperti perkataan mereka, \"Engkau adalah bukan utusan Allah,\" dan lain sebagainya. (Sesungguhnya) huruf inna di sini merupakan pertanda isti'naf atau kalimat baru (kekuatan itu) kekuatan (adalah kepunyaan Allah seluruhnya. Dialah Yang Maha Mendengar) semua perkataan (lagi Maha Mengetahui) semua perbuatan, maka karenanya Dia membalas perbuatan mereka dan menolong kamu.",[["وَلَا","Dan (jangan)"],["يَحْزُنكَ","menyedihkan kamu"],["قَوْلُهُمْ ۘ","ucapan mereka"],["إِنَّ","Sesungguhnya"],["ٱلْعِزَّةَ","penghormatan"],["لِلَّهِ","(kepunyaan) Allah"],["جَمِيعًا ۚ","semua"],["هُوَ","Dia"],["ٱلسَّمِيعُ","(ialah) Yang Maha Mendengar"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"1430":["(Ingatlah, sesungguhnya kepunyaan Allah semua yang ada di langit dan semua yang ada di bumi) sebagai hamba-Nya, milik-Nya dan sebagai makhluk-Nya. (Dan tidaklah mengikuti orang-orang yang menyeru) yang menyembah (selain daripada Allah) selain Allah, yaitu berupa berhala-berhala (berupa sekutu-sekutu) bagi-Nya secara nyata, Maha Suci Allah dari sekutu-sekutu (tidaklah) tiada lain (mereka mengikuti) dalam hal tersebut (melainkan hanya dugaan saja) mereka menduga bahwa berhala-berhala sesembahan mereka itu adalah tuhan yang dapat memberikan syafaat terhadap diri mereka (dan tidaklah) tiadalah (keadaan mereka melainkan hanya berdusta belaka) yakni berbuat dusta dalam hal tersebut.",[["أَلَآ","Tidak syak lagi"],["إِنَّ","Sesungguhnya"],["لِلَّهِ","kepada Allah (milik)"],["مَن","sesiapa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَن","dan sesiapa"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۗ","bumi"],["وَمَا","Dan tidak"],["يَتَّبِعُ","ikut"],["ٱلَّذِينَ","orang yang"],["يَدْعُونَ","menyeru"],["مِن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["شُرَكَآءَ ۚ","rakan kongsi"],["إِن","Tidak"],["يَتَّبِعُونَ","mereka ikut"],["إِلَّا","tetapi"],["ٱلظَّنَّ","andaian itu"],["وَإِنْ","dan bukan"],["هُمْ","mereka"],["إِلَّا","tetapi"],["يَخْرُصُونَ","meneka"]]],"1431":["(Dialah yang menjadikan malam hari bagi kalian supaya kalian beristirahat padanya dan menjadikan siang terang) diisnadkannya lafal al-ibshaar yang artinya melihat kepada lafal an-nahaar yang artinya siang hari mengandung pengertian majaz, karena seseorang dapat melihat pada siang hari. (Sesungguhnya pada yang demikian itu terdapat tanda-tanda) bukti-bukti yang menunjukkan keesaan-Nya (bagi orang-orang yang mendengar) dengan pendengaran yang dibarengi dengan perasaan mengambil pelajaran dan nasihat dari apa yang didengarnya.",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["جَعَلَ","dibuat"],["لَكُمُ","bagi kamu"],["ٱلَّيْلَ","malam"],["لِتَسْكُنُوا۟","supaya kamu boleh berehat"],["فِيهِ","di dalamnya"],["وَٱلنَّهَارَ","dan hari"],["مُبْصِرًا ۚ","memberi keterlihatan"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يَسْمَعُونَ","(yang) mendengar"]]],"1432":["(Mereka berkata) yang dimaksud adalah orang-orang Yahudi, orang-orang Nasrani dan orang-orang yang menduga bahwa para malaikat itu adalah anak-anak perempuan Allah (\"Allah mempunyai anak,\") maka Allah berfirman kepada mereka (Maha Suci Allah) memahasucikan Allah dari tuduhan mempunyai anak (Dialah Yang Maha Kaya) tidak membutuhkan kepada seseorang pun, dan sesungguhnya orang-orang yang meminta punya anak itu adalah orang yang membutuhkannya. (Kepunyaan-Nya apa yang ada di langit dan apa yang ada di bumi) sebagai milik-Nya, makhluk-Nya dan hamba-Nya (tidak) tiada (bagi kalian suatu hujah pun) bukti (tentang ini) seperti apa yang telah kalian katakan itu. (Pantaskah kalian mengatakan terhadap Allah apa yang kalian tidak ketahui?) kata tanya di sini mengandung pengertian cemoohan.",[["قَالُوا۟","Mereka berkata"],["ٱتَّخَذَ","Allah telah mengambil"],["ٱللَّهُ","Allah telah mengambil"],["وَلَدًۭا ۗ","seorang anak lelaki"],["سُبْحَـٰنَهُۥ ۖ","Maha Suci Dia"],["هُوَ","Dia"],["ٱلْغَنِىُّ ۖ","(ialah) Yang Berdikari"],["لَهُۥ","KepunyaanNya (milik)"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۚ","bumi"],["إِنْ","Tidak"],["عِندَكُم","kamu ada"],["مِّن","sebarang"],["سُلْطَـٰنٍۭ","pihak berkuasa"],["بِهَـٰذَآ ۚ","untuk ini"],["أَتَقُولُونَ","Adakah kamu berkata"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["مَا","apa"],["لَا","tidak"],["تَعْلَمُونَ","kamu tahu"]]],"1433":["(Katakanlah, \"Sesungguhnya orang-orang yang mengada-adakan kebohongan terhadap Allah) dengan menisbatkan mempunyai anak kepada-Nya (tidak beruntung.\") tidak bahagia.",[["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يَفْتَرُونَ","mencipta"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["ٱلْكَذِبَ","pembohongan itu"],["لَا","mereka tidak akan berjaya"],["يُفْلِحُونَ","mereka tidak akan berjaya"]]],"1434":["Bagi mereka (kesenangan) yang sedikit atau sementara (di dunia) yang mereka bersenang-senang dengannya selama hidup mereka di dunia (kemudian kepada Kamilah mereka kembali) dengan dimatikannya mereka (kemudian Kami rasakan kepada mereka siksa yang berat) sesudah mati (disebabkan kekafiran mereka).",[["مَتَـٰعٌۭ","Satu kenikmatan"],["فِى","dalam"],["ٱلدُّنْيَا","dunia"],["ثُمَّ","kemudian"],["إِلَيْنَا","kepada Kami"],["مَرْجِعُهُمْ","(adalah) kepulangan mereka"],["ثُمَّ","kemudian"],["نُذِيقُهُمُ","Kami akan membuat mereka rasa"],["ٱلْعَذَابَ","azab"],["ٱلشَّدِيدَ","yang teruk"],["بِمَا","kerana"],["كَانُوا۟","mereka dahulu"],["يَكْفُرُونَ","kufur"]]],"1435":["(Dan bacakanlah) hai Muhammad (kepada mereka) orang-orang kafir Mekah (berita penting) cerita penting (tentang Nuh) yaitu (di waktu dia berkata kepada kaumnya, \"Hai kaumku, jika terasa berat) keberatan (bagi kalian tinggal bersamaku) aku berdiam di antara kalian (dan peringatanku) nasihatku terhadap kalian (dengan ayat-ayat Allah, maka kepada Allahlah aku bertawakal, karena itu bulatkanlah keputusan kalian) bulatkanlah tekad kalian tentang perkara yang akan kalian lakukan terhadap diriku (bersama dengan sekutu-sekutu kalian) wawu di sini bermakna ma'a. (Kemudian janganlah keputusan kalian itu dirahasiakan) disembunyikan, akan tetapi tampakkanlah dan berterus-teranglah kepadaku tentang hal itu (lalu lakukanlah terhadap diriku) laksanakanlah apa yang telah kalian kehendaki itu (dan janganlah kalian memberi tangguh kepadaku) menangguh-nangguhkannya, karena sesungguhnya aku tidak akan mempedulikan kalian lagi.",[["۞ وَٱتْلُ","Dan mengaji"],["عَلَيْهِمْ","kepada mereka"],["نَبَأَ","berita itu"],["نُوحٍ","(daripada) Nuh"],["إِذْ","apabila"],["قَالَ","dia berkata"],["لِقَوْمِهِۦ","kepada umatnya"],["يَـٰقَوْمِ","Wahai kaumku"],["إِن","Jika"],["كَانَ","ialah"],["كَبُرَ","keras"],["عَلَيْكُم","pada kamu"],["مَّقَامِى","penginapan aku"],["وَتَذْكِيرِى","dan peringatan aku"],["بِـَٔايَـٰتِ","ayat-ayat Allah"],["ٱللَّهِ","ayat-ayat Allah"],["فَعَلَى","kemudian pada"],["ٱللَّهِ","Allah"],["تَوَكَّلْتُ","Aku meletakkan kepercayaan aku"],["فَأَجْمِعُوٓا۟","Jadi kamu semua berazam"],["أَمْرَكُمْ","rancangan kamu"],["وَشُرَكَآءَكُمْ","dan rakan kongsi kamu"],["ثُمَّ","Kemudian"],["لَا","jangan jadi"],["يَكُنْ","jangan jadi"],["أَمْرُكُمْ","(dalam) rancangan kamu"],["عَلَيْكُمْ","bagi kamu"],["غُمَّةًۭ","sebarang keraguan"],["ثُمَّ","Kemudian"],["ٱقْضُوٓا۟","melaksanakan (melaksanakannya)"],["إِلَىَّ","atas aku"],["وَلَا","dan jangan"],["تُنظِرُونِ","beri aku tangguh"]]],"1436":["(Jika kalian berpaling) dari peringatanku (aku tidak meminta upah sedikit pun daripada kalian) sebagai imbalan dan upah atas jerih payahku itu, maka berpalinglah kalian (tiada lain) tidak lain (upahku) pahalaku (hanyalah dari Allah belaka dan aku disuruh supaya aku termasuk golongan orang-orang yang berserah diri) kepada-Nya.",[["فَإِن","Tetapi jika"],["تَوَلَّيْتُمْ","kamu berpaling"],["فَمَا","maka tidak"],["سَأَلْتُكُم","Aku telah bertanya kepada kamu"],["مِّنْ","sebarang"],["أَجْرٍ ۖ","pahala"],["إِنْ","Tidak"],["أَجْرِىَ","(ialah) pahala aku"],["إِلَّا","tetapi"],["عَلَى","pada"],["ٱللَّهِ ۖ","Allah"],["وَأُمِرْتُ","dan aku telah diperintahkan"],["أَنْ","bahawa"],["أَكُونَ","aku jadi"],["مِنَ","daripada"],["ٱلْمُسْلِمِينَ","kaum muslimin"]]],"1437":["(Lalu mereka mendustakan Nuh, maka Kami selamatkan dia dan orang-orang yang bersamanya di dalam bahtera) perahu (dan Kami jadikan mereka itu) orang-orang yang bersama dengan Nabi Nuh (pemegang kekuasaan) di muka bumi (dan Kami tenggelamkan orang-orang yang mendustakan ayat-ayat Kami) dengan banjir besar (Maka perhatikanlah bagaimana kesudahan orang-orang yang diberi peringatan itu) yaitu dengan binasanya mereka; maka demikian pula Kami akan berlaku sama terhadap orang yang mendustakan rasul.",[["فَكَذَّبُوهُ","Tetapi mereka menafikannya"],["فَنَجَّيْنَـٰهُ","maka Kami selamatkan dia"],["وَمَن","dan (mereka) yang"],["مَّعَهُۥ","(ada) bersamanya"],["فِى","dalam"],["ٱلْفُلْكِ","kapal itu"],["وَجَعَلْنَـٰهُمْ","dan Kami jadikan mereka"],["خَلَـٰٓئِفَ","pengganti"],["وَأَغْرَقْنَا","dan Kami tenggelam"],["ٱلَّذِينَ","orang yang"],["كَذَّبُوا۟","dinafikan"],["بِـَٔايَـٰتِنَا ۖ","Tanda-Tanda Kami"],["فَٱنظُرْ","Kemudian lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلْمُنذَرِينَ","(dari) orang-orang yang diberi peringatan"]]],"1438":["(Kemudian sesudahnya Kami utus) yakni sesudah Nabi Nuh (beberapa rasul kepada kaum mereka) seperti Nabi Ibrahim, Nabi Hud dan Nabi Saleh (maka rasul-rasul itu datang kepada mereka dengan membawa keterangan-keterangan yang nyata), yakni mukjizat-mukjizat (tetapi mereka tidak hendak beriman karena mereka dahulu telah biasa mendustakannya) sebelum rasul-rasul diutus kepada mereka. (Demikianlah Kami mengunci mati) menutup rapat-rapat (hati orang-orang yang melampaui batas) sehingga hati mereka tidak mau menerima iman, seperti Kami mengunci mati hati mereka yang melampaui batas.",[["ثُمَّ","Kemudian"],["بَعَثْنَا","Kami utus"],["مِنۢ","selepas dia"],["بَعْدِهِۦ","selepas dia"],["رُسُلًا","Utusan"],["إِلَىٰ","kepada"],["قَوْمِهِمْ","rakyat mereka"],["فَجَآءُوهُم","dan mereka datang kepada mereka"],["بِٱلْبَيِّنَـٰتِ","dengan bukti yang jelas"],["فَمَا","Tetapi tidak"],["كَانُوا۟","mereka adalah"],["لِيُؤْمِنُوا۟","untuk beriman"],["بِمَا","apa"],["كَذَّبُوا۟","mereka telah menafikan"],["بِهِۦ","[ia]"],["مِن","sebelum"],["قَبْلُ ۚ","sebelum"],["كَذَٰلِكَ","Demikianlah"],["نَطْبَعُ","Kami mengelak"],["عَلَىٰ","[pada]"],["قُلُوبِ","hati"],["ٱلْمُعْتَدِينَ","(dari) orang-orang yang melampaui batas"]]],"1439":["(Kemudian sesudah rasul-rasul itu, Kami utus Musa dan Harun kepada Firaun dan pemuka-pemuka kaumnya) kaumnya Firaun (dengan membawa ayat-ayat Kami) yang berjumlah sembilan buah ayat (maka mereka menyombongkan diri) tidak mau beriman kepadanya (dan mereka adalah orang-orang yang berdosa).",[["ثُمَّ","Kemudian"],["بَعَثْنَا","Kami utus"],["مِنۢ","selepas mereka"],["بَعْدِهِم","selepas mereka"],["مُّوسَىٰ","Musa"],["وَهَـٰرُونَ","dan Harun"],["إِلَىٰ","kepada"],["فِرْعَوْنَ","Firaun"],["وَمَلَإِي۟هِۦ","dan ketua-ketuanya"],["بِـَٔايَـٰتِنَا","dengan Tanda-tanda Kami"],["فَٱسْتَكْبَرُوا۟","tetapi mereka sombong"],["وَكَانُوا۟","dan telah"],["قَوْمًۭا","suatu kaum"],["مُّجْرِمِينَ","penjenayah"]]],"1440":["(Dan tatkala telah datang kepada mereka kebenaran dari sisi Kami, mereka berkata, \"Sesungguhnya ini adalah sihir yang nyata.\") jelas dan gamblang.",[["فَلَمَّا","Maka apabila"],["جَآءَهُمُ","datang kepada mereka"],["ٱلْحَقُّ","kebenaran"],["مِنْ","daripada Kami"],["عِندِنَا","daripada Kami"],["قَالُوٓا۟","mereka berkata"],["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["لَسِحْرٌۭ","(adalah) sesungguhnya sihir"],["مُّبِينٌۭ","yang nyata"]]],"1441":["(Musa berkata, \"Apakah kalian mengatakan terhadap kebenaran waktu ia datang kepada kalian) sesungguhnya adalah sihir (sihirkah ini?) padahal sungguh telah mendapat kemenangan orang yang mendatangkannya dan kalahlah sihir yang dilakukan oleh para ahli tenung (dan sungguh ahli sihir itu tidaklah mendapat kemenangan.\") kedua kata tanya yang terdapat di dalam ayat ini mengandung makna ingkar.",[["قَالَ","Musa berkata"],["مُوسَىٰٓ","Musa berkata"],["أَتَقُولُونَ","Adakah kamu berkata"],["لِلْحَقِّ","tentang kebenaran"],["لَمَّا","apabila"],["جَآءَكُمْ ۖ","ia telah datang kepada kamu"],["أَسِحْرٌ","Adakah ini sihir"],["هَـٰذَا","Adakah ini sihir"],["وَلَا","Tetapi (akan) tidak"],["يُفْلِحُ","berjaya"],["ٱلسَّـٰحِرُونَ","ahli sihir"]]],"1442":["(Mereka berkata, \"Apakah kamu datang kepada kami untuk memalingkan kami) untuk membuat kami murtad (dari apa yang kami dapati nenek moyang kami mengerjakannya dan supaya kamu berdua mempunyai kekuasaan) kerajaan (di muka bumi?) yang dimaksud adalah negeri Mesir (Kami tidak akan mempercayai kamu berdua.\") tidak mau beriman.",[["قَالُوٓا۟","Mereka berkata"],["أَجِئْتَنَا","Adakah kamu datang kepada kami"],["لِتَلْفِتَنَا","untuk memalingkan kita"],["عَمَّا","daripada itu"],["وَجَدْنَا","kami jumpa"],["عَلَيْهِ","di atasnya"],["ءَابَآءَنَا","nenek moyang kita"],["وَتَكُونَ","dan kamu berdua (mungkin) mempunyai"],["لَكُمَا","dan kamu berdua (mungkin) mempunyai"],["ٱلْكِبْرِيَآءُ","kehebatan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَمَا","Dan kami tidak"],["نَحْنُ","Dan kami tidak"],["لَكُمَا","(dalam) kamu berdua"],["بِمُؤْمِنِينَ","orang yang beriman"]]],"1443":["(Firaun berkata, \"Datangkanlah kepadaku semua ahli-ahli sihir yang pandai.\") yang mahir di dalam ilmu sihir.",[["وَقَالَ","Dan Firaun berkata"],["فِرْعَوْنُ","Dan Firaun berkata"],["ٱئْتُونِى","Bawa kepada aku"],["بِكُلِّ","setiap"],["سَـٰحِرٍ","ahli silap mata"],["عَلِيمٍۢ","dipelajari"]]],"1444":["(Maka tatkala ahli-ahli sihir itu datang, Musa berkata kepada mereka,) sesudah mereka mengatakan kepadanya, \"Kamukah yang akan melemparkan terlebih dahulu ataukah kami yang akan melemparkan?\" (Al-A`raf 115) (\"Lemparkanlah apa yang hendak kalian lemparkan.\")",[["فَلَمَّا","Maka apabila"],["جَآءَ","datang"],["ٱلسَّحَرَةُ","ahli sihir"],["قَالَ","berkata"],["لَهُم","kepada mereka"],["مُّوسَىٰٓ","Musa"],["أَلْقُوا۟","Baling"],["مَآ","apa sahaja"],["أَنتُم","kamu"],["مُّلْقُونَ","(ingin) melempar"]]],"1445":["(Maka setelah mereka lemparkan) tali-tali dan tongkat-tongkat mereka (Musa berkata, \"Apa) huruf maa di sini bermakna istifham sekaligus menjadi mubtada sedangkan khabarnya ialah berikutnya (yang kalian datangkan itu itulah sihir) lafal as-sihr menjadi badal. Sedangkan menurut qiraat yang lain dengan memakai hamzah, berarti keduanya menjadi khabar, dan maa bukannya istifhamiyah melainkan maushul dan sekaligus menjadi mubtada. (Sesungguhnya Allah akan menampakkan ketidakbenarannya.\") Allah akan melenyapkannya (Sesungguhnya Allah tidak akan membiarkan terus berlangsungnya pekerjaan orang-orang yang membuat kerusakan).",[["فَلَمَّآ","Kemudian apabila"],["أَلْقَوْا۟","mereka (telah) melemparkan"],["قَالَ","Musa berkata"],["مُوسَىٰ","Musa berkata"],["مَا","Apa"],["جِئْتُم","kamu telah membawa"],["بِهِ","[ia]"],["ٱلسِّحْرُ ۖ","(ialah) sihir"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["سَيُبْطِلُهُۥٓ ۖ","akan membatalkannya"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يُصْلِحُ","meminda"],["عَمَلَ","kerja itu"],["ٱلْمُفْسِدِينَ","(dari) para perasuah"]]],"1446":["(Dan Allah akan mengukuhkan) meneguhkan dan memenangkan (yang benar dengan kalimat-kalimat-Nya) yakni janji-janji-Nya (walaupun orang-orang yang berbuat dosa tidak menyukainya.)",[["وَيُحِقُّ","Dan Allah akan menetapkan"],["ٱللَّهُ","Dan Allah akan menetapkan"],["ٱلْحَقَّ","kebenaran"],["بِكَلِمَـٰتِهِۦ","dengan firman-Nya"],["وَلَوْ","walaupun"],["كَرِهَ","tidak menyukainya"],["ٱلْمُجْرِمُونَ","penjenayah"]]],"1447":["(Maka tidak ada yang beriman kepada Musa melainkan pemuda-pemuda) segolongan orang (dari) anak-anak (kaumnya) kaumnya Firaun (dalam keadaan takut bahwa Firaun dan pemuka-pemuka kaumnya akan menyiksa mereka.) dalam upayanya untuk memalingkan mereka dari agama Nabi Musa melalui siksaan (Sesungguhnya Firaun itu berbuat sewenang-wenang) berlaku sombong (di muka bumi.) negeri Mesir (Dan sesungguhnya dia termasuk orang-orang yang melampaui batas) dia sudah sangat keterlaluan karena mengaku menjadi tuhan.",[["فَمَآ","Tetapi tiada"],["ءَامَنَ","beriman"],["لِمُوسَىٰٓ","Musa"],["إِلَّا","kecuali"],["ذُرِّيَّةٌۭ","(the) zuriat"],["مِّن","antara"],["قَوْمِهِۦ","umatnya"],["عَلَىٰ","bagi"],["خَوْفٍۢ","bertakwa"],["مِّن","daripada"],["فِرْعَوْنَ","Firaun"],["وَمَلَإِي۟هِمْ","dan ketua-ketua mereka"],["أَن","jangan-jangan"],["يَفْتِنَهُمْ ۚ","mereka menganiaya mereka"],["وَإِنَّ","Dan sesungguhnya"],["فِرْعَوْنَ","Firaun"],["لَعَالٍۢ","(adalah) seorang yang zalim"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَإِنَّهُۥ","dan sesungguhnya, dia"],["لَمِنَ","(adalah) daripada"],["ٱلْمُسْرِفِينَ","mereka yang melakukan keterlaluan"]]],"1448":["(Berkata Musa, \"Hai kaumku! Jika kalian beriman kepada Allah, maka bertawakallah kepada-Nya saja jika kalian benar-benar orang-orang yang berserah diri.\")",[["وَقَالَ","Dan Musa berkata"],["مُوسَىٰ","Dan Musa berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["إِن","Jika"],["كُنتُمْ","kamu ada"],["ءَامَنتُم","beriman"],["بِٱللَّهِ","kepada Allah"],["فَعَلَيْهِ","kemudian pada-Nya"],["تَوَكَّلُوٓا۟","letak amanah"],["إِن","jika"],["كُنتُم","kamu"],["مُّسْلِمِينَ","orang Islam"]]],"1449":["(Lalu mereka berkata, \"Kepada Allahlah kami bertawakal. Ya Rabb kami! Janganlah Engkau jadikan kami sasaran fitnah bagi kaum yang zalim) artinya janganlah Engkau membuat mereka menang atas diri kami sehingga mereka menduga bahwa mereka berada dalam jalan yang benar lalu mereka berani menyiksa kami.",[["فَقَالُوا۟","Kemudian mereka berkata"],["عَلَى","selepas"],["ٱللَّهِ","Allah"],["تَوَكَّلْنَا","kami meletakkan kepercayaan kami"],["رَبَّنَا","Wahai Tuhan kami"],["لَا","Jangan"],["تَجْعَلْنَا","buat kita"],["فِتْنَةًۭ","perbicaraan"],["لِّلْقَوْمِ","untuk rakyat"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"1450":["(Dan selamatkanlah kami dengan rahmat Engkau dari tipu daya orang-orang kafir.\")",[["وَنَجِّنَا","Dan selamatkan kami"],["بِرَحْمَتِكَ","dengan rahmatMu"],["مِنَ","daripada"],["ٱلْقَوْمِ","rakyat"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"1451":["(Dan Kami wahyukan kepada Musa dan saudaranya, \"Ambillah oleh kamu berdua) tempatilah oleh kamu berdua (beberapa buah rumah di Mesir untuk tempat tinggal bagi kaummu dan jadikanlah olehmu rumah-rumah itu tempat untuk salat) sebagai mushalla tempat kalian melakukan salat di dalamnya supaya kalian merasa aman dari ketakutan, dan tersebutlah bahwa Firaun melarang mereka melakukan salat (dan dirikanlah oleh kalian salat) sempurnakanlah salat itu oleh kalian (serta gembirakanlah orang-orang yang beriman.\") bahwa mereka akan mendapatkan pertolongan dan surga.",[["وَأَوْحَيْنَآ","Dan Kami ilhamkan"],["إِلَىٰ","kepada"],["مُوسَىٰ","Musa"],["وَأَخِيهِ","dan abangnya"],["أَن","bahawa"],["تَبَوَّءَا","Settle"],["لِقَوْمِكُمَا","orang kamu"],["بِمِصْرَ","di Mesir"],["بُيُوتًۭا","(dalam) rumah"],["وَٱجْعَلُوا۟","dan buat"],["بُيُوتَكُمْ","rumah-rumah kamu"],["قِبْلَةًۭ","(sebagai) tempat ibadat"],["وَأَقِيمُوا۟","dan menubuhkan"],["ٱلصَّلَوٰةَ ۗ","solat"],["وَبَشِّرِ","Dan sampaikanlah berita gembira"],["ٱلْمُؤْمِنِينَ","(kepada) orang-orang yang beriman"]]],"1452":["(Musa berkata, \"Ya Rabb kami! Sesungguhnya Engkau telah memberi kepada Firaun dan pemuka-pemuka kaumnya perhiasan dan harta kekayaan dalam kehidupan dunia. Ya Rabb kami) Engkau telah memberikan mereka hal-hal tersebut (yang akhirnya mereka menyesatkan) pada kesudahannya mereka menyesatkan manusia (dari jalan Engkau) agama Engkau. (Ya Rabb kami, binasakanlah harta benda mereka) lenyapkanlah harta benda mereka (dan kunci matilah hati mereka) artinya tutuplah rapat-rapat hati mereka (maka mereka tidak beriman hingga mereka melihat siksaan yang pedih) yang menyakitkan. Nabi Musa berdoa mengutuk Firaun dan pemuka-pemuka kaumnya, sedangkan Nabi Harun mengamini doanya.",[["وَقَالَ","Dan Musa berkata"],["مُوسَىٰ","Dan Musa berkata"],["رَبَّنَآ","Wahai Tuhan kami"],["إِنَّكَ","Sesungguhnya, Engkau"],["ءَاتَيْتَ","telah memberi"],["فِرْعَوْنَ","Firaun"],["وَمَلَأَهُۥ","dan ketua-ketuanya"],["زِينَةًۭ","kemegahan"],["وَأَمْوَٰلًۭا","dan kekayaan"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا","dunia"],["رَبَّنَا","Wahai Tuhan kami"],["لِيُضِلُّوا۟","Supaya mereka tersesat"],["عَن","daripada"],["سَبِيلِكَ ۖ","cara kamu"],["رَبَّنَا","Wahai Tuhan kami"],["ٱطْمِسْ","musnah"],["عَلَىٰٓ","[pada]"],["أَمْوَٰلِهِمْ","kekayaan mereka"],["وَٱشْدُدْ","dan mengeras"],["عَلَىٰ","[pada]"],["قُلُوبِهِمْ","hati mereka"],["فَلَا","jadi (itu) tidak"],["يُؤْمِنُوا۟","mereka beriman"],["حَتَّىٰ","sehingga"],["يَرَوُا۟","mereka lihat"],["ٱلْعَذَابَ","hukuman itu"],["ٱلْأَلِيمَ","yang menyakitkan"]]],"1453":["(Allah berfirman,) Maha Tinggi Allah (\"Sesungguhnya telah diperkenankan permohonan kamu berdua) akhirnya harta benda milik Firaun diserapah menjadi batu, dan Firaun masih tetap belum mau beriman hingga ia mati tenggelam (sebab itu tetaplah kamu berdua pada jalan yang lurus) menunaikan risalah dan dakwah sampai datang azab atas mereka (dan janganlah sekali-kali kamu mengikuti jalan orang-orang yang tidak mengetahui\") bahwa keputusan-Ku akan disegerakan. Diriwayatkan bahwa setelah peristiwa itu Nabi Musa tinggal di negeri Mesir selama empat puluh tahun.",[["قَالَ","Dia berkata"],["قَدْ","Sesungguhnya"],["أُجِيبَت","telah dijawab"],["دَّعْوَتُكُمَا","(seruan) kamu berdua"],["فَٱسْتَقِيمَا","Jadi kamu berdua (terus ke) jalan yang lurus"],["وَلَا","Dan jangan"],["تَتَّبِعَآنِّ","ikut"],["سَبِيلَ","jalan"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"1454":["(Dan Kami memungkinkan Bani Israel melintasi laut lalu mereka diikuti) disusul dan dikejar (oleh Firaun dan bala tentaranya, karena hendak menganiaya dan menindas) mereka, lafal baghyan dan `adwan menjadi maf'ul lah (hingga bila Firaun itu telah hampir tenggelam berkata dia, \"Saya percaya bahwa) bahwasanya; dan menurut suatu qiraat lafal annahu dibaca innahu sebagai jumlah isti'naf (tidak ada Tuhan melainkan Tuhan yang dipercayai oleh Bani Israil, dan saya termasuk orang-orang yang berserah diri.\") Firaun sengaja mengulang-ulang perkataannya itu supaya diterima oleh Allah, akan tetapi Allah tidak mau menerimanya. Kemudian malaikat Jibril menyumbat mulutnya dengan lumpur laut, karena merasa khawatir Firaun akan mendapatkan rahmat dari Allah. Lalu Allah berfirman kepadanya:",[["۞ وَجَـٰوَزْنَا","Dan Kami menyeberang"],["بِبَنِىٓ","(the) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["ٱلْبَحْرَ","laut"],["فَأَتْبَعَهُمْ","dan mengikuti mereka"],["فِرْعَوْنُ","Firaun"],["وَجُنُودُهُۥ","dan tuan rumahnya"],["بَغْيًۭا","(dalam) pemberontakan"],["وَعَدْوًا ۖ","dan permusuhan"],["حَتَّىٰٓ","sehingga"],["إِذَآ","apabila"],["أَدْرَكَهُ","mendahuluinya"],["ٱلْغَرَقُ","yang lemas"],["قَالَ","dia berkata"],["ءَامَنتُ","aku beriman"],["أَنَّهُۥ","bahawa"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["ٱلَّذِىٓ","yang Satu"],["ءَامَنَتْ","kepada siapa beriman"],["بِهِۦ","kepada siapa beriman"],["بَنُوٓا۟","Bani Israil"],["إِسْرَٰٓءِيلَ","Bani Israil"],["وَأَنَا۠","dan aku"],["مِنَ","daripada"],["ٱلْمُسْلِمِينَ","kaum muslimin"]]],"1455":["(Apakah sekarang) baru kamu percaya (padahal sesungguhnya kamu telah durhaka sejak dahulu, dan kamu termasuk orang-orang yang berbuat kerusakan) karena kesesatanmu dan penyesatan yang kamu lakukan dari jalan keimanan.",[["ءَآلْـَٔـٰنَ","Sekarang"],["وَقَدْ","Dan sesungguhnya"],["عَصَيْتَ","kamu (telah) menderhaka"],["قَبْلُ","sebelum"],["وَكُنتَ","dan kamu adalah"],["مِنَ","daripada"],["ٱلْمُفْسِدِينَ","para perasuah"]]],"1456":["(Maka pada hari ini Kami selamatkan) Kami keluarkan dari laut (badanmu) jasadmu yang sudah tidak bernyawa (supaya kamu dijadikan oleh orang-orang yang datang sesudahmu) generasi sesudahmu (sebagai pelajaran) bahan pelajaran, sehingga mereka mengetahui sifat kehambaanmu. Dengan demikian mereka tidak akan berani lagi melakukan perbuatan seperti yang pernah dilakukan olehmu. Ibnu Abbas r.a. menceritakan, bahwa sebagian orang-orang Bani Israel merasa ragu-ragu akan kematian Firaun, maka dikeluarkan-Nyalah mayat Firaun dari laut supaya mereka melihat dan menyaksikannya dengan mata kepala sendiri (dan sesungguhnya kebanyakan dari manusia) penduduk Mekah (lengah dari tanda-tanda kekuasaan-Ku) artinya mereka tidak mau mengambil pelajaran daripadanya.",[["فَٱلْيَوْمَ","Jadi hari ini"],["نُنَجِّيكَ","Kami akan menyelamatkan kamu"],["بِبَدَنِكَ","dalam badan kamu"],["لِتَكُونَ","bahawa kamu mungkin"],["لِمَنْ","untuk (mereka) yang"],["خَلْفَكَ","berjayakan kamu"],["ءَايَةًۭ ۚ","satu tanda"],["وَإِنَّ","Dan sesungguhnya"],["كَثِيرًۭا","ramai"],["مِّنَ","antara"],["ٱلنَّاسِ","umat manusia"],["عَنْ","daripada"],["ءَايَـٰتِنَا","Tanda-Tanda Kami"],["لَغَـٰفِلُونَ","(adalah) pasti lalai"]]],"1457":["(Dan sesungguhnya Kami telah menempatkan) memberikan tempat (Bani Israel di tempat kediaman yang bagus) tempat yang terhormat, yaitu negeri Syam dan negeri Mesir (dan Kami beri mereka rezeki dari yang baik-baik. Maka mereka tidak berselisih) sekalipun sebagian di antara mereka beriman dan sebagian yang lain kafir (kecuali setelah datang kepada mereka pengetahuan, yang tersebut dalam Taurat. Sesungguhnya Rabb kamu akan memutuskan antara mereka di hari kiamat tentang apa yang mereka perselisihkan itu) dalam masalah agama, yaitu dengan menyelamatkan orang-orang beriman dan mengazab orang-orang kafir.",[["وَلَقَدْ","Dan sesungguhnya"],["بَوَّأْنَا","Kami settle"],["بَنِىٓ","(the) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["مُبَوَّأَ","(dalam) penempatan"],["صِدْقٍۢ","terhormat"],["وَرَزَقْنَـٰهُم","dan Kami beri mereka rezeki"],["مِّنَ","dengan"],["ٱلطَّيِّبَـٰتِ","perkara yang baik"],["فَمَا","dan bukan"],["ٱخْتَلَفُوا۟","mereka berbeza"],["حَتَّىٰ","sehingga"],["جَآءَهُمُ","datang kepada mereka"],["ٱلْعِلْمُ ۚ","pengetahuan itu"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["يَقْضِى","akan menilai"],["بَيْنَهُمْ","antara mereka"],["يَوْمَ","(pada) hari itu"],["ٱلْقِيَـٰمَةِ","Kiamat"],["فِيمَا","berkenaan apa"],["كَانُوا۟","mereka pernah (untuk)"],["فِيهِ","[di dalamnya]"],["يَخْتَلِفُونَ","berbeza"]]],"1458":["(Maka jika kamu) hai Muhammad (berada dalam keragu-raguan tentang apa yang Kami turunkan kepadamu) yaitu berupa kisah-kisah, seumpamanya (maka tanyakanlah kepada orang-orang yang telah membaca kitab) Taurat (sebelum kamu) maka sesungguhnya hal itu telah tertera di dalam kitab mereka, mereka akan memberitakannya kepadamu sesuai dengannya; untuk itu maka Rasulullah saw. bersabda, \"Aku tidak ragu dan tidak menanyakannya.\" (Sesungguhnya telah datang kebenaran kepadamu dari Rabbmu, sebab itu janganlah sekali-kali kamu termasuk orang-orang yang ragu) menaruh keraguan padanya.",[["فَإِن","Jadi jika"],["كُنتَ","kamu"],["فِى","dalam"],["شَكٍّۢ","keraguan"],["مِّمَّآ","tentang apa"],["أَنزَلْنَآ","Kami telah mendedahkan"],["إِلَيْكَ","kepada kamu"],["فَسْـَٔلِ","kemudian bertanya"],["ٱلَّذِينَ","orang yang"],["يَقْرَءُونَ","(telah) membaca"],["ٱلْكِتَـٰبَ","Kitab"],["مِن","sebelum kamu"],["قَبْلِكَ ۚ","sebelum kamu"],["لَقَدْ","Sesungguhnya"],["جَآءَكَ","telah datang kepada kamu"],["ٱلْحَقُّ","kebenaran"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["فَلَا","jadi (jangan)"],["تَكُونَنَّ","jadilah"],["مِنَ","antara"],["ٱلْمُمْتَرِينَ","orang-orang yang ragu-ragu"]]],"1459":["(Dan sekali-kali janganlah kamu termasuk orang-orang yang mendustakan ayat-ayat Allah yang menyebabkan kamu termasuk orang-orang yang rugi).",[["وَلَا","Dan jangan"],["تَكُونَنَّ","jadilah"],["مِنَ","daripada"],["ٱلَّذِينَ","orang yang"],["كَذَّبُوا۟","menafikan"],["بِـَٔايَـٰتِ","(tanda-tanda) Allah"],["ٱللَّهِ","(tanda-tanda) Allah"],["فَتَكُونَ","maka kamu akan menjadi"],["مِنَ","antara"],["ٱلْخَـٰسِرِينَ","yang rugi"]]],"1460":["(Sesungguhnya orang-orang yang telah pasti) telah dipastikan (terhadap mereka kalimat Rabbmu) yaitu azab Allah telah pasti atas mereka (tidaklah akan beriman).",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","mereka [yang]"],["حَقَّتْ","telah menjadi wajar"],["عَلَيْهِمْ","ke atas mereka"],["كَلِمَتُ","(the) Firman"],["رَبِّكَ","Tuhanmu"],["لَا","tidak akan"],["يُؤْمِنُونَ","beriman"]]],"1461":["(Meskipun datang kepada mereka segala macam keterangan hingga mereka menyaksikan azab yang pedih) maka pada saat itu tidak bermanfaat lagi keimanan mereka.",[["وَلَوْ","Walaupun"],["جَآءَتْهُمْ","datang kepada mereka"],["كُلُّ","setiap"],["ءَايَةٍ","Tanda"],["حَتَّىٰ","sehingga"],["يَرَوُا۟","mereka lihat"],["ٱلْعَذَابَ","hukuman itu"],["ٱلْأَلِيمَ","yang menyakitkan"]]],"1462":["(Dan mengapa tidak) hendaknyalah (ada suatu kota) yakni penduduknya (yang beriman) sebelum azab turun atas mereka (lalu imannya itu bermanfaat kepadanya selain kaum Yunus. Tatkala mereka beriman) yaitu sewaktu mereka melihat adanya tanda-tanda azab lalu mereka segera beriman sebelum azab diturunkan atas diri mereka (Kami hilangkan dari mereka azab yang menghinakan dalam kehidupan dunia dan Kami beri kesenangan kepada mereka sampai pada waktu yang tertentu) sampai ajal mereka tiba.",[["فَلَوْلَا","Jadi kenapa tidak"],["كَانَتْ","adalah"],["قَرْيَةٌ","mana-mana bandar"],["ءَامَنَتْ","yang beriman"],["فَنَفَعَهَآ","dan mendapat manfaatnya"],["إِيمَـٰنُهَآ","imannya"],["إِلَّا","kecuali"],["قَوْمَ","manusia"],["يُونُسَ","(dari) Yunus"],["لَمَّآ","Apabila"],["ءَامَنُوا۟","mereka beriman"],["كَشَفْنَا","Kami mengeluarkan"],["عَنْهُمْ","daripada mereka"],["عَذَابَ","azab"],["ٱلْخِزْىِ","(dari) kehinaan itu"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا","dunia"],["وَمَتَّعْنَـٰهُمْ","dan Kami beri mereka kesenangan"],["إِلَىٰ","bagi"],["حِينٍۢ","suatu masa"]]],"1463":["(Dan jika Rabbmu menghendaki tentulah beriman semua orang yang di muka bumi seluruhnya. Maka apakah kamu hendak memaksa manusia) terhadap apa yang Allah tidak kehendaki mereka untuk melakukannya (supaya mereka menjadi orang-orang yang beriman semuanya?) tentu saja tidak.",[["وَلَوْ","Dan jika"],["شَآءَ","(telah) berkehendak"],["رَبُّكَ","Tuhanmu"],["لَـَٔامَنَ","nescaya (akan) beriman"],["مَن","yang"],["فِى","(ada) dalam"],["ٱلْأَرْضِ","bumi"],["كُلُّهُمْ","kesemuanya"],["جَمِيعًا ۚ","bersama-sama"],["أَفَأَنتَ","Kemudian, adakah kamu"],["تُكْرِهُ","memaksa"],["ٱلنَّاسَ","umat manusia"],["حَتَّىٰ","sehingga"],["يَكُونُوا۟","mereka menjadi"],["مُؤْمِنِينَ","orang yang beriman"]]],"1464":["(Dan tidak ada seorang pun akan beriman kecuali dengan izin Allah) dengan kehendak-Nya (dan Allah menimpakan kemurkaan) azab-Nya (kepada orang-orang yang tidak mempergunakan akalnya) yaitu orang-orang yang tidak mau memikirkan ayat-ayat Allah.",[["وَمَا","Dan tidak"],["كَانَ","ialah"],["لِنَفْسٍ","untuk jiwa"],["أَن","kepada"],["تُؤْمِنَ","beriman"],["إِلَّا","kecuali"],["بِإِذْنِ","dengan izin (yang)"],["ٱللَّهِ ۚ","(milik) Allah"],["وَيَجْعَلُ","Dan Dia akan meletakkan"],["ٱلرِّجْسَ","kemarahan itu"],["عَلَى","pada"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يَعْقِلُونَ","guna akal"]]],"1465":["(Katakanlah,) kepada orang-orang kafir Mekah (\"Perhatikanlah apa) apa-apa (yang ada di langit dan di bumi) yaitu tanda-tanda yang menunjukkan akan keesaan Allah swt. (Tidaklah bermanfaat tanda kekuasaan Allah dan rasul-rasul yang memberi peringatan) lafal an-nudzur adalah bentuk jamak dari kata tunggal nadzir yang artinya para rasul (bagi orang-orang yang tidak beriman.\") yang hal ini diketahui oleh Allah swt. atau dengan kata lain, hal-hal tersebut tidak ada manfaatnya bagi mereka.",[["قُلِ","Katakanlah"],["ٱنظُرُوا۟","Lihat"],["مَاذَا","apa"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["وَمَا","Tetapi tidak"],["تُغْنِى","akan mendapat manfaat"],["ٱلْـَٔايَـٰتُ","Tanda-tanda"],["وَٱلنُّذُرُ","dan pemberi amaran"],["عَن","kepada"],["قَوْمٍۢ","suatu kaum"],["لَّا","(yang melakukannya) tidak"],["يُؤْمِنُونَ","beriman"]]],"1466":["(Tiada) tidak ada (yang mereka tunggu-tunggu) dengan perbuatan mereka yang mendustakan kamu (melainkan kejadian-kejadian yang sama dengan kejadian-kejadian yang menimpa orang-orang terdahulu sebelum mereka) umat-umat terdahulu. Artinya, mereka akan tertimpa siksaan yang sama seperti siksaan yang menimpa umat-umat terdahulu (Katakanlah, \"Maka tunggulah) hal tersebut (sesungguhnya aku pun orang yang menunggu bersama kalian.\")",[["فَهَلْ","Kemudian lakukan"],["يَنتَظِرُونَ","mereka menunggu"],["إِلَّا","kecuali"],["مِثْلَ","suka"],["أَيَّامِ","hari-hari"],["ٱلَّذِينَ","orang yang"],["خَلَوْا۟","meninggal dunia"],["مِن","sebelum mereka"],["قَبْلِهِمْ ۚ","sebelum mereka"],["قُلْ","Katakanlah"],["فَٱنتَظِرُوٓا۟","Kemudian tunggu"],["إِنِّى","sesungguhnya, aku (adalah)"],["مَعَكُم","bersama kamu"],["مِّنَ","antara"],["ٱلْمُنتَظِرِينَ","mereka yang menunggu"]]],"1467":["(Kemudian Kami selamatkan) bentuk mudhari' di sini dimaksud untuk menceritakan keadaan di masa lampau (rasul-rasul Kami dan orang-orang yang beriman) dari azab (demikianlah) penyelamatan itu (menjadi kewajiban atas Kami menyelamatkan orang-orang yang beriman) Nabi dan para sahabatnya ketika orang-orang musyrik disiksa.",[["ثُمَّ","Kemudian"],["نُنَجِّى","Kami akan jimat"],["رُسُلَنَا","Rasul-rasul Kami"],["وَٱلَّذِينَ","dan orang yang"],["ءَامَنُوا۟ ۚ","beriman"],["كَذَٰلِكَ","Demikianlah"],["حَقًّا","(ia adalah) satu kewajipan"],["عَلَيْنَا","atas Kami"],["نُنجِ","(yang) Kami simpan"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"1468":["(Katakanlah, \"Hai manusia) hai penduduk Mekah! (Jika kalian masih dalam keragu-raguan tentang agamaku) bahwasanya agamaku itu adalah hak dan benar (maka ketahuilah aku tidak menyembah yang kalian sembah selain Allah) selain-Nya, yang dimaksud adalah berhala-berhala; hal ini merupakan pertanda bahwa kalian ragu-ragu terhadap agamaku (tetapi aku menyembah Allah yang akan mematikan kalian) yang akan mencabut ruh kalian (dan aku telah diperintah supaya) hendaknya (aku termasuk orang-orang yang beriman.\")",[["قُلْ","Katakanlah"],["يَـٰٓأَيُّهَا","Wahai umat manusia"],["ٱلنَّاسُ","Wahai umat manusia"],["إِن","Jika"],["كُنتُمْ","kamu"],["فِى","dalam"],["شَكٍّۢ","keraguan"],["مِّن","daripada"],["دِينِى","agama aku"],["فَلَآ","maka tidak"],["أَعْبُدُ","aku menyembah"],["ٱلَّذِينَ","mereka yang"],["تَعْبُدُونَ","kamu menyembah"],["مِن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["وَلَـٰكِنْ","tetapi"],["أَعْبُدُ","aku menyembah"],["ٱللَّهَ","Allah"],["ٱلَّذِى","yang Esa"],["يَتَوَفَّىٰكُمْ ۖ","menyebabkan kamu mati"],["وَأُمِرْتُ","Dan aku diperintahkan"],["أَنْ","bahawa"],["أَكُونَ","aku jadi"],["مِنَ","daripada"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"1469":["(Dan) aku diperintahkan (\"Hadapkanlah mukamu kepada agama dengan tulus dan ikhlas) dalam keadaan cenderung dan menggandrunginya (dan janganlah kamu termasuk orang-orang yang musyrik).",[["وَأَنْ","Dan bahawa"],["أَقِمْ","Langsung"],["وَجْهَكَ","muka kamu"],["لِلدِّينِ","kepada agama"],["حَنِيفًۭا","tegak"],["وَلَا","dan jangan"],["تَكُونَنَّ","jadilah"],["مِنَ","daripada"],["ٱلْمُشْرِكِينَ","orang musyrik"]]],"1470":["(Dan janganlah kamu menyeru) menyembah (kepada selain Allah, yaitu apa-apa yang tidak dapat memberikan manfaat kepadamu) jika kamu menyembahnya (dan pula tidak dapat memberikan mudarat kepadamu) jika kamu tidak menyembahnya (sebab jika kamu berbuat) hal itu, umpamanya (maka sesungguhnya kamu kalau begitu termasuk orang-orang yang lalim.\")",[["وَلَا","Dan jangan"],["تَدْعُ","menyeru"],["مِن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["مَا","apa"],["لَا","(akan) tidak"],["يَنفَعُكَ","memberi manfaat kepada kamu"],["وَلَا","dan bukan"],["يَضُرُّكَ ۖ","membahayakan kamu"],["فَإِن","Tetapi jika"],["فَعَلْتَ","kamu berbuat demikian"],["فَإِنَّكَ","sesungguhnya, kamu"],["إِذًۭا","maka (akan)"],["مِّنَ","daripada"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"1471":["(Jika Allah menimpakan kepadamu) mengenakan kepadamu (sesuatu kemudaratan) seperti kemiskinan dan sakit (maka tidak ada yang dapat menghilangkan) yang melenyapkan (hal itu kecuali Dia. Dan jika Allah menghendaki kebaikan bagi kamu, maka tak ada yang dapat menolak) menahan (karunia-Nya) yang telah Dia kehendaki buatmu (Dia memberikan hal itu) kebaikan itu (kepada siapa yang dikehendaki-Nya di antara hamba-hamba-Nya dan Dialah Yang Maha Pengampun lagi Maha Penyayang.)",[["وَإِن","Dan jika"],["يَمْسَسْكَ","Allah sentuh kamu"],["ٱللَّهُ","Allah sentuh kamu"],["بِضُرٍّۢ","dengan kesusahan"],["فَلَا","(ada) tidak"],["كَاشِفَ","penghilang"],["لَهُۥٓ","daripadanya"],["إِلَّا","kecuali"],["هُوَ ۖ","Dia"],["وَإِن","dan jika"],["يُرِدْكَ","Dia berniat untuk kamu"],["بِخَيْرٍۢ","apa-apa kebaikan"],["فَلَا","maka (ada) tidak"],["رَآدَّ","repeller"],["لِفَضْلِهِۦ ۚ","(dari) karunia-Nya"],["يُصِيبُ","Dia menyebabkan ia mencapai"],["بِهِۦ","Dia menyebabkan ia mencapai"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["مِنْ","daripada"],["عِبَادِهِۦ ۚ","hambanya"],["وَهُوَ","Dan Dia"],["ٱلْغَفُورُ","(ialah) Yang Maha Pengampun"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"1472":["(Katakanlah, \"Hai manusia) yakni penduduk Mekah! (Sesungguhnya telah datang kepada kalian kebenaran dari Rabb kalian, sebab itu barang siapa yang mendapat petunjuk maka sesungguhnya petunjuk itu untuk kebaikan dirinya.) karena sesungguhnya pahala hidayahnya itu hanya dialah yang berhak menerimanya (Dan barang siapa yang sesat maka sesungguhnya kesesatannya itu untuk kecelakaan dirinya sendiri) karena akibat kesesatannya itu akan menimpa dirinya sendiri (Dan aku bukanlah seorang penjaga terhadap diri kalian.\") karenanya bagaimana aku akan memaksakan kepada kalian untuk mengikuti petunjuk.",[["قُلْ","Katakanlah"],["يَـٰٓأَيُّهَا","Wahai umat manusia"],["ٱلنَّاسُ","Wahai umat manusia"],["قَدْ","Sesungguhnya"],["جَآءَكُمُ","telah datang kepada kamu"],["ٱلْحَقُّ","kebenaran"],["مِن","daripada"],["رَّبِّكُمْ ۖ","Tuhanmu"],["فَمَنِ","Jadi sesiapa"],["ٱهْتَدَىٰ","(adalah) dibimbing"],["فَإِنَّمَا","kemudian sahaja"],["يَهْتَدِى","(dia) mendapat petunjuk"],["لِنَفْسِهِۦ ۖ","untuk jiwanya"],["وَمَن","dan sesiapa"],["ضَلَّ","sesat"],["فَإِنَّمَا","kemudian sahaja"],["يَضِلُّ","dia sesat"],["عَلَيْهَا ۖ","menentangnya"],["وَمَآ","Dan aku tidak"],["أَنَا۠","Dan aku tidak"],["عَلَيْكُم","atas kamu"],["بِوَكِيلٍۢ","seorang penjaga"]]],"1473":["(Dan ikutilah apa yang diwahyukan kepadamu) dari Rabbmu (dan bersabarlah) di dalam berdakwah dan menghadapi permusuhan mereka (hingga Allah memberi keputusan) terhadap mereka dengan perintah-Nya (dan Dia adalah hakim yang sebaik-baiknya) hakim yang paling adil. Ternyata Nabi saw. bersabar di dalam menghadapi kesemuanya itu, hingga Allah memberikan keputusan terhadap orang-orang musyrik, yaitu dengan memerintahkan supaya mereka diperangi dan bagi ahli Kitab supaya ditarik jizyah/upeti.",[["وَٱتَّبِعْ","Dan ikut"],["مَا","apa"],["يُوحَىٰٓ","didedahkan"],["إِلَيْكَ","kepada kamu"],["وَٱصْبِرْ","dan bersabarlah"],["حَتَّىٰ","sehingga"],["يَحْكُمَ","Allah memberi penghakiman"],["ٱللَّهُ ۚ","Allah memberi penghakiman"],["وَهُوَ","Dan Dia"],["خَيْرُ","(adalah) yang Terbaik"],["ٱلْحَـٰكِمِينَ","(dari) para Hakim"]]],"1474":["(Alif laam raa) hanya Allahlah yang mengetahui maksudnya; inilah (suatu Kitab yang ayat-ayatnya disusun dengan rapi) hal ini tampak pada susunan ayat-ayatnya yang memukau dan keindahan makna-maknanya (serta dijelaskan secara rinci) yang kandungannya menjelaskan tentang hukum-hukum, kisah-kisah dan nasihat-nasihat (yang diturunkan dari sisi Yang Maha Bijaksana lagi Maha Waspada) yaitu Allah.",[["الٓر ۚ","Alif Lam Ra"],["كِتَـٰبٌ","(Ini adalah) sebuah Kitab"],["أُحْكِمَتْ","disempurnakan"],["ءَايَـٰتُهُۥ","Ayat-ayatnya"],["ثُمَّ","lebih-lebih lagi"],["فُصِّلَتْ","dijelaskan secara terperinci"],["مِن","daripada (Dia Yang)"],["لَّدُنْ","daripada (Dia Yang)"],["حَكِيمٍ","(adalah) Maha Bijaksana"],["خَبِيرٍ","Maha Mengetahui"]]],"1475":["(agar) supaya (kalian tidak menyembah selain Allah. Sesungguhnya aku, Muhammad, adalah pemberi peringatan kepada kalian dari-Nya) yaitu dengan azab jika kalian berbuat kekafiran (dan pembawa berita gembira) dengan pahala jika kalian beriman.",[["أَلَّا","Itu \"Tidak"],["تَعْبُدُوٓا۟","kamu menyembah"],["إِلَّا","tetapi"],["ٱللَّهَ ۚ","Allah"],["إِنَّنِى","Memang aku"],["لَكُم","kepada kamu"],["مِّنْهُ","daripadaNya"],["نَذِيرٌۭ","seorang pemberi amaran"],["وَبَشِيرٌۭ","dan pembawa berita gembira"]]],"1476":["(Dan hendaklah kalian meminta ampun kepada Rabb kalian) dari kemusyrikan (dan bertobatlah kalian) kembalilah kalian (kepada-Nya) dengan menjalankan ketaatan (niscaya Dia akan memberi kenikmatan kepada kalian) di dunia (dengan kenikmatan yang baik) dengan kehidupan yang baik dan rezeki yang banyak (sampai pada waktu yang telah ditentukan) yaitu mati (dan Dia akan memberi) kelak di akhirat (kepada tiap-tiap orang yang mempunyai keutamaan) di dalam beramal (keutamaannya) yakni balasannya (Dan jika kalian berpaling) lafal tawallau pada asalnya adalah tatawallau kemudian salah satu dari dua huruf ta dibuang sehingga jadilah tawallau, artinya berpaling (maka sesungguhnya aku takut kalian akan ditimpa siksa di hari kiamat) yaitu hari akhir.",[["وَأَنِ","Dan bahawa"],["ٱسْتَغْفِرُوا۟","Minta ampun"],["رَبَّكُمْ","Tuhanmu"],["ثُمَّ","dan"],["تُوبُوٓا۟","bertaubat"],["إِلَيْهِ","kepada-Nya"],["يُمَتِّعْكُم","Dia akan membenarkan kamu"],["مَّتَـٰعًا","nikmatilah"],["حَسَنًا","yang baik"],["إِلَىٰٓ","bagi"],["أَجَلٍۢ","satu istilah"],["مُّسَمًّۭى","dilantik"],["وَيُؤْتِ","Dan berikan"],["كُلَّ","(kepada) setiap"],["ذِى","pemilik"],["فَضْلٍۢ","(dari) rahmat"],["فَضْلَهُۥ ۖ","RahmatNya"],["وَإِن","Tetapi jika"],["تَوَلَّوْا۟","kamu berpaling"],["فَإِنِّىٓ","maka sesungguhnya, aku"],["أَخَافُ","bertakwa"],["عَلَيْكُمْ","bagi kamu"],["عَذَابَ","azab"],["يَوْمٍۢ","(pada) hari yang agung"],["كَبِيرٍ","(pada) hari yang agung"]]],"1477":["(Kepada Allahlah kembali kalian, dan Dia Maha Kuasa atas segala sesuatu) antara lain ialah memberi pahala dan menentukan azab.",[["إِلَى","Kepada"],["ٱللَّهِ","Allah"],["مَرْجِعُكُمْ ۖ","(adalah) kamu kembali"],["وَهُوَ","dan Dia"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌ","Maha Berkuasa"]]],"1478":["Ayat ini seperti yang diriwayatkan oleh Imam Bukhari melalui Ibnu Abbas r.a. diturunkan berkenaan dengan orang-orang yang merasa malu untuk membuang air besar atau merasa malu berjimak karena kemaluan mereka terlihat dari atas langit. Akan tetapi menurut pendapat yang lain dikatakan bahwa ayat ini diturunkan berkenaan dengan perihal orang-orang munafik (Ingatlah sesungguhnya orang-orang munafik itu memalingkan dada mereka untuk menyembunyikan diri daripada-Nya) daripada Allah (Ingatlah, di waktu mereka menyelimuti dirinya dengan kain) menutupi dirinya dengan kain (Allah mengetahui) Maha Tinggi Allah (apa yang mereka sembunyikan dan apa yang mereka lahirkan) sehingga sembunyi mereka tidak ada gunanya lagi (sesungguhnya Allah Maha Mengetahui segala isi hati) artinya Dia mengetahui semua apa yang ada di dalam hati.",[["أَلَآ","Tidak syak lagi"],["إِنَّهُمْ","mereka"],["يَثْنُونَ","lipat"],["صُدُورَهُمْ","buah dada mereka"],["لِيَسْتَخْفُوا۟","supaya mereka boleh bersembunyi"],["مِنْهُ ۚ","daripadaNya"],["أَلَا","pastinya"],["حِينَ","apabila"],["يَسْتَغْشُونَ","mereka menutupi (diri mereka sendiri)"],["ثِيَابَهُمْ","(dengan) pakaian mereka"],["يَعْلَمُ","Dia tahu"],["مَا","apa"],["يُسِرُّونَ","mereka sembunyikan"],["وَمَا","dan apa"],["يُعْلِنُونَ ۚ","mereka mendedahkan"],["إِنَّهُۥ","Sesungguhnya Dia"],["عَلِيمٌۢ","Maha Mengetahui"],["بِذَاتِ","tentang apa"],["ٱلصُّدُورِ","(ada dalam) buah dada"]]]});